import { ASTNodeType, AttributeClass, ASTNode, CompilationPhase,
	VariableDeclarationNode, CastExpression, ConditionalExpressionNode, NumericLiteralNode, StringLiteralNode,
	CharacterLiteralNode, NullLiteralNode, ASTVisitor, __convert, objectList,
	liquidList, unitList, buildingList,
	InitializerListNode,
	TypeSpecifierNode,
	DeclaratorNode,
	ASTBuilder
 } from "./mindcBase.js";
// `Instruction` used to be imported here and was never used; the entry needed
// at run time is `MemoryBlockInfo`, and it is a type name, so nothing here
// reads a binding from `mindcGeneratorBase.js` while this module's body runs.
import { MemoryBlockInfo } from "./mindcGeneratorBase.js";
import { widthOfType, normalizeImplementation } from "./mindcInfrastructure.js";

export class VariableLinker {
	/**
	 * 
	 * @param {string} variableName 
	 * @param {SymbolEntry} entry
	 */
	constructor(variableName, entry) {
		/**
		 * @type {VariableLinker[]}
		 */
		this.linked = [];
		/**
		 * @type {AttributeClass[]}
		 * 
		 * Nodes that prepare to delete something.
		 */
		this.prepared = [];
		/**
		 * @type {VariableLinker}
		 */
		this.parent = null;
		/**
		 * @type {string}
		 */
		this.name = variableName;
		this.rejecting = false;
		this.entry = entry;
	}

	/**
	 * 
	 * @param {VariableLinker} linker 
	 */
	linkTo(linker) {
		if (linker.rejecting) return;
		linker.linked.push(this);
		this.parent = linker;
	}

	invalidate() {
		this.parent = null;
		this.prepared.forEach(obj => void(obj.setAttribute('candidateRemoval', 0)));
		this.prepared = [];
	}

	unlink() {
		if (!this.parent) {
			return;
		}
		const index = this.parent.linked.indexOf(this);
		if (index != -1) {
			this.parent.linked.splice(index);
		}
		this.invalidate();
	}

	modify() {
		this.linked.forEach(obj => void(obj.invalidate()));
		this.linked = [];
		this.unlink();
	}

	/**
	 * 
	 * @returns {string}
	 */
	getName() {
		if (!this.parent) {
			return this.name;
		}
		return this.parent.getName();
	}

	/**
	 * 
	 * @param {AttributeClass} candidate 
	 */
	registerCandidate(candidate) {
		if (this.parent) {
			candidate.setAttribute('candidateRemoval', 2);
		} else {
			candidate.setAttribute('candidateRemoval', 0);
		}
		this.prepared.push(candidate);
	}
}

// 修改SymbolEntry类以存储更详细的类型信息
/**
 * @member {boolean} accessThroughPointer Indicating whether the variable should be accessed by a memory address (not necessarily be a pointer!)
 * @member {boolean} implementAsPointer Indicating whether the variable IS a pointer (or array, which is regarded as a pointer.)
 * @member {boolean} needMemoryAllocation
 */
export class SymbolEntry {
	/**
	 * 
	 * @param {string} name 
	 * @param {TypeInfo | string | {returnType: string, parameters: {name: string, type: string}[]}} type 
	 * @param {Scope | null} scope 
	 * @param {string} kind 
	 * @param {*} location 
	 * @param {number} size 
	 */
    constructor(name, type, scope, kind, location = null, size = null) {
        this.name = name;
        this.type = type; // 类型信息（现在是TypeInfo对象）
		this.size = size;	// Should be generated by compiler system
        this.scope = scope;
		this.owningScope = null;	// The scope that the function (if it points to one) owns
        this.kind = kind; // 'variable', 'function', 'parameter', 'type'
        this.location = location;
        this.initialized = false;
        this.used = false;
		// Unused:
		this.readCount = 0; // 读取次数
        this.writeCount = 0; // 写入次数
		// Unused end
	
		/**
		 * @type {MemoryBlockInfo?}
		 */
        this.memoryLocation = null;
		this.accessThroughPointer = false;	// In-memory variable, must be accessed through memory blocks
											// THIS ALSO MEANS THAT: you can and should always dereference it to get the real value
		this.implementAsPointer = (this.myType() instanceof TypeInfo && (this.myType().kind === 'pointer' || this.myType().kind === 'array'));
											// This is true will mean that when getting value, it will return a pointer
											// ACCORDING TO THAT DEFINITION, struct SHOULD BE "IMPLEMENTED AS POINTER"
											// instead of "ACCESS THROUGH POINTER"
		this.needMemoryAllocation = false;

		this.extraMemoryLocation = null;	// For variables having both access-through and implement-as, this will be the memory space where their value is placed.
		this.isExtraNear = false;			// This should be written by and only by code generator

		/**
		 * @type { {stackSymbols: SymbolEntry[], regStructMem: Map<string, string> }? }
		 */
		this.memberHandler = null;

		this.isAuto = false;
		this.isAutoDevice = false;	// Must be manually done!
		this.isVirtualSymbol = false;
		this.isRecursiveSymbol = false;
		// (for struct, union, pointer and array)

		// Following of these can be automatic sometimes
        this.isGlobal = false;
		this.isRegister = false; // 标记是否为register变量
		this.isStatic = (this.myType() instanceof TypeInfo) ? this.myType().isStatic() : false;
		this.isPersistent = (this.myType() instanceof TypeInfo) ? this.myType().isPersistent() : false;
		this.isExtern = (this.myType() instanceof TypeInfo) ? this.myType().isExtern() : false;
		this.isRemote = (this.myType() instanceof TypeInfo) ? this.myType().isRemote() : false;
		// Note: this is also available for functions:
		// (for functions, once 'true', it can't be inlined !)
        this.isAddressed = false; // 标记是否被取地址
		this.isConst = (this.myType() instanceof TypeInfo) ? this.myType().isConst() : false;
        this.isVolatile = (this.myType() instanceof TypeInfo) ? this.myType().isVolatile() : false;
		// 常量传播相关
        this.isConstant = false;
        this.constantValue = null;

		// Used for code generator
		this.isNearPointer = false;

		// Simple array means array satisfying the following conditions that can be converted into a
		// builtin array by default:
		// 1. The array is of simple object type (Note: in this case, device, content_t and null_t are also allowed)
		// volatile variables, struct/union, array and pointer are NOT simple object types.
		// 2. The array is never cast to pointer type (Note: function calls permitted.)
		// If an array is both simple array and constant array, further optimization can be done.
		// If the array is of device, content_t (or sometimes null_t) type, then simple array is A MUST.
		/**
		 * If the type is 'embedded', it works like pdlist / sdlist. If it requires shared feature (i.e. remote access),
		 * instead of using 'sdlist' there will be an additional library not working in the same way as this array
		 * as the method must be specified.
		 * 
		 * By using array_init(type, mutable, implement, {data...}) you are also allowed to manually specify the way 
		 * such thing is loaded.
		 * 
		 * @type {arrayStyle}
		 */
		this.arrayStyle = {
			type: 'traditional',
			mutable: true,
			implement: null
		};
        
        // 优化标记 [Not really used right away]
        this.canBeEliminated = false;
        this.isDead = false;

		// Optimizer tag used now
		this.variableReferrer = new VariableLinker(name, this);
    }
	
	// 标记为常量
    markAsConstant(value) {
        this.isConstant = true;
        this.constantValue = value;
		/*

		let typeRef = this.myType();
        if (typeRef && typeRef.qualifiers) {
            typeRef.qualifiers.push('const');
        }
			*/
    }

	/**
	 * 
	 * @returns {TypeInfo | null | {returnType: string; parameters: any[]}}
	 * @deprecated Use it only when you don't care about memory attributes.
	 */
	myType() {
		if (!this.type) return null;
		return this.type.type ? this.type.type : this.type;
	}

	isStructOrUnion() {
		if (!this.type) return false;
		const curType = this.myType();
		return curType.kind === 'struct' || curType.kind === 'union';
	}

	isBasic() {
		const curType = this.myType();
		return curType && curType.kind === 'basic';
	}

	isPointer() {
		return this.accessThroughPointer || this.implementAsPointer || this.needMemoryAllocation;
	}

	/**
	 * 
	 * @returns {boolean}
	 */
	requireExtraMemory() {
		return this.accessThroughPointer && this.myType().isTypeInfo && ['array', 'struct', 'union'].includes(this.myType().kind);
	}

	memoryRef() {
		return this.requireExtraMemory() ? this.extraMemoryLocation : this.memoryLocation;
	}

	/**
	 * In current version, a structure can't be regarded as `accessThroughPointer`.
	 * @returns {boolean}
	 */
	isRegistryStruct() {
		return this.isStructOrUnion() && !this.isPointer();
	}

	getAssemblySymbol() {
		if (this.isAutoDevice) {
			return this.name;
		}
		if (this.kind === 'function') {
			return '_' + this.name;
		}
		if (this.scope) {
			return this.scope.getPath() + "." + this.name;
		} else {
			return this.name;
		}
	}

	duplicate() {
		let result = new SymbolEntry(this.name, this.type, this.scope, this.kind);
		Object.assign(result, this);
		return result;
	}

	/**
	 * 
	 * @returns {TypeInfo}
	 * @throws
	 */
	extractType() {
		/**
		 * @type {TypeInfo}
		 */
		let resultType;
		if (this.kind !== 'function') {
			// Let it crash otherwise.
			resultType = this.myType().duplicate();
			// if (resultType.isTypeInfo) {
			/*
			Every conversion of the type used to push these again, so a type
			touched more than once ended up with `const const const`. Add each
			qualifier at most once.
			*/
			const withQualifier = name => {
				if (!resultType.qualifiers.includes(name)) resultType.qualifiers.push(name);
			};
			if (this.isAuto || this.isAutoDevice) withQualifier('auto');
			if (this.isRegister) withQualifier('register');
			if (this.isConst || resultType.isConst()) withQualifier('const');
			if (this.isVolatile || resultType.isVolatile()) withQualifier('volatile');
			if (this.isExtern) withQualifier('extern');
			if (this.isStatic) withQualifier('static');
			if (this.isPersistent) withQualifier('persistent');
			resultType.qualifiers = [...new Set(resultType.qualifiers)];
			// }	// I guess it should crash otherwise. If there's no judgment, it will
		} else {
			resultType = new TypeInfo(this.name, 'function', 1);
			resultType.functionTo = this;
		}
		return resultType;
	}

	isArray() {
		return this.extractType().kind === 'array';
	}

	describe() {
		return `${this.name}: ${
			(typeof this.type === 'object') ? this.extractType().toString() : `#${this.type}`} @ ${this.scope ? this.scope.getPath() : 'g'}`;
	}

	/**
	 * 
	 * @param {Scope} scope 
	 */
	belongingTo(scope) {
		/**
		 * 
		 * @param {Scope} s
		 * @returns {boolean}
		 */
		let checkScope = s => (s ? (s == scope || checkScope(s.parent)) : false);
		return checkScope(this.scope);
	}

	/**
	 * @returns {string?}
	 */
	getFunctionRegion() {
		const search = scope => {
			if (!scope) return null;
			if (scope.type === 'f') return scope.astNode ? scope.astNode.name : null;
			if (!scope.parent) return null;
			return search(scope.parent);
		};
		return this.scope ? search(this.scope) : null;
	}
}

// 作用域类
export class Scope {
    constructor(parent = null, type = 'b', astNode = null, name = '') {
        this.parent = parent;
		/**
		 * @type {'g' | 'f' | 'b' | 'l'}
		 */
        this.type = type; // g 'global', f 'function', b 'block', l 'inline'
		this.name = name;
		/**
		 * @type {ASTNode}
		 */
		this.astNode = astNode; // 关联的AST节点
		/**
		 * @type {Map<string, SymbolEntry>}
		 */
        this.symbols = new Map();
		/**
		 * @type {Scope[]}
		 */
        this.children = [];
		
		if (parent) {
            parent.children.push(this);
        }
    }

    addSymbol(symbol) {
        this.symbols.set(symbol.name, symbol);
		symbol.scope = this; // 建立双向关联
    }
	
	removeSymbol(name) {
		this.symbols.delete(name);
	}

	/**
	 * 
	 * @param {string} name 
	 * @returns {SymbolEntry | null}
	 */
    lookup(name) {
        return this.symbols.get(name) || (this.parent ? this.parent.lookup(name) : null);
    }
	
	/**
	 * 
	 * @param {string} name 
	 * @returns {Scope | null}
	 */
	lookupScopeOf(name) {
		if (this.symbols.has(name)) {
			return this;
		}
		const result = this.parent ? this.parent.lookupScopeOf(name) : null;
		return result;
	}

    lookupCurrent(name) {
        return this.symbols.get(name) || null;
    }
	
	// 获取当前作用域的所有符号
	/**
	 * @returns {SymbolEntry[]} All symbols of current scope.
	 * @remark Notice: children scopes' information isn't included.
	 */
    getAllSymbols() {
        return Array.from(this.symbols.values());
    }

	/**
	 * @returns {SymbolEntry[]}
	 */
	recursivelyGetAllSymbols() {
		return [...this.getAllSymbols(), ...(this.children.flatMap(child => child.recursivelyGetAllSymbols())) ];
	}
	
	// 获取作用域的完整路径
    getPath() {
        const path = [];
        let current = this;
        while (current) {
            path.unshift(current.type + ':' + current.name);
            current = current.parent;
        }
        return path.join('.');
    }

	// Shallow duplicate
	duplicate() {
		const scope = new Scope(this.parent, this.type, this.astNode, this.name);
		scope.children = [...this.children];
		scope.symbols = new Map([...this.symbols].map(([key, symb]) => {
			const dup = symb.duplicate();
			dup.scope = scope;
			return [key, dup];
		}));
		scope.duplicateIdent = (this.duplicateIdent ?? 0) + 1;
		return scope;
	}

	duplicateAll() {
		const scope = new Scope(this.parent, this.type, this.astNode, this.name);
		scope.children = this.children.map(child => child.duplicateAll());
		scope.children.forEach(child => {
			child.parent = scope;
		});
		scope.symbols = new Map([...this.symbols].map(([key, symb]) => {
			const dup = symb.duplicate();
			dup.scope = scope;
			return [key, dup];
		}));
		scope.fullDuplicateIdent = (this.fullDuplicateIdent ?? 0) + 1;
		return scope;
	}

	/**
	 * 
	 * @param {Scope} scope 
	 * @returns {boolean} Returns whether the given scope is a parent of current scope.
	 */
	isParent(scope) {
		if (!scope) return false;
		if (scope === this) return true;
		if (!this.parent) return false;
		return this.parent.isParent(scope);
	}
}

// 首先，添加一些辅助类
export class TypeInfo {
	/**
	 * 
	 * @param {string} name 
	 * @param {string} kind 
	 * @param {number} size 
	 * @param {MemberInfo[] | null} members 
	 */
    constructor(name, kind, size = 1, members = null) {
        this.name = name; // 类型名称
        this.kind = kind; // 'basic', 'struct', 'union', 'pointer', 'array', 'function', 'device', 'null'
        this.size = size; // 类型大小（按1字节对齐）
		/**
		 * @type {MemberInfo[]}
		 */
        this.members = members ?? []; // 结构体/联合体成员
        this.pointerTo = null; // 对于指针类型，指向的类型 (MUST BE A TYPE, NOT A FUNCTION)
        this.arraySize = null; // 对于数组类型，数组大小
        this.qualifiers = []; // 类型限定符: const, volatile, auto, register, extern, etc.
		// Probably we consider 'near' and 'far' as well
		this.functionTo = null;	// Pointing to what function for function type
		this.memberReference = null;
		/**
		 * @type {true}
		 */
		this.isTypeInfo = true;

		this.annotations = new AttributeClass();
    }
    
    isConst() {
        return this.qualifiers.includes('const');
    }
    
    isVolatile() {
        return this.qualifiers.includes('volatile');
    }

	/**
	 * Whether the value lives in ANOTHER processor: every access becomes a
	 * `read` / `write` on the device named by the pointer.
	 *
	 * @returns {boolean}
	 */
	isRemote() {
		return (this.qualifiers ?? []).includes('remote');
	}

	isExtern() {
		return this.qualifiers.includes('extern');
	}

	isStatic() {
		return this.qualifiers.includes('static');
	}

	/**
	 * `persistent` is Mindustry-C's cross-run storage duration. It is not a
	 * C99 storage class; it survives the implicit restart of the processor
	 * program (unlike `static`, which is run-local here).
	 */
	isPersistent() {
		return (this.qualifiers ?? []).includes('persistent');
	}

	isNear() {
		return this.qualifiers.includes('near');
	}

	/**
	 * Discard qualifiers.
	 * @param {string[]} qualifiers 
	 * @returns {TypeInfo}
	 */
	discardQualifier(qualifiers) {
		let result = new TypeInfo(this.name, this.kind, this.size, this.members);
		Object.assign(result, this);
		result.qualifiers = result.qualifiers.filter(q => (!qualifiers.includes(q)));
		return result;
	}

	/**
	 * 
	 * @returns {boolean}
	 */
	/**
	 * Whether the DEFINITION itself forces this struct into memory, i.e. whether
	 * it embeds something that needs memory (an array, or a struct that needs
	 * memory) at any depth. This is a property of the type, so every instance of
	 * it must be stored in memory -- no copy can stay in registers.
	 *
	 * @param {Set<string>} [seen] Guard against recursive definitions
	 * @returns {boolean}
	 */
	intrinsicallyRequiresMemory(seen = null) {
		if (!['struct', 'union'].includes(this.kind)) return false;
		const visited = seen ?? new Set();
		if (this.name) {
			if (visited.has(this.name)) return false;
			visited.add(this.name);
		}
		return (this.members ?? []).some(member =>
			member && member.type && member.type.isTypeInfo && member.type.isRequireMem());
	}

	isStrictPointerImpl() {
		const pointerImplementation = ['pointer', 'array'];
		if (this.kind === 'struct' || this.kind === 'union') {
			/*
			`forceMemoryImpl` is set on a COPY of the type when an instance of it
			has its address taken. A processor has no way to point at a group of
			registers, so that copy has to become a piece of memory. Instances
			whose address is never taken keep the original type and stay in
			registers.
			*/
			if (this.forceMemoryImpl === true) return true;
			/*
			A struct that CONTAINS an array -- or a struct that itself must live in
			memory -- can never be held in registers either: the array needs memory
			of its own, and how many of them a running program needs is not known
			at compile time (a recursive call may need arbitrarily many).
			*/
			return (this.members ?? []).some(member =>
				member && member.type && member.type.isTypeInfo && member.type.isRequireMem());
		}
		return ((typeof this.kind === 'object') && this.kind.isStrictPointerImpl()) ||
		 pointerImplementation.includes(this.kind);
	}


	/**
	 * 
	 * @returns {boolean}
	 */
	isPointerImpl() {
		const pointerImplementation = ['pointer', 'array'];
		if (this.kind === 'struct' || this.kind === 'union') {
			return this.isVolatile() || this.isStrictPointerImpl();
		}
		return ((typeof this.kind === 'object') && this.kind.isPointerImpl()) ||
		 pointerImplementation.includes(this.kind) || this.isVolatile();
	}

	/**
	 * The difference between this and isPointerImpl() is that simple pointer might not require
	 * memory assignment.
	 * 
	 * @returns {boolean}
	 */
	isRequireMem() {
		const pointerImplementation = ['array'];
		if (this.kind === 'struct' || this.kind === 'union') {
			return this.isVolatile() || this.isStrictPointerImpl();
		}
		return ((typeof this.kind === 'object') && this.kind.isPointerImpl()) ||
		 pointerImplementation.includes(this.kind) || this.isVolatile();
	}

	isRegStruct() {
		return (this.kind === 'struct' || this.kind === 'union') && !this.isPointerImpl();
	}

	initializeReferenceTable() {
		this.memberReference = new Map();	// Used only in generation
		this.members.forEach(member => {
			this.memberReference.set(member.name, member.offset);
		});
	}	
    
    toString() {
		/*
		Qualifiers accumulate while a type is copied around, so print each one
		once. The pointee is printed WITHOUT re-listing the outer qualifiers and
		the `*` goes where C puts it, otherwise `const int *` came out as
		`const const const int*`.
		*/
		/*
		A qualifier describes the level it sits on, and for a POINTER the levels
		are genuinely different types: `const int *` is a pointer to a constant
		int, `int *const` is a constant pointer to a plain int. So every level
		prints its OWN qualifiers and `const int *const` keeps both -- the
		pointer's own ones go after the `*`, the way C writes them.

		Duplicates are still dropped, but only WITHIN one level: they come from
		the same type being copied around and say nothing.
		*/
		const qualifiersOf = t => [...new Set(t?.qualifiers ?? [])];
		const render = t => {
			if (!t) return '';
			const own = qualifiersOf(t);
			if ((t.kind === 'pointer' || t.kind === 'array') && t.pointerTo) {
				const inner = render(t.pointerTo);
				if (t.kind === 'pointer') {
					return inner + '*' + (own.length > 0 ? ' ' + own.join(' ') : '');
				}
				/*
				An array has no separate surface syntax -- C writes
				`const int[5]`, never `int[5] const` -- so the element level
				carries the qualifier and the array level only adds what the
				element does not already show.
				*/
				const extra = own.filter(q => !qualifiersOf(t.pointerTo).includes(q));
				/*
				`arraySize` is not necessarily a number: it is often the
				literal NODE from the declarator. Interpolating it straight
				into a template calls its `toString()`, which reaches for a
				source location and throws.
				*/
				const sizeOf = x => {
					if (x === undefined || x === null) return '';
					if (typeof x === 'string' || typeof x === 'number') return String(x);
					if (Array.isArray(x)) return x.map(sizeOf).join('');
					return String(x.value ?? '');
				};
				/*
				An open dimension is `NaN` -- the same thing a parameter's `[]`
				reads back as, and the reason a type-name channel cannot carry it
				(see `getTypeInfo`). It has to print as `[]`: "NaN" in a message
				about a program the user wrote is noise, and `int[NaN]` is not a
				type anybody can write.
				*/
				const shownSize = value => {
					const text = sizeOf(value);
					return (/^\s*NaN\s*$/.test(text) || text === 'undefined') ? '' : text;
				};
				return (extra.length > 0 ? extra.join(' ') + ' ' : '') + inner
					+ `[${Array.isArray(t.arraySize) ? t.arraySize.map(shownSize).join('') : shownSize(t.arraySize)}]`;
			}
			// `name` may be a node rather than a string in odd cases
			const name = (typeof t.name === 'string') ? t.name : (t.name?.value ?? '');
			return (own.length > 0 ? own.join(' ') + ' ' : '') + name;
		};
		let result = render(this);
		if (this.kind === 'function') {
			if (this.functionTo) {
				result += '{' + this.functionTo.type.returnType.toString() + ' || ';
				result += (this.functionTo.type.parameters.map(param => (param.type.toString()))).join(',') + '}';
			} else {
				result = `{ ??${this.name} }`;
			}
		}
        return result;
    }

	/**
	 * Return the result of single-layer dereference (through * or [])
	 * @returns {TypeInfo}
	 */
	extractSingle() {
		if (this.kind === 'array') {
			if (!this.pointerTo) return null;
			/**
			 * @type {TypeInfo}
			 */
			const tmpl = this.duplicate();
			if (this.arraySize.length > 1) {
				tmpl.size = tmpl.size / this.arraySize[0];
				tmpl.arraySize = this.arraySize.slice(1);
				return tmpl;
			} else {
				return this.pointerTo;
			}
		} else {
			return this.pointerTo;
		}
	}

	/**
	 * 
	 * @param {number} k 
	 * @returns {TypeInfo?}
	 */
	extractKth(k) {
		if (['array', 'pointer'].includes(this.kind)) {
			return this.extractSingle();
		} else if (['struct', 'union'].includes(this.kind)) {
			return this.members[k]?.type ?? null;
		} else {
			return null;
		}
	}

	/**
	 * @remark Shallow copy for members and comprehensive copy for qualifiers.
	 * @returns {TypeInfo}
	 */
	duplicate() {
		let result = new TypeInfo(this.name, this.kind, this.size);
		Object.assign(result, this);
		result.qualifiers = [...new Set(this.qualifiers)];
		return result;
	}
}

export class MemberInfo {
	/**
	 * 
	 * @param {string} name 
	 * @param {TypeInfo} type 
	 * @param {number} offset 
	 * @param {null} bitField 
	 */
    constructor(name, type, offset, bitField = null) {
        this.name = name;
        this.type = type;
        this.offset = offset; // 成员偏移量
        this.bitField = bitField; // 位域信息 [Unused!!]
        /*
        `int *byname ptr` inside a struct: the member is a pointer that carries
        a NAME, so `*s.ptr` is `read / write @this <the name>`. It has to be
        recorded here because the member has no SymbolEntry of its own -- which
        is exactly why the qualifier used to be dropped, making the write put
        one word and the read take two.
        */
        this.namePointer = false;
    }
}

export class SemanticAnalyzer extends ASTVisitor {
	// !! Global scope is being manually established !!
	/**
	 * 
	 * @param {Compiler} compiler 
	 */
    constructor(compiler = null) {
        super(compiler);
        this.errors = [];
        this.warnings = [];
		/**
		 * @type {Scope}
		 */
        this.currentScope = null;
        this.currentFunction = null;
        this.symbolTable = new Map();
        this.typeTable = new Map();
        this.structTable = new Map(); // 专门存储结构体/联合体定义
        this.typedefTable = new Map(); // 存储typedef定义的类型别名
        
		this.targetVersion = this.compiler ? this.compiler.config.getAttribute('targetVersion') : 0;

		this.globalScope = null;	// ???
		this.scopeCounter = 0;
		this.virtualCounter = 0;
		/*
		Break/continue context. A loop provides both; a `switch` (when it
		exists) will provide only the breakable half. Counters, so a nested
		loop or switch restores the outer context on exit.
		*/
		this.loopDepth = 0;
		this.breakableDepth = 0;
		// Cannot do initialization in construction !!!
    }

	/**
	 * Classify every `&x` in the program: builtin output parameter, stored into
	 * a pointer, or an ordinary address use. See `analyze()` for why.
	 *
	 * Runs on the full AST, before any optimisation removes declarations.
	 *
	 * @param {any} ast
	 */
	collectAddressUses(ast) {
		/** @type {Map<string, {builtin: number, pointers: Set<string>, other: number}>} */
		const table = new Map();
		// Symbols live in nested scopes, so resolve by name over the whole tree
		let allSymbols = null;
		const symbolsOf = name => {
			if (!allSymbols) {
				allSymbols = new Map();
				const visit = scope => {
					scope?.symbols?.forEach(sym => {
						if (!allSymbols.has(sym.name)) allSymbols.set(sym.name, []);
						allSymbols.get(sym.name).push(sym);
					});
					scope?.children?.forEach(visit);
				};
				visit(this.globalScope);
			}
			return allSymbols.get(name) ?? [];
		};
		const entryOf = symbol => {
			if (!symbol) return null;
			const key = symbol.getAssemblySymbol?.() ?? symbol.name ?? null;
			if (!key) return null;
			if (!table.has(key)) table.set(key, { builtin: 0, pointers: new Set(), other: 0 });
			return table.get(key);
		};
		const isOutputBuiltin = (name, index) => {
			if (name === 'ulocate' || name === 'ucontrol') return true;
			const candidates = symbolsOf(name);
			return candidates.some(symbol => Array.isArray(symbol?.type?.nominalPointers)
				&& symbol.type.nominalPointers.includes(index));
		};

		const walk = (node, parent) => {
			if (!node || typeof node !== 'object') return;
			if (Array.isArray(node)) { node.forEach(child => walk(child, parent)); return; }
			if (node.type === 'UnaryExpression' && node.operator === '&'
				&& node.argument && node.argument.type === 'Identifier') {
				const candidates = symbolsOf(node.argument.name);
				const entry = entryOf(candidates.length === 1 ? candidates[0]
					: (candidates.find(c => /coreX|coreY|coreFound/.test(c.name)) ?? candidates[0]));
				if (entry) {
					if (parent && (parent.type === 'FunctionCall' || parent.type === 'BuiltinCall')) {
						const callee = parent.callee?.name ?? parent.functionName ?? parent.name ?? null;
						const argIndex = Array.isArray(parent.arguments) ? parent.arguments.indexOf(node) : -1;
						if (isOutputBuiltin(callee, argIndex)) entry.builtin++;
						else entry.other++;
					} else if (parent && parent.type === 'VariableDeclarator') {
						/*
						`int *p = &x` -- remember p. Whether x needs a real
						address depends on p, which is decided later.
						*/
						entry.pointers.add(parent.name);
					} else if (parent && parent.type === 'AssignmentExpression'
						&& parent.right === node && parent.left?.type === 'Identifier') {
						entry.pointers.add(parent.left.name);
					} else {
						entry.other++;
					}
				}
			}
			for (const key of ['children', 'functions', 'globalDeclarations', 'statements',
				'declarators', 'arguments', 'argument', 'left', 'right', 'initializer',
				'expression', 'test', 'consequent', 'alternate', 'body', 'init', 'update',
				'callee', 'declarations', 'elements']) {
				const child = node[key];
				if (Array.isArray(child)) child.forEach(c => walk(c, node));
				else if (child && typeof child === 'object') walk(child, node);
			}
		};
		walk(ast, null);
		this.addressUseTable = table;
	}

    analyze(ast) {
        this.errors = [];
        this.warnings = [];
        this.ast = ast;
        this.stringLiteralCounter = 0;
        this.stringLiteralArrays = new Map();
        // `remote()` bindings that name an array declared further down
        this.pendingRemoteLinks = [];
        this.currentScope = new Scope(null, 'g');
        this.currentFunction = null;
		this.globalScope = this.currentScope;
		
		// 初始化内建类型
        this.initializeBuiltinTypes();
        this.initializeBuiltinFunctions();

		this.specialTypes = {
			'@this': this.typeTable.get('device'),
			'@thisx': this.typeTable.get('int'),
			'@thisy': this.typeTable.get('int'),
			'@links': this.typeTable.get('int'),
			'@ipt': this.typeTable.get('int'),
			'@pi': this.typeTable.get('double'),
			'@e': this.typeTable.get('double'),
			'@degToRad': this.typeTable.get('double'),
			'@radToDeg': this.typeTable.get('double'),
			'@time': this.typeTable.get('double'),
			'@tick': this.typeTable.get('double'),
			'@second': this.typeTable.get('double'),
			'@minute': this.typeTable.get('double'),
			'@waveNumber': this.typeTable.get('int'),
			'@waveTime': this.typeTable.get('double'),
			'@mapw': this.typeTable.get('int'),
			'@maph': this.typeTable.get('int'),
			'@server': this.typeTable.get('bool'),
			'@client': this.typeTable.get('bool'),
			'@clientLocale': this.typeTable.get('string_t'),
			'@clientName': this.typeTable.get('string_t'),
			'@clientTeam': this.typeTable.get('string_t'),
			'@clientUnit': this.typeTable.get('int'),
			'@clientMobile': this.typeTable.get('bool'),
			'@blockCount': this.typeTable.get('int'),
			'@unitCount': this.typeTable.get('int'),
			'@itemCount': this.typeTable.get('int'),
			'@liquidCount': this.typeTable.get('int'),
			'@unit': this.typeTable.get('device')
		};
		/*
		`#pragma var(<type>, @name)` declares a processor variable: it behaves
		exactly like `@this`, only with the type the program asked for.
		*/
		this.contentTable = (this.compiler?.extraConfig?.getAttribute('contentTable')) ?? null;
		if (this.contentTable) {
			for (const [name, typeName] of this.contentTable.variables) {
				const info = this.typeTable.get(typeName);
				if (info) this.specialTypes[name] = info;
			}
		}
		
		// 建立AST节点和作用域的关联
        this.linkScopesToAST(ast);
		
		// 第一遍：收集类型定义（typedef, struct, union）
        this.collectTypeDefinitions(ast);
		// In-memory copies of struct types, made on demand by `&s`
		this.memoryVariants = new Map();

        this.visit(ast);
		/*
		Record HOW the address of each variable is taken. The generator needs
		this to decide whether the variable really has to live in memory:

		  - `ulocate(..., &x, ...)` writes into the register NAMED x, so x may
		    stay a register at any version;
		  - `int *p = &x` needs a real address only when p is a traditional
		    pointer -- if p keeps names (or is never used at all) x may stay a
		    register too;
		  - anything else genuinely needs an address.
		*/
        this.collectAddressUses(ast);
        /*
        Only now is the whole program read, so only now can a `remote()` that
        mentions an array declared further down be bound.
        */
        /*
        A function POINTER type is a fixed contract: what travels through it is
        a line number, so the function behind it cannot be told which
        instantiation to use. A template struct in such a signature has no
        single representation to pick, so it is rejected here -- write the
        concrete struct instead (`struct cvt { int *byname p; }`).
        */
        this.rejectTemplateInFunctionPointers();
        this.finalizeRemoteLinks();
        /*
        Only now is every call site known, so only now can each array parameter
        be told which layout it will be given.
        */
        this.finalizeArrayParameters(ast);
        /*
        Only now is every store into a struct member known, so only now can an
        `auto` member settle on the representation its instance needs.
        */
        this.specializeStructTemplates(ast);
        this.specializeStructTemplateFunctions(ast);
        this.verifyStructConversions();
        /*
        Only now is every statement of every function seen, so only now can an
        unbound handle (`int a[];`) be judged: it is provably unreadable before
        its first binding, and one that is never bound at all is an error.
        */
        this.checkUnboundHandles(ast);
        /*
        Only now is every parameter representation, `remote` link and
        `array("...")` request settled, so only now can each array's layout be
        decided from them and remembered on the symbol for the generator.
        */
        this.finalizeArrayStyles();

        return {
            success: this.errors.length === 0,
            ast: ast,
            errors: this.errors,
            warnings: this.warnings,
            symbolTable: this.symbolTable
        };
    }
	
	// !! Notice: new scopes can't be created afterwards !!
	// 建立AST节点和作用域的关联
    linkScopesToAST(node) {
        if (!node) return;
        
        // 将当前作用域关联到节点
        node.scope = this.currentScope;
        
        switch (node.type) {
            case 'Program':
                // 程序节点关联全局作用域
                node.scope = this.globalScope;
                this.globalScope.astNode = node;
				// if (node.functions) {
					// node.functions.forEach(child => this.linkScopesToAST(child));
				// }
                break;
                
            case 'FunctionDeclaration':
                // 函数作用域
                const functionScope = new Scope(this.currentScope, 'f', node, node.name);
                this.currentScope = functionScope;
                node.scope = functionScope;
                break;
                
            case 'CompoundStatement':
                // 块作用域
				// TODO: There are some bugs here...
                if (this.currentScope.type !== 'f' || 
                    (this.currentScope.astNode && this.currentScope.astNode.type !== 'CompoundStatement')) {
                    const blockScope = new Scope(this.currentScope, 'b', node, '' + (++this.scopeCounter));
                    this.currentScope = blockScope;
                    node.scope = blockScope;
                } else {
                    // 函数体的第一个复合语句不创建新作用域
                    node.scope = this.currentScope;
                }
				// if (node.statements) {
					// node.statements.forEach(child => this.linkScopesToAST(child));
				// }
                break;
        }
        
        // 递归处理子节点
        if (node.children) {
            node.children.forEach(child => this.linkScopesToAST(child));
        }

		const fieldsToCheck = [
				'functions', 'globalDeclarations', 'typeDefinitions',
				'statements', 'expression', 'test', 'consequent', 'alternate',
				'body', 'discriminant', 'init', 'update', 'argument', 'left', 'right',
				'declarators', 'arguments', 'callee', 'initializer'
			];

			for (const field of fieldsToCheck) {
				if (Array.isArray(node[field])) {
					node[field].forEach(elem => this.linkScopesToAST(elem));
				} else if (node[field] && typeof node[field] === 'object') {
					this.linkScopesToAST(node[field]);
				}
			}
        
        // 退出作用域
        switch (node.type) {
            case 'FunctionDeclaration':
            case 'CompoundStatement':
                if (node.scope && node.scope !== this.globalScope) {
                    this.currentScope = node.scope.parent;
                }
                break;
        }
    }
	
	// !! MANUAL CHANGES HERE !!
	collectTypeDefinitions(node) {
        if (!node) return;
        
        // 收集程序中的类型定义
        if (node.type === 'Program') {
            // 收集typedef定义
			// Modified here
            if (node.typeDefinitions) {
                node.typeDefinitions.forEach(def => {
                    if (def.type === 'struct' || def.type === 'union') {
                        this.processStructOrUnionDefinition(def);
                    } else if (def.type === 'TypeSpecifier' && def.typeName === 'enum') {
                        this.processEnumDefinition(def, this.globalScope);
                    } else {
						if ((!def.isStruct) && (!def.isUnion)) {
							this.processTypedefDeclaration(def);
						}
						else {
							this.addError(`Internal error: Unknown parsed structure`, node.location);
						}
					}
                });
            }
            
            // 收集全局结构体/联合体定义
            node.globalDeclarations.forEach(decl => {
                if ((decl.type === 'VariableDeclaration' || decl.declarators) && decl.getAttribute('isStructOrUnion')) {
                    // 处理结构体/联合体变量声明中的类型定义
                    //this.processTypeFromDeclaration(decl.type);
					// 检查是否是结构体/联合体类型
					const typeName = this.getTypeNameFromTypeNode(decl.type);
					if (typeName === 'struct' || typeName === 'union') {
						// I don't know, but I guess this means that this type is still not
						// initialized.
						this.processTypeFromDeclaration(decl.type);
					}
				}
            });
        }
    }

    initializeBuiltinTypes() {
        // 基本类型
        const basicTypes = ['int', 'char', 'float', 'double', 'void', 'long', 'short', 'signed', 'unsigned', 'bool'];
        basicTypes.forEach(type => {
            this.typeTable.set(type, new TypeInfo(type, 'basic', 1));
        });
        /*
        The native Mindustry string is a value, not a C character. It used to
        be spelled `char`; separating the two lets `char` be the ordinary
        one-cell number C expects while `string_t` keeps the 1-cell machine
        string.
        */
        this.typeTable.set('string_t', new TypeInfo('string_t', 'basic', 1));

        // 特殊类型
        this.typeTable.set('device', new TypeInfo('device', 'device', 1));
        this.typeTable.set('null_t', new TypeInfo('null_t', 'null', 1));
		this.typeTable.set('content_t', new TypeInfo('content_t', 'device', 1));	// Similar to device
        // 'item_t', 'liquid_t', 'unit_t', 'block_t'
		for (const contentTypes of ['item_t', 'liquid_t', 'unit_t', 'block_t']) {
			this.typeTable.set(contentTypes, new TypeInfo(contentTypes, 'basic', 1));
		}

		const extraTypes = this.extraConfig.getAttribute('extraTypes');
		if (extraTypes) {
			extraTypes.forEach(
				/**
				 * @param {TypeInfo} type 
				 */
				type => {
					this.typeTable.set(type.name, type);
			});
		}

        // 指针类型的基础（void*）
		// Pointer has a size of 2 !!
		/*
        const voidPtrType = new TypeInfo('void*', 'pointer', 2);
        voidPtrType.pointerTo = this.typeTable.get('void');
        this.typeTable.set('void*', voidPtrType);
		const charPtrType = new TypeInfo('char*', 'pointer', 2);
        voidPtrType.pointerTo = this.typeTable.get('char');
        this.typeTable.set('char*', charPtrType);
		*/
    }

    initializeBuiltinFunctions() {
		// TODO: Must be modified...
		// TODO: Use boolean here
        const builtins = [
            { name: 'draw', returnType: 'void', parameters: ['string_t'], hasVarArgs: true }, // 操作名称 + 变长参数 (Actually, need further judgment)
			{ name: 'print', returnType: 'void', parameters: [], hasVarArgs: true }, // 变长参数 (Actually, accepting multiple operations)
			{ name: 'printf', returnType: 'void', parameters: [], hasVarArgs: true },
			{ name: 'assert', returnType: 'void', parameters: [], hasVarArgs: true },
			{ name: 'printchar', returnType: 'void', parameters: [], hasVarArgs: true }, 
			{ name: 'format', returnType: 'void', parameters: [], hasVarArgs: true }, 
			{ name: 'drawflush', returnType: 'void', parameters: ['device'] },
			{ name: 'printflush', returnType: 'void', parameters: ['device'] },
			{ name: 'getlink', returnType: 'device', parameters: ['int'] },
			{ name: 'control', returnType: 'void', parameters: ['string_t', 'device'], hasVarArgs: true }, // 操作名称 + 设备 + 变长参数
			{ name: 'radar', returnType: 'device', parameters: ['string_t', 'string_t', 'string_t', 'string_t', 'device', 'int'] },
			{ name: 'sensor', returnType: 'null_t', parameters: ['device', 'content_t'] },	// Sensor may return ANY TYPE. PROCESS ON YOUR OWN
			{ name: 'set', returnType: 'void', parameters: [], hasVarArgs: true, special: 'set' }, // 特殊处理
			{ name: 'op', returnType: 'void', parameters: [], hasVarArgs: true, special: 'op' }, // 特殊处理
			{ name: 'lookup', returnType: 'content_t', parameters: ['string_t', 'int'] },
			{ name: 'wait', returnType: 'void', parameters: ['float'] },
			{ name: 'stop', returnType: 'void', parameters: [] },
			{ name: 'end', returnType: 'void', parameters: [] },
			{ name: 'jump', returnType: 'void', parameters: [], hasVarArgs: true, special: 'jump' }, // 特殊处理
			{ name: 'read', returnType: 'null_t', parameters: [], special: 'read'}, // 特殊处理
			{ name: 'stricteq', returnType: 'bool', parameters: [], hasVarArgs: true, special: 'stricteq' }, // 严格相等
			{ name: 'write', returnType: 'void', parameters: [], special: 'write'}, // 特殊处理
			{ name: 'ubind', returnType: 'void', parameters: ['content_t']},
			{ name: 'ucontrol', returnType: 'void', parameters: [], hasVarArgs: true},
			{ name: 'uradar', returnType: 'device', parameters: ['string_t', 'string_t', 'string_t', 'string_t', 'int', 'int'] },
			{ name: 'ulocate', returnType: 'int', parameters: [], hasVarArgs: true},
			{ name: 'asm', returnType: 'null_t', parameters: ['string_t'], special: 'asm'}, // TODO: I'm unsure about whether this can be correctly done now.
			{ name: 'sin', returnType: 'float', parameters: ['float'] },	// These are in [op] instruction
			{ name: 'cos', returnType: 'float', parameters: ['float'] },
			{ name: 'tan', returnType: 'float', parameters: ['float'] },
			{ name: 'asin', returnType: 'float', parameters: ['float'] },
			{ name: 'acos', returnType: 'float', parameters: ['float'] },
			{ name: 'atan', returnType: 'float', parameters: ['float'] },
			{ name: 'adiff', returnType: 'float', parameters: ['float', 'float'] },
			{ name: 'min', returnType: 'float', parameters: ['float', 'float'] },
			{ name: 'max', returnType: 'float', parameters: ['float', 'float'] },
			{ name: 'ceil', returnType: 'float', parameters: ['long']},
			{ name: 'floor', returnType: 'float', parameters: ['long']},
			{ name: 'sqrt', returnType: 'float', parameters: ['float']},
			{ name: 'pow', returnType: 'float', parameters: ['float', 'float']},
			{ name: 'abs', returnType: 'float', parameters: ['float']},
			{ name: 'rand', returnType: 'float', parameters: ['float']},
			{ name: 'memcpy', returnType: 'void', parameters: ['void*', 'void*', 'unsigned']},
			{ name: 'memsp', returnType: 'void*', parameters: ['device', 'int']},
			{ name: 'byname', returnType: 'void*', parameters: [], hasVarArgs: true, special: 'byname' },
			/*
			`vecalias(&a, b)` binds a handle cell to an array, `veccpy(a, b)`
			copies elements into storage of its own. Both are intrinsics: the
			arity and the argument layouts are checked in `visitBuiltinCall`, and
			the generator emits the bodies (one store; one loop).
			*/
			{ name: 'vecalias', returnType: 'void', parameters: [], hasVarArgs: true, special: 'vecalias' },
			{ name: 'veccpy', returnType: 'void', parameters: [], hasVarArgs: true, special: 'veccpy' },
			{ name: 'remote', returnType: 'void*', parameters: [], hasVarArgs: true, special: 'remote' },
			...(this.extraConfig.getAttribute('extraFunctions') ?? [])
		];

        builtins.forEach(func => {
            const symbol = new SymbolEntry(
                func.name,
                { returnType: func.returnType, parameters: func.parameters, hasVarArgs: func.hasVarArgs ?? false, nominalPointers: func.nominalPointers ?? [], special: func.special ?? null },
                this.currentScope,
                'function'
            );
			// Builtin symbol doesn't own scope
            this.currentScope.addSymbol(symbol);
        });
    }

	// Deepseek has some branches here
	// ! There has some manual changes !
	processTypedefDeclaration(typedefNode) {
		// Deepseek says yes
		// 临时解决方案：检查节点是否具有declarators属性
		if (!typedefNode.declarators) {
			this.addError(`Internal Error: Invalid typedef declaration`, typedefNode.location);
			return;
		}
		
		// Some special process for function pointer type:
		// ! TODO: Functions will need 'isAddressed' (to suppress inlining) !
		if (typedefNode.isFunction) {
			typedefNode.declarators.forEach(declarator => {
				const aliasName = declarator.name;
				// Directly create a new type instead of go aliases
				// TODO: Add temporary name, if necessary?
				// Function has a size of 1 (its address)
				// (Different from pointer's size 2 due to the need of storing its block position
				// This will make them have a name
				const aliasType = new TypeInfo(aliasName, 'function', 1);
				aliasType.qualifiers = typedefNode.functionDefinition.pointerQualifiers;
				aliasType.functionTo = new SymbolEntry(
					aliasName,
					{
						returnType: typedefNode.functionDefinition.returnType.typeName,
						parameters: typedefNode.functionDefinition.parameters.map(param => ({
							name: param.name,
							type: ((param) => {
									/*
									An array parameter keeps its dimensions on the
									PARAMETER node, not on the type specifier -- so
									`typedef void (*cb)(int s[3])` used to come out
									as `cb{void || int}` and no array could ever be
									handed to it.
									*/
									if (param.arrayDimensions?.length && !param.type?.arrayDimensions?.length) {
										param.type.arrayDimensions = param.arrayDimensions;
									}
									return this.getTypeNameFromTypeNode(param.type);
								})(param)
						}))
					},
					this.globalScope,
					'function',
					typedefNode.location
				);
				
				this.addTypeAlias(aliasName, aliasType, declarator.location);
				this.typedefTable.set(aliasName, {
					originalType: aliasType,
					aliasType: aliasType,
					location: declarator.location
				});
			});
		} else {
			// Traditional process
			if (typedefNode.structDefinition) {
				this.processStructOrUnionDefinition(typedefNode.structDefinition);
			}
			if (typedefNode.type?.type === 'TypeSpecifier' && typedefNode.type.typeName === 'enum') {
				this.processEnumDefinition(typedefNode.type, this.currentScope);
			}
			let baseTypeName = this.getTypeNameFromTypeNode(typedefNode.type);
			let baseType = this.getTypeInfo(baseTypeName);
			/*
			`typedef struct P P;` itself declares the tag P as an incomplete
			type. Its later definition fills this same object.
			*/
			if (!baseType && typedefNode.type?.type === 'TypeSpecifier'
				&& ['struct', 'union'].includes(typedefNode.type.typeName)
				&& typedefNode.type.getAttribute('structOrUnionName')) {
				const kind = typedefNode.type.typeName;
				baseType = new TypeInfo(baseTypeName, kind, 0);
				baseType.incomplete = true;
				baseType.isForward = true;
				baseType.members = [];
				this.typeTable.set(baseTypeName, baseType);
				this.structTable.set(baseTypeName, baseType);
			}
			
			if (!baseType) {
				this.addError(`Unknown base type '${baseTypeName}' in typedef`, typedefNode.location);
				return;
			}
			
			typedefNode.declarators.forEach(declarator => {
				const aliasName = declarator.name;
				/*
				A direct alias of an incomplete struct must BE that type object,
				not a copy: the later definition fills the object.
				*/
				const directAlias = baseType.incomplete === true
					&& (declarator.pointerDepth ?? 0) === 0
					&& !(declarator.arrayDimensions?.length);
				const aliasType = directAlias ? baseType : this.createAliasType(baseType, declarator);
				
				// 添加到类型表和typedef表
				this.addTypeAlias(aliasName, aliasType, declarator.location);
				this.typedefTable.set(aliasName, {
					originalType: baseType,
					aliasType: aliasType,
					location: declarator.location
				});
			});
		}
    }
	
	/**
	 * Register an enum definition and its enumerators.
	 *
	 * Enumerators are `int` constants in the surrounding scope (C, not a
	 * scoped enum); `enum Tag` itself is an int-like type for variables.
	 *
	 * @param {TypeSpecifierNode} typeNode
	 * @param {Scope} [scope]
	 * @returns {void}
	 */
	processEnumDefinition(typeNode, scope = this.currentScope) {
		if (!typeNode || typeNode.getAttribute?.('enumProcessed') === true) return;
		typeNode.setAttribute('enumProcessed', true);
		const name = typeNode.getAttribute('enumName') || 'enum';
		const intType = this.typeTable.get('int');
		/*
		C enums are compatible with int; keeping the SAME TypeInfo means
		`enum Color c = BLUE;`, arithmetic and array sizes all see an int.
		*/
		this.typeTable.set(name, intType);
		typeNode.setAttribute('enumTypeName', name);

		let next = 0;
		for (const entry of typeNode.getAttribute('enumValues') ?? []) {
			let value = next;
			if (entry.value) {
				const folded = this.enumConstantValue(entry.value, scope);
				if (folded === null) {
					this.addError(`Enumerator '${entry.name}' needs a constant expression`, entry.location);
					continue;
				}
				value = folded;
			}
			next = value + 1;
			if (scope.lookupCurrent(entry.name)) {
				this.addError(`Enumerator '${entry.name}' is already declared in this scope`, entry.location);
				continue;
			}
			const symbol = new SymbolEntry(entry.name,
				{ type: intType, isConst: true },
				scope, 'variable', entry.location);
			symbol.isConst = true;
			symbol.isEnumConstant = true;
			symbol.markAsConstant(value);
			scope.addSymbol(symbol);
		}
	}

	/**
	 * Fold the constant expression allowed in an enumerator initializer.
	 *
	 * @param {ASTNode} node
	 * @param {Scope} scope
	 * @returns {number?}
	 */
	enumConstantValue(node, scope) {
		if (!node) return null;
		switch (node.type) {
			case 'NumericLiteral':
				return Number(node.value);
			case 'CharacterLiteral':
				return (node.value ?? '').codePointAt(0) ?? null;
			case 'Identifier': {
				const symbol = scope.lookup(node.name) ?? this.globalScope.lookup(node.name);
				return symbol?.isConstant ? Number(symbol.constantValue) : null;
			}
			case 'UnaryExpression': {
				const value = this.enumConstantValue(node.argument, scope);
				if (value === null) return null;
				switch (node.operator) {
					case '+': return value;
					case '-': return -value;
					case '~': return ~Math.trunc(value);
					case '!': return value === 0 ? 1 : 0;
					default: return null;
				}
			}
			case 'BinaryExpression': {
				const left = this.enumConstantValue(node.left, scope);
				const right = this.enumConstantValue(node.right, scope);
				if (left === null || right === null) return null;
				switch (node.operator) {
					case '+': return left + right;
					case '-': return left - right;
					case '*': return left * right;
					case '/': return right === 0 ? null : Math.trunc(left / right);
					case '%': return right === 0 ? null : left % right;
					case '<<': return Math.trunc(left) << Math.trunc(right);
					case '>>': return Math.trunc(left) >> Math.trunc(right);
					case '|': return Math.trunc(left) | Math.trunc(right);
					case '&': return Math.trunc(left) & Math.trunc(right);
					case '^': return Math.trunc(left) ^ Math.trunc(right);
					default: return null;
				}
			}
			default:
				return null;
		}
	}

	processStructOrUnionDefinition(defNode) {
        const typeName = defNode.name || `anonymous_${defNode.type}_${this.anonymousStructCounter = (this.anonymousStructCounter ?? 0) + 1}`;
        const isUnion = defNode.type === 'union';
        const kind = isUnion ? 'union' : 'struct';
        const scopedType = this.currentScope.lookupCurrent?.(typeName)?.type?.type ?? null;
        const existing = (this.currentScope === this.globalScope)
            ? (scopedType ?? this.structTable.get(typeName) ?? this.typeTable.get(typeName) ?? null)
            : scopedType;

        if (existing && ['struct', 'union'].includes(existing.kind)) {
            if (existing.incomplete !== true) {
                if (defNode.isForward) return;	// a redundant forward declaration
                this.addError(`'${defNode.type} ${typeName}' is already defined`, defNode.location);
                return;
            }
        }

        /*
        The SAME TypeInfo object survives a forward declaration. Pointers and
        aliases made while the type was incomplete must see the completed
        members later, so a definition fills the existing object instead of
        creating a second one.
        */
        const structType = existing && ['struct', 'union'].includes(existing.kind)
            ? existing : new TypeInfo(typeName, kind, 0);
        structType.kind = kind;
        structType.members = structType.members ?? [];
        if (this.currentScope === this.globalScope || !defNode.name) {
            this.typeTable.set(typeName, structType);
            this.structTable.set(typeName, structType);
        }

        if (defNode.isForward) {
            structType.incomplete = true;
            structType.isForward = true;
            structType.beingDefined = false;
            if (defNode.name && !this.currentScope.lookupCurrent(defNode.name)) {
                this.currentScope.addSymbol(new SymbolEntry(defNode.name,
                    { type: structType }, this.currentScope, 'type', defNode.location));
            }
            return;
        }
        structType.incomplete = false;
        structType.isForward = false;
        structType.beingDefined = true;
        /*
        `struct tmpl { auto int *p; }` -- a member asking for whichever
        representation the instance turns out to need. Such a struct is a
        PATTERN: every instance has to settle on one representation per `auto`
        member before the type can be used.
        */
        const templateMembers = [];
        (defNode.members ?? []).forEach(member => {
            const q = [
                ...(member?.type?.getAttribute?.('qualifiers') ?? []),
                ...((member?.type?.pointerQualifiers ?? []).flat()),
                ...(member?.getAttribute?.('qualifiers') ?? [])
            ];
            if (q.includes('auto')) templateMembers.push(member.name);
        });
        if (templateMembers.length) {
            structType.isTemplate = true;
            structType.templateMembers = templateMembers;
        }

        // 处理成员
        let currentOffset = 0;
        let maxMemberSize = 0;
        const members = [];
        const bitfieldStorages = [];
        let bitGroupStart = -1;
        let bitGroupUsed = 0;
        let bitGroupIndex = 0;
        const intType = this.typeTable.get('int');
        
        if (defNode.members && defNode.members.length > 0) {
            defNode.members.forEach(member => {
                /*
                `struct S { enum Color { ... } c; };` -- the enum is declared
                inside the member list, so it has to be registered before the
                member's type name is looked up.
                */
                if (member?.type?.type === 'TypeSpecifier'
                    && member.type.typeName === 'enum'
                    && member.type.getAttribute?.('enumDefinition')) {
                    this.processEnumDefinition(member.type, this.currentScope);
                }
                // const memberTypeName = this.getTypeNameFromTypeNode(member.type);
				const memberTypeName = this.getTypeNameFromDeclarator(member);
                const memberType = this.getTypeInfo(memberTypeName);
                
                if (!memberType) {
                    this.addError(`Unknown member type '${memberTypeName}'`, member.location);
                    return;
                }
                if (memberType.incomplete === true) {
                    this.addError(`Member '${member.name}' has incomplete type '${memberType.toString()}'`,
                        member.location);
                    return;
                }
                const memberByname = this.hasByNameQualifier(member);
                
                // 计算成员大小（所有基本类型大小为1）
                const memberSize = this.calculateTypeSize(memberType);

                /*
                Bitfields: unsigned, 1..52 bits, packed LSB-first into one cell.
                A zero-width field ends the current storage cell; more than 52
                bits starts a new one. The cell itself is a synthetic member so
                copy/zero/serialisation see the raw storage, while the visible
                bitfield members carry storageName/bitOffset/bitWidth.
                */
                if (member.bitField) {
                    if (isUnion) {
                        this.addError(`Bitfields in a union are not supported yet`, member.location);
                        return;
                    }
                    if (!(this.isIntegerType(memberType.name) || memberType.name === 'bool')) {
                        this.addError(`A bitfield needs an integer type`, member.location);
                        return;
                    }
                    const width = this.constantCaseValue(member.bitField);
                    if (!Number.isInteger(width) || width < 0) {
                        this.addError(`A bitfield width must be a non-negative integer constant`, member.location);
                        return;
                    }
                    if (width === 0) {
                        bitGroupStart = -1;
                        bitGroupUsed = 0;
                        return;
                    }
                    if (width > 52) {
                        this.addError(`A bitfield is limited to 52 bits (got ${width})`, member.location);
                        return;
                    }
                    if (bitGroupStart < 0 || bitGroupUsed + width > 52) {
                        bitGroupStart = currentOffset++;
                        bitGroupUsed = 0;
                        const storageName = `__bits${bitGroupIndex++}`;
                        const storage = new MemberInfo(storageName, intType, bitGroupStart, null);
                        storage.isBitfieldStorage = true;
                        storage.bitfieldMembers = [];
                        members.push(storage);
                        bitfieldStorages.push(storage);
                    }
                    const storageName = `__bits${bitGroupIndex - 1}`;
                    const bit = new MemberInfo(member.name, memberType,
                        bitGroupStart, member.bitField);
                    bit.isBitfield = true;
                    bit.storageName = storageName;
                    bit.bitOffset = bitGroupUsed;
                    bit.bitWidth = width;
                    bit.isSigned = memberType.name === 'signed';
                    bit.namePointer = memberByname;
                    members.push(bit);
                    bitfieldStorages[bitfieldStorages.length - 1].bitfieldMembers.push(bit);
                    bitGroupUsed += width;
                    return;
                }

                // A non-bitfield ends the current bitfield storage cell.
                bitGroupStart = -1;
                bitGroupUsed = 0;
                
                // 对于结构体，累加偏移量；对于联合体，取最大成员大小
                if (isUnion) {
                    maxMemberSize = Math.max(maxMemberSize, memberSize);
                    const memberInfo = new MemberInfo(
                        member.name,
                        memberType,
                        0,
                        null
                    );
                    memberInfo.namePointer = memberByname;
                    members.push(memberInfo);
                } else {
                    // 结构体成员：按1字节对齐
                    const memberInfo = new MemberInfo(
                        member.name,
                        memberType,
                        currentOffset,
                        null
                    );
                    memberInfo.namePointer = memberByname;
                    members.push(memberInfo);
                    currentOffset += memberSize;
                }
            });
            
            // 计算最终大小
            if (isUnion) {
                structType.size = maxMemberSize;
                /*
                A union with more than one member is memory-backed for now:
                register structs give every member its own register, which would
                not overlap at all. A single-member union has nothing to alias
                and may keep the ordinary representation.
                */
                if (members.length > 1) structType.forceMemoryImpl = true;
            } else {
                structType.size = currentOffset;
            }
        } else {
            // 空结构体/联合体
            structType.size = 0;
        }
        structType.members = members;
        structType.bitfieldStorages = bitfieldStorages;
        
        // 存储到类型表 (already registered above, before the members were read)
        structType.beingDefined = false;
        
        // 如果结构体有名称，添加到当前作用域
        if (defNode.name && !this.currentScope.lookupCurrent(defNode.name)) {
            const structSymbol = new SymbolEntry(
                defNode.name,
                { type: structType },
                this.currentScope,
                'type'
            );
            this.currentScope.addSymbol(structSymbol);
        }
    }
	
	processTypeFromDeclaration(typeNode) {
        // 从声明中提取类型信息
        const typeName = this.getTypeNameFromTypeNode(typeNode);
        if (!this.typeTable.has(typeName)) {
            const typeInfo = this.createTypeInfoFromNode(typeNode);
            if (typeInfo) {
                this.typeTable.set(typeName, typeInfo);
            }
        }
    }
	
	createTypeInfoFromNode(typeNode) {
        const typeName = this.getTypeNameFromTypeNode(typeNode);
        const qualifiers = typeNode.getAttribute('qualifiers') || [];

        // 检查是否是结构体/联合体类型
        if (typeName === 'struct' || typeName === 'union') {
            const structName = typeNode.getAttribute('structOrUnionName');
            if (structName && this.structTable.has(structName)) {
                const structType = this.structTable.get(structName);
                const result = new TypeInfo(structName, typeName, structType.size, structType.members);
                result.qualifiers = qualifiers;
                return result;
            } else {
                // 匿名结构体/联合体
                const anonymousType = new TypeInfo(`anonymous_${typeName}`, typeName, 1);
                anonymousType.qualifiers = qualifiers;
                return anonymousType;
            }
        }
        
        // 基本类型或typedef类型
        const baseType = this.typeTable.get(typeName);
        if (baseType) {
            const result = new TypeInfo(typeName, baseType.kind, baseType.size);
            result.qualifiers = qualifiers;
            return result;
        }
        
        return null;
    }
	
	createAliasType(baseType, declarator) {
		/*
		An alias is a COPY of the whole base type, not a shell built from its
		name and outermost size. Typedefs nest (`typedef int *p; typedef p *pp;`),
		and a copy that drops `pointerTo` quietly turns `p` into a plain `int` --
		a pointer that is only not one, which the first dereference crashes on.
		`duplicate()` carries the whole chain, and every level keeps its own
		qualifiers along with it.
		*/
		let aliasType = baseType.duplicate();

		// 处理指针
		if (declarator.pointerDepth > 0) {
			let currentType = aliasType;
			for (let i = 0; i < declarator.pointerDepth; i++) {
				const ptrType = new TypeInfo('', 'pointer', 2);
				ptrType.pointerTo = currentType;
				ptrType.qualifiers = declarator.pointerQualifiers[i] || [];
				currentType = ptrType;
			}
			return currentType;
		}
		
		// 处理数组
		if (declarator.arrayDimensions && declarator.arrayDimensions.length > 0) {
			/*
			A typedef array is built exactly like a variable's: the outermost
			dimension is written first in the program (`int a[3][4]` is an array
			of `int[4]`), so wrap from the innermost out. The array level shows
			the base's qualifiers, as a variable's array layer does.
			*/
			const baseQualifiers = [...aliasType.qualifiers];
			let arrayType = aliasType;
			for (const dim of [...declarator.arrayDimensions].reverse()) {
				/*
				A dimension has to be known while compiling -- the same rule a
				variable declaration enforces, or `arr a;` made from this alias
				would be a variable length array by surprise.
				*/
				let value = dim;
				if (dim.type !== 'NumericLiteral') {
					const folded = this.constantDimensionOf(dim);
					if (folded !== null) {
						value = { type: 'NumericLiteral', value: folded };
					} else {
						this.addError(
							`Variable length arrays are not supported: the size of ` +
							`'${declarator.name}' must be a compile time constant`,
							declarator.location);
					}
				}
				const arrType = new TypeInfo('', 'array',
					arrayType.size * ((typeof value?.value === 'number') ? value.value : 1));
				arrType.arraySize = value;
				arrType.pointerTo = arrayType; // 使用pointerTo指向元素类型
				arrType.qualifiers = [...baseQualifiers];
				arrayType = arrType;
			}
			return arrayType;
		}
		
		return aliasType;
	}
	
	/**
	 * 
	 * @param {string} typeNameRaw 
	 * @returns {TypeInfo}
	 */
		/**
		 * The type a NAME spells out, as a `TypeInfo`.
		 *
		 * A declarator is a base name, some `*`s and some qualifiers, and a
		 * qualifier belongs to the LEVEL it was written on: in `int *remote` the
		 * `remote` follows the `*` and describes the POINTER, while in
		 * `remote int *` it precedes the base and describes the int. Those are
		 * different types, and this is the one place a written type name becomes a
		 * `TypeInfo`, so the level is read off the spelling here rather than
		 * guessed afterwards.
		 *
		 * Each level of the `pointerTo` chain carries its own `qualifiers` --
		 * exactly what `TypeInfo.toString` already prints -- so the level is not
		 * recorded a second time anywhere.
		 *
		 * @param {string} typeNameRaw
		 * @returns {TypeInfo?}
		 */
	/**
	 * Find a type by tag/typedef name, preferring block-scope declarations.
	 *
	 * @param {string} name
	 * @returns {TypeInfo?}
	 */
	lookupTypeInfo(name) {
		for (let scope = this.currentScope; scope; scope = scope.parent) {
			const symbol = scope.lookupCurrent?.(name) ?? null;
			if (symbol?.kind === 'type') {
				const info = symbol.type?.type ?? symbol.type ?? null;
				if (info?.isTypeInfo) return info;
			}
		}
		return this.typeTable.get(name) ?? this.structTable.get(name) ?? null;
	}

	/**
	 * Register a typedef name in the current scope (or the global type table).
	 */
	addTypeAlias(name, type, location = null) {
		if (this.currentScope === this.globalScope) {
			this.typeTable.set(name, type);
			return;
		}
		if (this.currentScope.lookupCurrent(name)) {
			this.addError(`Type '${name}' is already declared in this scope`, location);
			return;
		}
		this.currentScope.addSymbol(new SymbolEntry(name, { type }, this.currentScope, 'type', location));
	}

	getTypeInfo(typeNameRaw) {
		if (typeof typeNameRaw !== 'string') {
			return typeNameRaw;
		}
		/**
		 * @type {TypeInfo?}
		 */
		let result = null;
		/*
		How many pointer levels have been opened. A word written now belongs to
		level `levels + stars`: the stars in its own chunk sit to its LEFT, so in
		`*remote` the qualifier describes the pointer, while in `int*` the word is
		the base itself.
		*/
		let levels = 0;
		/** @type {Map<number, string[]>} */
		const perLevel = new Map();
		const note = (level, q) => {
			const list = perLevel.get(level) ?? [];
			if (!list.includes(q)) list.push(q);
			perLevel.set(level, list);
		};
		/*
		`[]` is an OPEN dimension, and NaN is how an unspecified one is spelled
		everywhere else (`arrayDimensionsOf` normalises it to null). The printer
		turns it back into `[]`.
		*/
		const wrapArray = (element, dimensions) => {
			const sizes = dimensions.map(d => {
				const inside = d.slice(1, -1).trim();
				return (inside === '') ? NaN : parseInt(inside);
			});
			let total = 1;
			for (const s of sizes) total *= s;
			const arr = new TypeInfo('', 'array', total);
			arr.arraySize = sizes;
			arr.pointerTo = element;
			return arr;
		};
		const checkQualifiers = ['const', 'volatile', 'near', 'extern', 'auto',
			'static', 'persistent', 'register', 'remote', 'byname', 'byvaluename'];
		const chunks = String(typeNameRaw).split(/\s+/).filter(c => c.length > 0);
		if (chunks.length === 0) {
			return null;
		}

		for (const chunk of chunks) {
			let stars = 0, word = '';
			for (const chr of chunk) {
				if (chr === '*') stars++;
				else word += chr;
			}
			// Dimensions written onto the name: `int[5]`, or `int [5]`.
			const dimensions = [];
			const bare = word.replace(/\[[0-9]*\]/g, m => { dimensions.push(m); return ''; });
			if (checkQualifiers.includes(bare)) {
				note(levels + stars, bare);
				levels += stars;
				continue;
			}
			if (bare.length === 0) {
				if (dimensions.length > 0) {
					if (!result) {
						console.log(`Internal error: read incorrect type msg ${typeNameRaw}`);
						return null;
					}
					result = wrapArray(result, dimensions);
				}
				// A `*` of its own: it opens a level and names no type.
				levels += stars;
				continue;
			}
			const foundType = this.lookupTypeInfo(bare);
			if (foundType) {
				/*
				A struct that is still being defined (`struct node { struct node
				*next; }`) must hand back the LIVE entry, not a copy: a copy taken
				now is empty and stays empty. The same holds for an incomplete
				forward declaration that a later definition fills.
				*/
				result = (foundType.beingDefined || foundType.incomplete)
					? foundType : foundType.duplicate();
			} else {
				return null;	// Unable to fetch information
			}
			if (dimensions.length > 0) result = wrapArray(result, dimensions);
			levels += stars;
		}
		if (!result) {
			return null;
		}
		/*
		Build the chain outwards and give each level the qualifiers written on
		it. The base keeps whatever qualifiers it already carried: a `const int`
		out of the type table is still a `const int` after a `*` goes on it.
		*/
		const chain = [result];
		for (let i = 0; i < levels; i++) {
			const ptr = new TypeInfo('', 'pointer', 2);
			ptr.pointerTo = chain[chain.length - 1];
			chain.push(ptr);
		}
		chain.forEach((type, level) => {
			const own = perLevel.get(level);
			if (!own || own.length === 0) return;
			type.qualifiers = [...new Set([...(type.qualifiers ?? []), ...own])];
		});
		return chain[chain.length - 1];
	}
	
	calculateTypeSize(typeInfo) {
        if (!typeInfo) return 1; // 默认大小
        
        switch (typeInfo.kind) {
            case 'basic':
            case 'device':
            case 'null':
				return 1;
            case 'pointer':
                return 2;
            case 'struct':
            case 'union':
                return typeInfo.size || 1;
            case 'array':
                if (typeInfo.arraySize) {
                    const elementSize = this.calculateTypeSize(typeInfo.pointerTo);
                    return elementSize * typeInfo.arraySize;
                }
				// TODO: Might be adding warning
                return 1; // 未知大小的数组
            default:
                return 1;
        }
    }

    addError(message, location = null) {
        this.errors.push({
            message,
            line: location ? location.line : 0,
            column: location ? location.column : 0
        });
    }

    addWarning(message, location = null) {
        this.warnings.push({
            message,
            line: location ? location.line : 0,
            column: location ? location.column : 0
        });
    }

    // =============== 访问者方法 ===============

    visitProgram(node) {
        // 遍历所有全局声明和函数
		node.globalDeclarations.forEach(decl => this.visit(decl));
		/*
		Both passes below need the whole program: the set of overloads (a call
		may come before some of them), and the arguments of every call to an
		`auto` function (that is what decides the versions to emit).
		*/
		this.prescanFunctionDeclarations(node);
		/*
		Everything is visited FIRST: an `auto` version is chosen from what the
		call site really hands over, and that is only known once the arguments
		have symbols (a local has none before its function is visited).
		*/
        node.functions.forEach(func => this.visit(func));
		if (this.overloadMode() !== 'none') this.expandAutoTemplates(node);
		this.validateFunctionDefinitions();
		/*
		After the versions exist: an `auto` function reached through a pointer
		is pinned by the version that was made for it, so what is left are the
		functions that have only themselves.
		*/
		this.pinValueTakenRepresentations(node);
		/*
		Prototypes have done their job during semantic analysis. Keeping them in
		the AST makes the optimizer treat a declaration and its definition as two
		functions with the same name; drop the body-less nodes now that calls have
		resolved to their symbols.
		*/
		node.functions = node.functions.filter(func => !!func.body);
    }

    visitstruct(node) {
        this.processStructOrUnionDefinition(node);
    }

    visituinion(node) {
        this.processStructOrUnionDefinition(node);
    }

    // Alias for callers that spell the node type capitalized.
    visitStruct(node) { return this.visitstruct(node); }
    visitUnion(node) { return this.visituinion(node); }

    visitTypedefDeclaration(node) {
        this.processTypedefDeclaration(node);
    }

    visitTypeSpecifier(node) {
        if (node?.typeName === 'enum') this.processEnumDefinition(node, this.currentScope);
    }

    visitFunctionDeclaration(node) {
        // 检查函数是否已声明
        const existingSymbol = this.currentScope.lookupCurrent(node.name);
        let funcSymbol = null;
        let reuse = false;
        if (existingSymbol) {
            if (existingSymbol.kind !== 'function') {
                this.addError(`'${node.name}' is already declared and is not a function`, node.location);
                return;
            }
            /*
            A prototype and a definition share one signature-keyed entry. A
            prototype may repeat, and a definition may follow one; two
            definitions were already rejected by the prescan.
            */
            if (!node.body) {
                this.validateFunctionRedeclaration(existingSymbol, node);
                return;
            }
            if (existingSymbol.isDefined === true) {
                this.addError(`Function '${node.name}' is already defined`, node.location);
                return;
            }
            funcSymbol = existingSymbol;
            reuse = true;
            this.validateFunctionRedeclaration(existingSymbol, node);
        }

		// 获取返回类型名称
		// Added after correctional conversation.
		this.checkOverloading(node);
		const returnTypeName = this.getTypeNameFromTypeNode(node.returnType);
		if (!returnTypeName) {
			this.addError(`Invalid return type for function '${node.name}'`, node.returnType.location);
			return;
		}

        // 创建函数符号
        if (!funcSymbol) {
            funcSymbol = new SymbolEntry(
                node.name,
                {
                    returnType: this.typeToString(this.getTypeNameFromTypeNode(node.returnType)),
                    parameters: node.parameters.map(param => ({
                        name: param.name,
                        type: this.getTypeNameFromTypeNode(param) /*param.type.typeName*/
                        /* Modified in 5th conversation. Whether this is correct remains to be seen! */
                    }))
                },
                this.currentScope,
                'function',
                node.location
            );
            this.currentScope.addSymbol(funcSymbol);
        } else {
            funcSymbol.type.returnType = this.typeToString(this.getTypeNameFromTypeNode(node.returnType));
            funcSymbol.type.parameters = node.parameters.map(param => ({
                name: param.name,
                type: this.getTypeNameFromTypeNode(param)
            }));
        }
        funcSymbol.isPrototype = !node.body;
        funcSymbol.isDefined = !!node.body;
        funcSymbol.declarationNode = node;
        /*
        A prototype only registers the signature; its parameters do not get a
        scope until a definition exists.
        */
        if (!node.body) return;
		if (this.currentScope !== this.globalScope) {
			this.addError(`Function definitions are not allowed inside a block`, node.location);
			return;
		}
		/*
		Not yet: the scope above may not exist yet (a function built by the
		compiler, such as an `auto` instantiation, has none until the next
		lines make one). It is assigned again once it surely does.
		*/

        this.currentFunction = funcSymbol;

        // 进入函数作用域
		let functionScope = node.scope;
		if (!functionScope) {
			node.scope = functionScope = new Scope(this.currentScope, 'f', node, node.name);
			/*
			The scope has to know which declaration it belongs to: several later
			passes (the optimizer's function info, for one) look the body up
			through it. A scope the parser never saw -- one made here for an
			`auto` instantiation -- would otherwise have none.
			*/
			functionScope.astNode = node;
			this.currentScope.children.push(functionScope);
		}
		funcSymbol.owningScope = functionScope;
		this.currentScope = functionScope;

        // 添加参数到作用域
        node.parameters.forEach(param => {
			/*
			Already resolved: a specialised function had its parameter given a
			concrete struct VARIANT. Looking it up by name instead found the
			PATTERN again -- which has no chosen representation -- so the
			member was read as a block/offset pair that does not exist.
			*/
			const gotType = (param.type?.isTypeInfo === true) ? param.type
				: this.getTypeInfo(this.getTypeNameFromTypeNode(param));
			const paramSymbol = new SymbolEntry(
                param.name,
                { type: gotType },
                this.currentScope,
                'parameter',
                param.location
            );
			if (gotType.isNear()) {
				paramSymbol.isNearPointer = true;
			}
			/*
			`void f(struct pt *byname q)` -- the parameter itself carries the
			member NAMES, so it must not be treated as a block/offset pair.
			*/
            if (this.hasByNameQualifier(param)) {
				paramSymbol.usesNamePointer = true;
				paramSymbol.forcedNamePointer = true;
				/*
				A `byname` parameter asks for the representation here; the
				variable it will name belongs to the CALLER, so the parameter is
				what this program knows about.
				*/
				this.noteNamePointerRequest(paramSymbol);
			}
			/*
			An `auto` parameter of an instantiated version: the representation
			this version was made for. Setting it here -- instead of letting the
			call-site notes decide -- is what lets one version take names while
			another takes addresses, which a single function cannot do.
			*/
				/*
				The signature is kept on the FUNCTION node and read back here.
				Putting it on the parameter object instead did not survive: the
				parameter list of a cloned node is not the object the visit walks.
				*/
				let autoRep = param?.autoRep ?? null;
				if (!autoRep) {
					const signature = node.getAttribute?.('autoReps') ?? null;
					if (signature) {
						const repsAll = String(signature).split('|');
						const at = (node.parameters ?? []).indexOf(param);
						if (at >= 0 && at < repsAll.length) autoRep = repsAll[at];
					}
				}
			if (autoRep) this.applyAutoRepToParamSymbol(paramSymbol, gotType, autoRep);
            this.currentScope.addSymbol(paramSymbol);
        });

        // 分析函数体
        if (node.body) {
            this.visit(node.body);
        }

        // 返回父作用域
        this.currentScope = this.currentScope.parent;
        this.currentFunction = null;
    }

    /**
     * A prototype and a definition (or two prototypes) must agree on the
     * return type and parameter types. Parameter NAMES may differ.
     *
     * @param {SymbolEntry} existing
     * @param {any} node
     * @returns {void}
     */
    validateFunctionRedeclaration(existing, node) {
        const returnType = this.typeToString(this.getTypeNameFromTypeNode(node.returnType));
        if (existing.type?.returnType && returnType !== existing.type.returnType) {
            this.addError(`Function '${node.name}' is redeclared with return type `
                + `'${returnType}', previously '${existing.type.returnType}'`, node.location);
        }
        const now = (node.parameters ?? []).map(p => String(this.getTypeNameFromTypeNode(p)));
        const before = (existing.type?.parameters ?? []).map(p => String(p?.type ?? p));
        if (before.length !== now.length || before.some((t, i) => t !== now[i])) {
            this.addError(`Function '${node.name}' is redeclared with a different parameter list`,
                node.location);
        }
    }

    /**
     * A prototype is allowed to have no definition, but a call to it is not.
     *
     * @returns {void}
     */
    validateFunctionDefinitions() {
        const visit = scope => {
            scope?.symbols?.forEach(symbol => {
                if (symbol.kind !== 'function') return;
                if (symbol.isPrototype === true && symbol.called === true) {
                    const globalDefinition = this.globalScope.lookup?.(symbol.name) ?? null;
                    if (globalDefinition?.kind === 'function' && globalDefinition.isDefined === true) {
                        symbol.owningScope = globalDefinition.owningScope;
                        symbol.type = globalDefinition.type;
                        symbol.isDefined = true;
                        return;
                    }
                    this.addError(`Function '${symbol.name}' is declared but never defined`,
                        symbol.declarationNode?.location ?? symbol.location);
                }
            });
            scope?.children?.forEach(visit);
        };
        visit(this.globalScope);
    }

	// Modified on 1 Dec, to be verified
	// This function has manual changes!!!
	/**
	 * 
	 * @param {VariableDeclarationNode} node 
	 * @returns 
	 */
    visitVariableDeclaration(node) {
        const baseTypeName = this.getTypeNameFromTypeNode(node.type);
        const qualifiers = node.type.getAttribute('qualifiers') || [];
		if (node.type?.type === 'TypeSpecifier' && node.type.typeName === 'enum') {
			this.processEnumDefinition(node.type, this.currentScope);
		}
		
		// 检查是否有存储类说明符
		const storageClass = node.type.storageClass; // auto, register, static, extern
        
        // 获取基础类型信息
		
        let baseType = this.getTypeInfo(baseTypeName);
        if (!baseType) {
            this.addError(`Unknown type '${baseTypeName}'`, node.type.location);
            return;
        }
        
        // 创建带有限定符的类型
        /*
        A COPY of the base type, not a shell made from its name and outermost
        size: when the base is itself a typedef'd array (`typedef int arr[4];
        arr a;`) the dimensions travel with it, and a shell that drops
        `arraySize` leaves a variable whose array is size-unknown -- which the
        first access walks into a crash. `duplicate()` carries the whole chain
        (each level owns its own qualifiers); members are re-copied so the base
        is not shared.
        */
        const varType = baseType.duplicate();
        if (baseType.members) varType.members = [...baseType.members];
		varType.qualifiers = [... new Set([...baseType.qualifiers, ...qualifiers])];
		
		const warningTypes = ['device', 'content_t'];
		const warningStorages = ['volatile'];
		const warningKinds = ['pointer', 'array'];

        node.declarators.forEach(declarator => {
            // 检查变量是否已声明
            const existingSymbol = this.currentScope.lookupCurrent(declarator.name);
            if (existingSymbol) {
                this.addError(`Variable '${declarator.name}' is already declared in this scope`, declarator.location);
                return;
            }

            // 创建变量类型（处理指针和数组）
            let finalType = varType;
			let pointerAccess = false;
            
            // 处理指针
            if (declarator.pointerDepth > 0) {
                let currentType = finalType;
                for (let i = 0; i < declarator.pointerDepth; i++) {
                    const ptrType = new TypeInfo('', 'pointer', 2);
                    ptrType.pointerTo = currentType;
                    ptrType.qualifiers = declarator.pointerQualifiers[i] || [];
                    currentType = ptrType;
                }
                finalType = currentType;
				if (varType.qualifiers.includes('near') && !finalType.qualifiers.includes('near')) finalType.qualifiers.push('near');
            } else {
				if (baseType.functionTo) {
					finalType.functionTo = baseType.functionTo;
				}
				// TODO: Check array support for typedef
				if (baseType.arrayDimensions && baseType.arrayDimensions.length > 0) {
					// baseType seems immutable so far
					// array kind already inherited!
					finalType.arraySize = baseType.arraySize;
					finalType.arrayDimensions = baseType.arrayDimensions;
				}
			}
            
            // 处理数组
			/*
			`int a[] = {3, 4, 5}`: the size is left out and taken from the
			initializer instead. C only allows the OUTERMOST one to be left out,
			but there is no harm in accepting an inner one too when the nesting
			makes it obvious.
			*/
			this.deduceRemoteArrayDimensions(declarator);
			/*
			`char a[] = "hi"` is a C character array: expand the literal into
			codes plus NUL before the dimension is deducted from it.
			*/
			if (baseTypeName === 'char'
				&& declarator.arrayDimensions?.length > 0
				&& declarator.initializer?.type === 'StringLiteral') {
				declarator.initializer = this.characterArrayInitializer(declarator.initializer);
				declarator.initializer.parent = declarator;
			}
			this.deduceArrayDimensions(declarator, baseType);
            if (declarator.arrayDimensions && declarator.arrayDimensions.length > 0) {
                let arrayType = finalType;
                for (const dim of declarator.arrayDimensions.reverse()) {
					/*
					A dimension has to be known while compiling. A const of a
					literal counts; anything else would be a variable length
					array, which this compiler does not support (the stack
					frame size is fixed at compile time), so say so instead of
					silently pretending the size is 1.
					*/
					if (dim.type !== 'NumericLiteral') {
						const folded = this.constantDimensionOf(dim);
						if (folded !== null) {
							dim.value = folded;
							dim.type = 'NumericLiteral';
						} else {
							this.addError(
								`Variable length arrays are not supported: the size of ` +
								`'${declarator.name}' must be a compile time constant`,
								declarator.location);
						}
					}
                    const arrType = new TypeInfo('', 'array', arrayType.size * ((typeof dim.value === 'number') ? dim.value : 1));
                    arrType.arraySize = dim;
                    arrType.pointerTo = arrayType;
					arrType.qualifiers = [...finalType.qualifiers];
                    arrayType = arrType;
                }
                finalType = arrayType;
				//pointerAccess = true;
            }

			/*
			Peel off pointers and array layers. A struct/union has no "single"
			type underneath it, so the recursion stops there -- otherwise the
			walk would run off the end into `null`.
			*/
			const extractToBottom = /**
			@param {TypeInfo} extr
			@returns {TypeInfo}
			*/ extr => {
				if (!extr || !extr.isTypeInfo) return extr;
				if (!extr.isStrictPointerImpl()) return extr;
				const single = extr.extractSingle?.() ?? null;
				if (!single || single === extr) return extr;
				return extractToBottom(single);
			};

			/*
			Only warn when the variable really ends up in memory: an array that
			was asked for a register layout (array("embedded...") / "encoded")
			holds its elements there, where a device is perfectly fine.
			*/
			const requestedImpl = declarator.getAttribute?.('arrayImplementation') ?? null;
			const staysInRegisters = !!requestedImpl && requestedImpl !== 'traditional';
			const incompleteByValue = t => {
				if (!t || !t.isTypeInfo) return false;
				if (t.incomplete === true) return true;
				if (t.kind === 'array') return incompleteByValue(t.pointerTo);
				return false;
			};
			if (incompleteByValue(finalType)) {
				this.addError(`Variable '${declarator.name}' has incomplete type '${finalType.toString()}'`,
					declarator.location ?? node.location);
				return;
			}
			if (!staysInRegisters && (finalType.qualifiers.some(q => warningStorages.includes(q)) || warningKinds.includes(finalType.kind)) && warningTypes.includes(extractToBottom(finalType).name)) {
				this.addWarning(`Variable ${declarator.name} (with type ${varType.toString()}) cannot be stored in memory`, declarator.location);
			}

            // 创建变量符号
            const varSymbol = new SymbolEntry(
                declarator.name,
                { 
                    type: finalType,
                    isConst: finalType.isConst(),
                    isVolatile: finalType.isVolatile(),
					isExtern: finalType.qualifiers.includes('extern')
                },
                this.currentScope,
                'variable',
                declarator.location
            );
			if (finalType.isNear()) {
				varSymbol.isNearPointer = true;
			}
			
			// 设置register标记
			if (storageClass === 'register') {
				varSymbol.isRegister = true;
			}
			if (storageClass === 'static') {
				varSymbol.isStatic = true;
				//varSymbol.accessThroughPointer = true;	// i.e. [omitted] need memory allocation
			}
			if (storageClass === 'persistent') {
				varSymbol.isPersistent = true;
			}
			if (storageClass === 'auto') {
				varSymbol.isAuto = true;
			}
			/*
			if (storageClass === 'extern') {
				varSymbol.accessThroughPointer = true;
			}
			*/
			if (baseTypeName === 'auto device') {
				varSymbol.isAutoDevice = true;
			}
			
			// 添加const和volatile信息
            const qualifiers = node.type.getAttribute('qualifiers') || [];
            varSymbol.isConst = finalType.isConst();
            varSymbol.isVolatile = finalType.isVolatile();
			varSymbol.isExtern = finalType.isExtern();
			
			// 检查是否为全局变量
            varSymbol.isGlobal = this.currentScope === this.globalScope;
			// Meaning that the variable requires special memory space. This doesn't mean that it's a pointer itself!
			pointerAccess = pointerAccess || (varSymbol.isVolatile && !varSymbol.isRegister);
			if (finalType.kind !== 'basic') {
				varSymbol.implementAsPointer = varSymbol.implementAsPointer || pointerAccess;	// Whether still implementing them as pointer
			} else {
				// Only basic types consider 'accessThroughPointer'
				varSymbol.accessThroughPointer = pointerAccess;
			}
			declarator.dataType = varSymbol.extractType();

            this.currentScope.addSymbol(varSymbol);
			/*
			`int a[];` with no initializer: an UNBOUND HANDLE. It is ONE register
			-- the cell that will hold a packed handle once `a = b;` binds it -- so
			the whole handle machinery (delivery, indexing, `lenof`) is reused for
			it, exactly as if it were a handle parameter. (The `remote` no-size
			case was already refused in `deduceArrayDimensions`; this is a guard
			for anything that slipped past.)
			*/
			if (declarator.getAttribute?.('unboundHandle') === true) {
				if (this.typeHasRemoteQualifier(finalType)) {
					this.addError(
						`The size of array '${declarator.name}' is neither given nor deducible: ` +
						`a remote array has to be bound to one already, as in ` +
						`'remote int s[] = remote(p, u)'`,
						declarator.location);
				} else {
					varSymbol.isUnboundHandle = true;
					/* The one representation this cell can have. */
					varSymbol.arrayParamRep = 'handle';
				}
			}

			/*
			`int a[10] = array("embedded_divided", {3, 4});`
			`array(...)` is a compile time directive: it names the layout the
			array must use, and may carry the initial contents. It is consumed
			here -- the rest of the compiler only ever sees the contents.
			*/
			this.consumeArrayDirective(declarator, varSymbol);
			/*
			`int *byname r` -- the pointer holds a NAME, so `*r` is
			`read / write @this <the name>`. Written on the declaration it is an
			explicit request, exactly like `byname(&c)`, and so it needs the
			target version but not `#pragma optimize(pointer)`.

			Only the parameter form and the `int *byname remote` form were
			honoured; on a variable the qualifier was silently dropped and the
			pointer fell back to a block/offset pair -- which is a memory
			access, and therefore wrong for a pointer meant to carry a name.
			*/
			const pointeeKind = finalType.kind === 'pointer'
				? (finalType.pointerTo?.kind ?? null) : null;
			if (finalType.kind === 'pointer' && !varSymbol.isRemote
				&& !['struct', 'union'].includes(pointeeKind)
				&& this.hasByNameQualifier(declarator)) {
				varSymbol.usesNamePointer = true;
				varSymbol.forcedNamePointer = true;
				/*
				`int *byname p = &x` names a variable without going through
				`byname()`, so nothing else would remember that this program
				asked for a name. The target is recorded when the initializer
				names one; otherwise the pointer stands in for the request.
				*/
				const init = declarator.initializer;
				const target = (init?.type === 'UnaryExpression' && init.operator === '&'
					&& init.argument?.type === 'Identifier')
					? (this.currentScope?.lookup?.(init.argument.name) ?? null) : null;
				if (target) {
					target.forcedNamePointer = true;
					this.noteNamePointerRequest(target);
				} else {
					this.noteNamePointerRequest(varSymbol);
				}
			}
			/*
			`int *remote p` -- a pointer that ITSELF lives in another processor.
			Reaching it would mean reading two registers out of the other
			processor, which is not implemented; the check below is where the
			support would go.
			*/
			/*
			`int *remote p`: the pointer itself lives in the other processor.
			Reaching it means reading the pair `p_block` / `p_pos` from there.
			*/
			if (this.isRemotePointerDeclarator(declarator)) {
				if (!this.supportsRemotePointer()) {
					this.addError(`A pointer that is itself remote ('int *remote') is not supported yet`,
						declarator.location);
					return;
				}
				varSymbol.isRemote = true;
				varSymbol.remoteStored = true;
				/*
				`int *byname remote q`: the pointer also asks for the NAME form, so
				it is ONE register over there instead of the block/pos pair.
				*/
				varSymbol.remoteStoredByName = this.hasByNameQualifier(declarator);
			}
			this.consumeRemoteDirective(declarator, varSymbol, finalType, qualifiers);

			/*
			`int *s = byname(&c);` -- the pointer itself has to hold a NAME,
			and that has to be decided before anything asks for its storage.
			*/
			if (declarator.initializer && this.containsByName(declarator.initializer)
				&& finalType.kind === 'pointer') {
				varSymbol.usesNamePointer = true;
				varSymbol.forcedNamePointer = true;
			}
			/*
			`struct pt *p = &st;` where `st` is a `register` struct: the pointer
			has to carry member names, since a register value has no address.
			*/
			if (finalType.kind === 'pointer' && declarator.initializer
				&& declarator.initializer.type === 'UnaryExpression'
				&& declarator.initializer.operator === '&') {
				const inner = declarator.initializer.argument;
				if (inner && inner.type === 'Identifier') {
					const src = this.currentScope.lookup(inner.name) ?? null;
					const srcType = src?.myType?.() ?? null;
					/*
					Only when the struct really stays in registers: a nested struct,
					one too wide for the threshold, or one compiled without the pragma
					is degraded to memory instead, and then the pointer needs an
					ADDRESS -- forcing a name packet here would make `p->m` step a
					name pointer, which has no address to step.
					*/
					if (src?.addressedByName || (src?.isRegister && srcType
						&& (srcType.kind === 'struct' || srcType.kind === 'union')
						&& this.allowsStructNamePointer(srcType))) {
						varSymbol.usesNamePointer = true;
						varSymbol.forcedNamePointer = true;
						varSymbol.addressedByName = true;
					}
				}
			}
			/*
			A `struct X *byname` where the struct does NOT stay in registers
			(nested / too wide for the threshold / compiled without the pragma) is
			degraded to a memory struct above, so the pointer keeps a real
			block/offset ADDRESS -- the byname name-representation is refused for
			struct pointees. But the `byname` qualifier on the type is the very
			fact `widthOfType` reads: it would answer 1 (a name word) for a value
			that truly occupies two registers. Make the type describe the storage:
			drop the qualifier, exactly when the name representation is not used.
			*/
			if (finalType.kind === 'pointer'
				&& ['struct', 'union'].includes(finalType.pointerTo?.kind ?? null)
				&& varSymbol.addressedByName !== true
				&& this.hasByNameQualifier(declarator)) {
				finalType.qualifiers = (finalType.qualifiers ?? [])
					.filter(q => q !== 'byname' && q !== 'byvaluename');
				declarator.dataType = varSymbol.extractType();
			}

			/*
			A string literal is a native `string_t` value, not an addressable
			array. A `const char*` may still point at it: materialise a hidden
			`const char[]` once and point there. A mutable `char*` is refused --
			text is read-only, exactly like a C string literal.
			*/
			if (declarator.initializer?.type === 'StringLiteral'
				&& finalType.kind === 'pointer'
				&& finalType.pointerTo?.kind === 'basic'
				&& finalType.pointerTo.name === 'char') {
				if (this.isConstCharPointer(finalType)) {
					const hidden = this.materializeStringLiteral(declarator.initializer);
					const reference = ASTBuilder.identifier(hidden);
					reference.setAttribute('location', declarator.initializer.location);
					reference.parent = declarator;
					declarator.initializer = reference;
				} else {
					this.addError(
						`Cannot initialize '${this.typeToString(finalType)}' with a string literal: ` +
						`the characters are read-only. Use 'const char*' for a view, or ` +
						`'char ${declarator.name}[] = "..."' for a mutable copy.`,
						declarator.initializer.location);
					declarator.initializer = null;
				}
			}

            // 检查初始化表达式
            if (declarator.initializer) {
                this.visit(declarator.initializer, {
					givenSymbol: varSymbol,
					givenType: declarator.dataType
				});
                
                // 类型检查初始化表达式
                const initType = this.getExpressionType(declarator.initializer);
                /*
                `int s[] = r;`: settled here, because the length has to come from
                what `s` is given, and that is not known until now.
                */
                if (declarator.getAttribute?.('openDimensionBinding') === true) {
                    this.bindOpenDimensionArray(declarator, varSymbol, initType);
                }
                /*
                A function pointer naming a CONCRETE struct may be given a
                function whose parameter is the template that struct spells
                out: the version for that variant is emitted and the pointer
                takes its line number (see
                `specializeStructTemplateFunctions`).
                */
                const fpAcceptsTemplate = (fp, fn) => {
                    const fpParams = this.functionPointerParametersOf(fp);
                    const fnParams = this.functionPointerParametersOf(fn);
                    if (!fpParams || !fnParams) return false;
                    if (fpParams.length !== fnParams.length) return false;
                    return fpParams.every((p, i) => {
                        const want = (typeof p?.type === 'string') ? this.getTypeInfo(p.type) : p?.type;
                        const got = (typeof fnParams[i]?.type === 'string')
                            ? this.getTypeInfo(fnParams[i].type) : fnParams[i]?.type;
                        if (!want || !got) return false;
                        if (!['struct', 'union'].includes(want.kind)) return false;
                        const canonical = this.canonicalStructType(got.kind === 'pointer'
                            ? got.pointerTo : got);
                        if (canonical?.isTemplate !== true) return false;
                        /*
                        The variant the pointer asks for: each `auto` member
                        takes the representation that struct spells out.
                        */
                        const reps = (canonical.templateMembers ?? []).map(mn => {
                            const m = (want.members ?? []).find(x => x.name === mn);
                            return (m?.namePointer === true) ? 'name' : 'memory';
                        });
                        const variant = this.structVariantOf(canonical, reps);
                        const vm = variant.members ?? [], wm = want.members ?? [];
                        return vm.length === wm.length && vm.every((m, k) =>
                            m.name === wm[k].name
                            && (m.namePointer === true) === (wm[k].namePointer === true));
                    });
                };
                /*
                A function pointer may equally be given a function with an
                `auto` parameter: the version the pointer's own type picks is
                emitted, and the pointer takes that version's line number. The
                two sides then do not have the same parameter types -- one is a
                pattern, the other an instantiation of it -- so they must not be
                compared as they stand.
                */
                const paramQuals = p => this.qualifiersOfTypeInfo(this.parameterTypeInfo(p));
                const fpAcceptsAutoVersion = (fp, fn) => {
                    const fpParams = this.functionPointerParametersOf(fp);
                    const fnParams = this.functionPointerParametersOf(fn);
                    if (!fpParams || !fnParams) return false;
                    if (fpParams.length !== fnParams.length) return false;
                    // The pointer is what picks the version, so it has to be concrete.
                    if (fpParams.some(p => paramQuals(p).includes('auto'))) return false;
                    // And the function has to be a pattern there is something to specialise.
                    if (!fnParams.some(p => paramQuals(p).includes('auto'))) return false;
                    // Every parameter has to name a representation a version can be made for.
                    return fpParams.every(p => !!this.autoRepFromExpectedType(p?.type ?? p));
                };
                if (initType && !this.isTypeCompatible(finalType, initType)
                    && !fpAcceptsTemplate(finalType, initType)
                    && !fpAcceptsAutoVersion(finalType, initType)) {
                    this.addError(
                        `Cannot initialize '${this.typeToString(finalType)}' with '${this.typeToString(initType)}'`,
                        declarator.initializer.location
                    );
				}

                varSymbol.initialized = true;

				/*
				A character array initialised from a literal includes its NUL, so
				`char a[2] = "hi"` cannot fit. The same count check catches any
				other initializer list that names more elements than the array
				has; C requires the excess to be diagnosed rather than dropped.
				*/
				if (finalType.kind === 'array'
					&& declarator.initializer?.type === 'InitializerList') {
					const outer = this.arrayDimensionsOf(finalType)[0];
					const count = declarator.initializer.children.length;
					if (outer && count > outer) {
						this.addError(
							`Too many initializers for '${declarator.name}': ` +
							`${count} value(s) for ${outer} element(s)`,
							declarator.initializer.location);
					}
				}
            }
			// 检查const变量初始化
			if (finalType.isConst() && !varSymbol.isAutoDevice && !declarator.initializer) {
				this.addError(`Const variable '${declarator.name}' must be initialized or be an automatically-linked device`, declarator.location);
			}
        });
    }

	/**
	 * The initializer list behind a declarator's initializer.
	 *
	 * `array("embedded", {...})` is still in place at this point (it is
	 * consumed later), so it has to be looked through -- otherwise
	 * `int a[] = array("embedded", {1, 2, 3, 4})` would look like it has no
	 * initializer at all and its size could not be deduced.
	 *
	 * @param {ASTNode?} initializer
	 * @returns {ASTNode?} an InitializerList, or null
	 */
	initializerListOf(initializer) {
		if (!initializer) return null;
		if (initializer.type === 'InitializerList') return initializer;
		if (initializer.type === 'FunctionCall' && initializer.callee?.name === 'array') {
			const second = (initializer.arguments ?? [])[1];
			if (second && second.type === 'InitializerList') return second;
		}
		return null;
	}

	/**
	 * Settle an array declared with an open dimension and bound to another
	 * array in its initializer (`int s[] = r;`).
	 *
	 * The length is not written and cannot be counted from an initializer list,
	 * so the only place it can come from is `r` -- and there is only one way to
	 * keep it: `s` has to BE `r`, not a copy of it. That is also what makes the
	 * feature affordable. A copy would have to be allocated at a length only
	 * known once `r` is, and every access would go through it; an alias costs
	 * nothing and writes back to `r`, exactly as C's array-to-pointer decay
	 * suggests.
	 *
	 * So the type is taken from `r` -- which is also what fixes `symbol.size`:
	 * left on its own `int[]` has size NaN, and a stack frame advanced by NaN
	 * never finishes -- and the array is aliased to it.
	 *
	 * @param {any} declarator
	 * @param {SymbolEntry} symbol
	 * @param {TypeInfo?} initType
	 * @returns {void}
	 */
	bindOpenDimensionArray(declarator, symbol, initType) {
		if (!initType || initType.kind !== 'array') {
			this.addError(
				`The size of array '${declarator.name}' is neither given nor deducible: ` +
				`write a size, or an initializer that is itself an array`,
				declarator.location);
			return;
		}
		if (this.hasOpenDimension(initType)) {
			this.addError(
				`Neither '${declarator.name}' nor what it is given says how many elements `
				+ `there are: one of them has to`,
				declarator.location);
			return;
		}
		const target = this.symbolOfArrayExpression(declarator.initializer);
		if (!target) {
			this.addError(
				`'${declarator.name}' has no length of its own, so it can only be bound to `
				+ `a named array -- there is nothing to take a length from here`,
				declarator.location);
			return;
		}
		/*
		The type is replaced but the wrapper is kept: `isConst` and `isVolatile`
		were already read off the declaration and are still true of `s`.
		*/
		const wrapper = symbol.type;
		symbol.type = (wrapper && typeof wrapper === 'object' && 'type' in wrapper)
			? { ...wrapper, type: initType } : initType;
		symbol.arrayAliasOf = target;
		symbol.isRemote = target.isRemote === true || this.typeHasRemoteQualifier(initType);
	}

	/**
	 * Fill in the array dimensions that were left out (`int a[] = {...}`).
	 *
	 * Counting is done level by level: the number of items at one level is the
	 * size of that dimension. A dimension that WAS written is not counted but
	 * still descends one level.
	 *
	 * @param {ASTNode} declarator
	 * @returns {void}
	 */
	/**
	 * `char a[] = "hi"` -- a C character array, not a native string.
	 *
	 * The literal is expanded into its character codes plus the terminating
	 * NUL, so the ordinary array machinery deducts the dimension and lays the
	 * cells out. The native `string_t` value stays one cell; this path only
	 * runs when the destination is a `char` array.
	 *
	 * @param {StringLiteralNode} literal
	 * @returns {InitializerListNode}
	 */
	characterArrayInitializer(literal) {
		const list = new InitializerListNode();
		list.location = literal.location;
		for (const ch of String(literal.value ?? '')) {
			const cell = ASTBuilder.numericLiteral(ch.codePointAt(0) ?? 0);
			cell.location = literal.location;
			list.addChild(cell);
		}
		const nul = ASTBuilder.numericLiteral(0);
		nul.location = literal.location;
		list.addChild(nul);
		return list;
	}

	/**
	 * Materialise a string literal as a compile-time `const char[]` so that a
	 * `const char*` can point at it. Only literals used through a character
	 * pointer pay for this: a plain `string_t s = "hi"` stays one cell.
	 *
	 * @param {StringLiteralNode} literal
	 * @returns {string} the hidden array's name
	 */
	materializeStringLiteral(literal) {
		const text = String(literal.value ?? '');
		const cached = this.stringLiteralArrays.get(text);
		if (cached) return cached;

		const name = `__strlit_${this.stringLiteralCounter++}`;
		const typeSpec = ASTBuilder.typeSpecifier('char');
		typeSpec.setAttribute('location', literal.location);
		typeSpec.setAttribute('qualifiers', ['const']);
		typeSpec.storageClass = '';

		const declarator = ASTBuilder.variableDeclarator(name);
		declarator.location = literal.location;
		declarator.arrayDimensions = [ASTBuilder.numericLiteral([...text].length + 1)];
		declarator.initializer = this.characterArrayInitializer(literal);
		/*
		A literal must be addressable: force the traditional memory layout,
		because an encoded/register constant has no block+offset to point at.
		*/
		declarator.setAttribute('arrayImplementation', 'traditional');

		const declaration = ASTBuilder.variableDeclaration(typeSpec, [declarator]);
		declaration.location = literal.location;

		const savedScope = this.currentScope;
		const savedFunction = this.currentFunction;
		this.currentScope = this.globalScope;
		this.currentFunction = null;
		this.visit(declaration);
		this.currentScope = savedScope;
		this.currentFunction = savedFunction;

		const symbol = this.globalScope.lookup(name);
		if (symbol) symbol.requestedArrayImplementation = 'traditional';
		this.ast.globalDeclarations.push(declaration);
		this.stringLiteralArrays.set(text, name);
		return name;
	}

	/**
	 * Whether a type is a pointer to `const char` (the only pointer a literal
	 * may initialise; a mutable `char*` would invite writes to read-only text).
	 *
	 * @param {TypeInfo} type
	 * @returns {boolean}
	 */
	isConstCharPointer(type) {
		if (!type || type.kind !== 'pointer') return false;
		const target = type.pointerTo;
		if (!target || target.kind !== 'basic' || target.name !== 'char') return false;
		return (target.qualifiers ?? []).includes('const');
	}

	/**
	 * Replace a literal with a reference to its materialised `const char[]`
	 * when the destination is `const char*`. Every other destination keeps the
	 * one-cell `string_t` value.
	 *
	 * @param {ASTNode?} node
	 * @param {TypeInfo?} expectedType
	 * @param {ASTNode?} parent
	 * @returns {ASTNode?}
	 */
	coerceStringLiteralToCharPointer(node, expectedType, parent = null, force = false) {
		if (!node || node.type !== 'StringLiteral') return node;
		if (!force && !this.isConstCharPointer(expectedType)) return node;
		const hidden = this.materializeStringLiteral(node);
		const reference = ASTBuilder.identifier(hidden);
		reference.setAttribute('location', node.location);
		reference.parent = parent;
		return reference;
	}

	deduceArrayDimensions(declarator, baseType) {
		const dims = declarator.arrayDimensions;
		if (!Array.isArray(dims) || dims.length === 0) return;
		if (!dims.some(d => !d)) return;	// Nothing left out
		const list = this.initializerListOf(declarator.initializer);
		if (!list) {
			/*
			`int s[] = r;`: the length is not written and not countable, but it
			does not have to be -- the array being bound already has one, and `s`
			can take it. The dimension is left OPEN here (`NaN`, exactly as a
			parameter's `[]` reads back) and settled once the initializer's type
			is known, which is later than this.
			*/
			if (declarator.initializer) {
				for (let i = 0; i < dims.length; i++) {
					if (!dims[i]) dims[i] = ASTBuilder.numericLiteral(NaN);
				}
				declarator.setAttribute('openDimensionBinding', true);
				return;
			}
			/*
			`int a[];` with no initializer is an UNBOUND HANDLE: the cell exists
			(one register) but holds no handle until a binding writes one in --
			`a = b;` (or, later, `vecalias(&a, b);`). The length stays NaN: it is
			genuinely unknown until then. An unbound handle is PROVABLY unreadable
			-- reading it before any binding, and leaving it never bound at all,
			are compile errors (checked once the whole program has been seen) --
			and one that escapes unbound traps at run time.
			*/
			if (baseType && this.typeHasRemoteQualifier(baseType)) {
				/*
				A REMOTE array can only ever be bound by `remote(p, u)`. There is
				nothing LOCAL to bind it to, and an unbound handle cannot cross
				processors, so this stays the refusal it always was.
				*/
				this.addError(
					`The size of array '${declarator.name}' is neither given nor deducible: ` +
					`a remote array has to name its other-processor target, as in ` +
					`'remote int s[] = remote(p, u)'`,
					declarator.location);
				for (let i = 0; i < dims.length; i++) {
					if (!dims[i]) dims[i] = ASTBuilder.numericLiteral(1);
				}
				return;
			}
			/*
			The handle keeps its own single cell; the array's "size" is NaN only
			while it is open, and `symbol.size` is fixed by the generator (one
			register). Binding later writes the packed handle into the cell.
			*/
			for (let i = 0; i < dims.length; i++) {
				if (!dims[i]) dims[i] = ASTBuilder.numericLiteral(NaN);
			}
			declarator.setAttribute('unboundHandle', true);
			return;
		}
		let level = list;
		for (let i = 0; i < dims.length; i++) {
			if (dims[i]) {
				level = this.descendInitializer(level);
				continue;
			}
			const count = this.initializerCountOf(level);
			/*
			Even on failure put something in: leaving `null` here makes the
			loop that builds the type read `.type` of null and throw, which
			hides the real message.
			*/
			dims[i] = ASTBuilder.numericLiteral(count > 0 ? count : 1);
			if (count <= 0) {
				this.addError(
					`Cannot deduce dimension ${i + 1} of array '${declarator.name}'`,
					declarator.location);
				return;
			}
			level = this.descendInitializer(level);
		}
	}

	/**
	 * @param {ASTNode?} list
	 * @returns {ASTNode?} the first sub-list, if there is one
	 */
	descendInitializer(list) {
		const items = list?.values ?? list?.children ?? null;
		const first = Array.isArray(items) ? items[0] : null;
		return (first && first.type === 'InitializerList') ? first : null;
	}

	/**
	 * How many items an initializer list holds.
	 *
	 * @param {ASTNode?} list
	 * @returns {number}
	 */
	initializerCountOf(list) {
		const items = list?.values ?? list?.children ?? null;
		return Array.isArray(items) ? items.length : 0;
	}

	/**
	 * Recognize `T a[N] = array("<implementation>"[, <initializer list>])`.
	 *
	 * The directive is removed from the tree; what is left behind is the
	 * initializer list (if any), so that everything downstream sees an
	 * ordinary array declaration carrying one extra attribute.
	 *
	 * @param {ASTNode} declarator
	 * @param {SymbolEntry} symbol
	 */
	consumeArrayDirective(declarator, symbol) {
		const initializer = declarator.initializer;
		if (!initializer || initializer.type !== 'FunctionCall') return;
		const callee = initializer.callee;
		if (!callee || callee.name !== 'array') return;
		const args = initializer.arguments ?? [];
		if (args.length === 0) {
			this.addError(`array() needs the name of an implementation`, initializer.location);
			return;
		}
		const first = args[0];
		if (first.type !== 'StringLiteral') {
			this.addError(`The first parameter of array() must be a string literal`, initializer.location);
			return;
		}
		const requested = String(first.raw).replace(/^"|"$/g, '');
		const known = ['traditional', 'embedded', 'embedded_divided', 'encoded',
			'embedded_lookup', 'embedded_lookup_item', 'embedded_lookup_liquid',
			'embedded_lookup_unit', 'embedded_lookup_block'];
		if (!known.includes(requested)) {
			this.addError(`Unknown array implementation '${requested}' (expected one of ${known.join(', ')})`,
				initializer.location);
			return;
		}
		const contents = (args.length >= 2 && args[1].type === 'InitializerList') ? args[1] : null;
		if (requested === 'encoded' && !contents) {
			this.addError(`An encoded array must be given its contents: array("encoded", {...})`,
				initializer.location);
			return;
		}
		declarator.setAttribute('arrayImplementation', requested);
		symbol.requestedArrayImplementation = requested;
		/*
		An array named after a lookup table can only be as long as that table.
		*/
		const category = this.lookupCategoryOf(requested);
		if (category) {
			this.checkLookupCapacity(symbol.name, category,
				this.arrayDimensionsOf(symbol.myType?.())[0] ?? 0, initializer.location);
		}
		declarator.initializer = contents;
		if (contents) {
			this.recordArrayInitialValues(symbol, contents, requested === 'encoded',
				initializer.location);
		}
	}

	/**
	 * `remote int ru[] = remote(processor1, u);` -- the size comes from the
	 * array on the other side, which has to be known before the type is built.
	 *
	 * @param {any} declarator
	 * @returns {void}
	 */
	deduceRemoteArrayDimensions(declarator) {
		const dims = declarator.arrayDimensions;
		if (!Array.isArray(dims) || dims.length === 0) return;
		if (dims[dims.length - 1]) return;		// already written out
		const call = declarator.initializer;
		if (!call) return;
		const called = (call.type === 'BuiltinCall') ? call.functionName
			: (call.callee ? (call.callee.name ?? call.callee.value) : null);
		if (called !== 'remote') return;
		const targetNode = (call.arguments ?? [])[1];
		if (!targetNode || (targetNode.type !== 'Identifier' && targetNode.type !== 'StringLiteral')) return;
		const target = this.lookupSymbol?.(targetNode.name)
			?? this.currentScope?.lookup?.(targetNode.name) ?? null;
		const type = target?.myType?.() ?? null;
		if (!type || type.kind !== 'array') return;
		const total = this.totalArraySizeOf(type);
		if (!total) return;
		const node = { type: 'NumericLiteral', value: String(total), raw: String(total) };
		dims[dims.length - 1] = node;
	}

	/**
	 * @param {TypeInfo} type
	 * @returns {number}
	 */
	totalArraySizeOf(type) {
		let sizes = type.arraySize ?? [];
		if (!Array.isArray(sizes)) sizes = [sizes];
		let total = 1;
		for (const dim of sizes) {
			const value = (typeof dim === 'number') ? dim
				: (dim && typeof dim === 'object' && typeof dim.value === 'number') ? dim.value : 1;
			total *= value;
		}
		return total;
	}

	/**
	 * Whether the `remote` qualifier was written after a `*`, which makes the
	 * POINTER remote rather than what it points at.
	 *
	 * @param {any} declarator
	 * @returns {boolean}
	 */
	isRemotePointerDeclarator(declarator) {
		const levels = declarator?.pointerQualifiers ?? [];
		return levels.some(list => (list ?? []).includes('remote'));
	}

	/**
	 * RESERVED: whether a `remote` ARRAY is supported. Reaching one means
	 * naming `u_0`, `u_1`, ... in the other processor, and picking the name at
	 * run time when the subscript is not constant.
	 *
	 * @returns {boolean}
	 */
	supportsRemoteArray() {
		return true;
	}

	/**
	 * RESERVED: whether `int *remote` (a pointer stored in another processor)
	 * is supported. Kept as a single place to switch on when the two register
	 * read / write it needs is implemented.
	 *
	 * @returns {boolean}
	 */
	/**
	 * Whether a pointer may carry the NAMES of a struct's members.
	 * Enabled by `#pragma optimize(struct_pointer[, n])` on v150 or newer.
	 * @returns {boolean}
	 */
	supportsStructNamePointer() {
		if ((this.targetVersion ?? 0) < 150) return false;
		const cfg = this.compiler?.extraConfig?.getAttribute?.('optimizeOption') ?? null;
		return cfg ? cfg.doStructPointerOptimize === true : false;
	}

	/**
	 * How many registers a name based pointer to this type would need: one per
	 * scalar member. Kept here (rather than in the infrastructure) because the
	 * decision has to be made while analysing, before any value class exists.
	 * @param {TypeInfo?} type
	 * @returns {number}
	 */
	structPacketWidth(type, depth = 0) {
		if (!type || !type.isTypeInfo || depth > 8) return 1;
		if ((type.members ?? []).some(m => {
			const mt = m.type ?? m.memberType;
			return mt && mt.isTypeInfo && (mt.kind === 'struct' || mt.kind === 'union');
		})) return Infinity;
		if (type.kind === 'pointer' || type.kind === 'array') return 2;
		if (type.kind !== 'struct' && type.kind !== 'union') return 1;
		if (type.isPointerImpl?.()) return 2;
		const members = type.members ?? [];
		if (members.length === 0) return 1;
		const widths = members.map(m => this.structPacketWidth(m.type ?? m.memberType, depth + 1));
		return type.kind === 'union' ? Math.max(...widths) : widths.reduce((a, b) => a + b, 0);
	}

	/**
	 * Whether `&st` may be taken for a struct kept in registers: the pragma
	 * must be on and the packet must fit the threshold.
	 * @param {TypeInfo?} type
	 * @returns {boolean}
	 */
	allowsStructNamePointer(type) {
		if (!this.supportsStructNamePointer()) return false;
		/*
		A member that is itself a struct has no single register name, so such a
		struct can never be carried this way -- whatever the threshold says.
		*/
		const nested = (type?.members ?? []).some(m => {
			const mt = m.type ?? m.memberType;
			return !!mt && mt.isTypeInfo && (mt.kind === 'struct' || mt.kind === 'union');
		});
		if (nested) return false;
		const cfg = this.compiler?.extraConfig?.getAttribute?.('optimizeOption') ?? {};
		const limit = (typeof cfg.structPointerThreshold === 'number')
			? cfg.structPointerThreshold : Infinity;
		return this.structPacketWidth(type) <= limit;
	}

	supportsRemotePointer() {
		return true;
	}

	/**
	 * Whether a declarator (or a parameter) asks for the "holds a name"
	 * representation by writing `byname` as a POINTER qualifier:
	 *   struct pt *byname q
	 * `byname` is a reserved word, so this is a plain token test.
	 *
	 * @param {any} node
	 * @returns {boolean}
	 */
	hasByNameQualifier(node) {
		/*
		Either place may carry it: the declarator when the pointer belongs to
		the declared name, or the type specifier when it was parsed there.
		(`??` cannot be used: an empty array is not null.)
		*/
		const levels = [
			...(node?.pointerQualifiers ?? []),
			...(node?.type?.pointerQualifiers ?? [])
		];
		return levels.some(list => (list ?? []).includes('byname'));
	}

	/**
	 * Whether an expression contains a `byname(&x)` call.
	 *
	 * @param {ASTNode?} node
	 * @returns {boolean}
	 */
	containsByName(node) {
		const seen = new Set();
		const walk = n => {
			if (!n || typeof n !== 'object' || seen.has(n)) return false;
			seen.add(n);
			if (n.functionName === 'byname'
				|| (n.callee && (n.callee.name ?? n.callee.value) === 'byname')) return true;
			for (const key of Object.keys(n)) {
				if (key === 'parent') continue;
				const child = n[key];
				if (Array.isArray(child)) {
					for (const item of child) if (walk(item)) return true;
				} else if (child && typeof child === 'object') {
					if (walk(child)) return true;
				}
			}
			return false;
		};
		return walk(node);
	}

	/**
	 * The global variable whose register name is `assembly` (`"g:.u"` -> `u`).
	 *
	 * `remote(@this, "g:.u")` names the variable by string. When this program
	 * declares it too, that declaration has to be found: `remote(...)` is the
	 * only thing mentioning it, and its initializer is consumed -- so without
	 * the link the declaration looks unused, is removed, and its elements are
	 * never initialised (every read of a self remote array returns 0).
	 *
	 * @param {string} assembly The register name, as written in the string
	 * @returns {SymbolEntry?}
	 */
	globalByAssembly(assembly) {
		const wanted = String(assembly ?? '');
		if (!wanted || !this.globalScope) return null;
		for (const symbol of this.globalScope.symbols.values()) {
			if (symbol.kind === 'function' || symbol.kind === 'type') continue;
			if (symbol.getAssemblySymbol?.() === wanted) return symbol;
		}
		return null;
	}

	/**
	 * `remote T x = remote(<processor>, <variable>);`
	 *
	 * `remote(dev, x)` means: ON THE DEVICE `dev` there is a variable named
	 * `x`, and this declaration operates THAT one. Every access is a
	 * `read` / `write` to `dev`, so the variable need not be declared in this
	 * program at all -- its NAME is all that is needed.
	 *
	 * A declaration of the same name here is therefore only a DESCRIPTION of
	 * the variable over there (its type, and for an array its length and
	 * layout); it does NOT become the thing being read and written. The one
	 * exception is `remote(@this, x)`: the device is this very processor, so
	 * the local declaration really is the target.
	 *
	 * `dev` may be any device expression. For a variable over there it should
	 * be a global (a local's register name depends on optimisations that differ
	 * between two programs).
	 *
	 * The initializer is consumed: what is left is the binding, which the code
	 * generator turns into two `set`s (device, name).
	 *
	 * @param {any} declarator
	 * @param {SymbolEntry} symbol
	 * @param {TypeInfo} finalType
	 * @returns {void}
	 */
	consumeRemoteDirective(declarator, symbol, finalType, qualifiers = [], deferred = false) {
		const initializer = declarator.initializer;
		if (!initializer) return;
		const called = (initializer.type === 'BuiltinCall')
			? initializer.functionName
			: (initializer.callee ? (initializer.callee.name ?? initializer.callee.value) : null);
		if (called !== 'remote') return;
		const args = initializer.arguments ?? [];
		const location = initializer.location;
		/*
		`remote int *p`: the qualifier belongs to what is pointed at, and the
		pointer type built for the declarator does not carry it -- so look at
		the declaration's own qualifier list as well.
		*/
		if (!finalType.isRemote() && !qualifiers.includes('remote') && !symbol.remoteStored) {
			this.addError(`remote() needs the declaration to be qualified 'remote', as in 'remote int x = remote(...)'`,
				location);
			declarator.initializer = null;
			return;
		}
		/*
		A remote array is a flat row of registers on the other side, one name
		per element. Two or more dimensions have no such shape, and without
		saying so here the failure came much later, as an internal error about
		registers.
		*/
		const dimCount = (declarator.arrayDimensions ?? []).length
			|| (symbol.arrayDimensions ?? symbol.dimensions ?? []).length || 1;
		if (finalType.kind === 'array' && dimCount > 1) {
			this.addError(`A 'remote' array can only have one dimension: its elements are `
				+ `single registers of the other processor`, location);
			declarator.initializer = null;
			return;
		}
		if (args.length < 2 || args.length > 3) {
			this.addError(`remote() takes the processor and the variable, and optionally `
				+ `the layout both sides use (such as "embedded_lookup_item")`, location);
			declarator.initializer = null;
			return;
		}
		/*
		The layout may be given here too: when the variable is named by a string
		there is no local declaration to read it from, and the two processors
		have to agree on it explicitly anyway.
		*/
		const layoutNode = args.length >= 3 ? args[2] : null;
		const layout = (layoutNode && layoutNode.type === 'StringLiteral')
			? String(layoutNode.raw ?? layoutNode.value).replace(/^"|"$/g, '') : null;
		const deviceNode = args[0];
		const targetNode = args[1];
		/*
		`remote(@this, x)` is the one case where the local declaration IS the
		target: the device named is this very processor.
		*/
		const selfDevice = deviceNode?.type === 'Identifier'
			&& String(deviceNode.name) === '@this';
		// `&s` gives a pointer, a plain `s` binds the variable itself
		let inner = targetNode;
		if (inner.type === 'UnaryExpression' && inner.operator === '&') inner = inner.argument;
		if (!inner || (inner.type !== 'Identifier' && inner.type !== 'StringLiteral')) {
			this.addError(`The variable of remote() must be a name (or its address &name)`, location);
			declarator.initializer = null;
			return;
		}
		let targetSymbol = this.lookupSymbol?.(inner.name) ?? this.currentScope?.lookup?.(inner.name) ?? null;
		/*
		`remote int turn = remote(dev, turn)` names the variable `turn` OF THE
		OTHER PROCESSOR -- the declaration being made here must not shadow it,
		or it would look like "a remote variable reaching a remote variable".
		*/
		if (targetSymbol && targetSymbol === symbol) targetSymbol = null;
		/*
		A name visible in a NON-global scope is taken as it is -- but it is a
		local, whose register name depends on optimisations that differ between
		two processors, so reaching it from another processor is not reliable.
		*/
		if (targetSymbol && !targetSymbol.isGlobal && !selfDevice) {
			this.addWarning(`'${inner.name}' is a local: its register name depends on how this `
				+ `program is optimised, so another processor may not find it under that name. `
				+ `Declare it globally to reach it remotely`, location);
		}
		/*
		A string names the variable of the OTHER processor, which need not exist
		here at all -- but it MAY: `remote(@this, "g:.u")` reaches this very
		program. Resolving the string to the local declaration is what keeps it
		alive, because `remote(...)` is the only thing that mentions it and the
		initializer is consumed here. Without this the array is never
		initialised, so every element reads back as 0.
		*/
		if (!targetSymbol && targetNode.type === 'StringLiteral') {
			// A StringLiteral carries its text in `value` / `raw`, not in `name`.
			targetSymbol = this.globalByAssembly(
				String(targetNode.raw ?? targetNode.value ?? '').replace(/^"|"$/g, ''));
		}
		/*
		The variable of the other processor does not have to exist here at all:
		a string literal names it directly (useful for pointers, which would
		otherwise have to be declared locally only to be named).
		*/
		if (!targetSymbol && targetNode.type !== 'UnaryExpression'
			&& targetNode.type === 'StringLiteral') {
			symbol.remoteDevice = deviceNode;
			symbol.remoteName = String(targetNode.raw ?? targetNode.value).replace(/^"|"$/g, '');
			symbol.isRemote = true;
			if (layout) symbol.requestedArrayImplementation = layout;
			declarator.initializer = null;
			return;
		}
		if (!targetSymbol && inner.type === 'Identifier' && !selfDevice) {
			/*
			Only an array whose length is not written here has a reason to wait:
			a declaration further down may still supply it.
			*/
			const lengthUnknown = finalType && finalType.kind === 'array'
				&& (() => {
					const dims = this.arrayDimensionsOf(finalType);
					return !dims.length || dims[0] === null;
				})();
			if (lengthUnknown && !deferred) {
				/*
				Take the initializer away for now: it is a `remote(...)` call,
				and nothing here knows how to type-check one. It is put back when
				the binding is retried.
				*/
				(this.pendingRemoteLinks ??= []).push(
					{ declarator, symbol, finalType, qualifiers, initializer: declarator.initializer });
				declarator.initializer = null;
				return;
			}
			if (lengthUnknown) {
				this.addError(`'${inner.name}' is not declared here, so remote() cannot know how `
					+ `long the array on the other processor is: give the length, as in `
					+ `'remote int ru[5] = remote(processor1, ${inner.name})'`, location);
				declarator.initializer = null;
				return;
			}
			/*
			Not declared here -- so take the symbol a global `x` of this type
			would have. Nothing is defined by that; it is what carries the
			description of the variable over there.
			*/
			targetSymbol = this.synthesiseRemoteTarget(inner.name, finalType, location);
			if (layout) targetSymbol.requestedArrayImplementation = layout;
		}
		if (!targetSymbol) {
			/*
			Not declared YET: `remote int ru[] = remote(p1, u);` may well appear
			before `int u[4];`. Nothing about this binding can be decided before
			the whole program is read, so remember it and try again once it has
			been -- see `finalizeRemoteLinks`.
			*/
			if (targetNode.type !== 'StringLiteral' && targetNode.type !== 'UnaryExpression') {
				/*
				Take the initializer away for now: it is a `remote(...)` call,
				and nothing here knows how to type-check one. It is put back when
				the binding is retried.
				*/
				(this.pendingRemoteLinks ??= []).push(
					{ declarator, symbol, finalType, qualifiers, initializer: declarator.initializer });
				declarator.initializer = null;
				return;
			}
			this.addError(`'${inner.name}' is not declared, so it cannot be reached remotely`, location);
			declarator.initializer = null;
			return;
		}

		if (targetSymbol.isRemote) {
			this.addError(`'${inner.name}' is itself remote: remote() cannot chain through two processors`, location);
			declarator.initializer = null;
			return;
		}
		/*
		An array is reached element by element, and each element is a register
		of the other processor -- which needs the subscript to be known and a
		representation this compiler does not build yet. Reserved below.
		*/
		if (targetSymbol.myType?.()?.kind === 'array') {
			if (!this.supportsRemoteArray()) {
				this.addError(`A remote array is not supported yet`, location);
				declarator.initializer = null;
				return;
			}
			if (!targetSymbol.isGlobal) {
				this.addWarning(`A remote array has to be global on both sides`, location);
			}
			/*
			Reaching an array means naming its elements one by one, so they have
			to BE registers. `encoded` (the whole array as one string) has none,
			and `lookup` names them after contents instead of after the array.
			*/
			const requested = targetSymbol.requestedArrayImplementation ?? null;
			/*
			The layout belongs to BOTH sides: the remote declaration may name it
			(the third argument of remote()), and the array itself may. Agreeing
			is what makes `ru[1]` mean the same register on both processors.
			*/
			if (layout && requested && layout !== requested) {
				this.addError(`'${targetSymbol.name}' is declared array("${requested}"), `
					+ `but remote() asks for "${layout}": the two processors have to agree `
					+ `on the layout`, location);
			}
			if (requested === null) {
				/*
				Nothing was asked for, so the layout is chosen automatically --
				and an automatically chosen `lookup` table is exactly what two
				processors may guess differently. Pick the plain register layout
				instead: it only needs the array's own name, which both sides
				already share.
				*/
				targetSymbol.requestedArrayImplementation = layout ?? 'embedded_divided';
			} else if (requested === 'encoded' || requested === 'traditional') {
				this.addError(`A remote array has to keep its elements in registers: `
					+ `'${targetSymbol.name}' is declared '${requested}'`, location);
				} else if (this.lookupCategoryOf(requested)) {
					/*
					Allowed, and the table is named -- but the array may not be
					longer than that table, or the extra elements would read as 0.
					*/
					const effective = layout ?? requested;
					const category = this.lookupCategoryOf(effective);
					if (category) {
						this.checkLookupCapacity(targetSymbol.name, category,
							this.arrayDimensionsOf(targetSymbol.myType?.())[0] ?? 0, location);
					}
				} else if (requested === 'embedded_lookup') {
				/*
				Allowed, but only with the table named: two processors that
				guess may well guess differently.
				*/
				this.addError(`A remote array using a lookup table must name it: `
					+ `use array("embedded_lookup_item", ...) (or _liquid, _unit, _block) `
					+ `instead of array("embedded_lookup", ...)`, location);
			}
			/*
			`remote(...)` is the only thing that mentions the array, and the
			initializer is consumed here -- so nothing would be left to keep it
			alive and its elements would never be initialised.
			*/
			if (selfDevice) targetSymbol.isRemoteTarget = true;
		}
		/*
		Only `remote(@this, x)` really uses the declaration of this program:
		elsewhere the declaration is just a description of a variable that lives
		on the other processor, and emitting registers for it here would only
		waste them.
		*/
		if (selfDevice) targetSymbol.isRemoteTarget = true;
		declarator.initializer = null;
		symbol.remoteDevice = deviceNode;
		symbol.remoteTarget = targetSymbol;
		symbol.remoteName = targetSymbol.getAssemblySymbol();
		if (layout) symbol.requestedArrayImplementation = layout;
		symbol.remoteTakeAddress = targetNode.type === 'UnaryExpression';
		symbol.isRemote = true;
	}

	/**
	 * `int *s = byname(&c);`
	 *
	 * The same representation as an automatic name pointer, but asked for
	 * explicitly -- so it does not need `#pragma optimize(pointer)`. (It still
	 * needs the version that can `read` from `@this`.)
	 *
	 * @param {any} node The call
	 * @returns {boolean} whether it was a byname() call
	 */
	consumeByNameCall(node) {
		const args = node.arguments ?? [];
		if (args.length !== 1) {
			this.addError(`byname() requires exactly 1 argument: the address of a variable`, node.location);
			return true;
		}
		const inner = args[0];
		if (inner.type !== 'UnaryExpression' || inner.operator !== '&'
			|| !inner.argument || inner.argument.type !== 'Identifier') {
			this.addError(`byname() needs the address of a variable, as in byname(&c)`, node.location);
			return true;
		}
		const symbol = this.lookupSymbol?.(inner.argument.name)
			?? this.currentScope?.lookup?.(inner.argument.name) ?? null;
		if (!symbol) {
			this.addError(`'${inner.argument.name}' is not declared`, node.location);
			return true;
		}
		if (!symbol.isGlobal) {
			this.addWarning(`byname(&${inner.argument.name}) points at a local: its register name may change`,
				node.location);
		}
		/*
		Remember it: the optimizer's name pointer analysis is what keeps such a
		variable out of memory, and it normally refuses without the pragma.
		*/
		symbol.forcedNamePointer = true;
		this.noteNamePointerRequest(symbol);
		node.setAttribute('bynameTarget', symbol.getAssemblySymbol());
		node.setAttribute('bynameSymbol', symbol);
		node.dataType = this.getTypeInfo('void*');
		return true;
	}

	/**
	 * Record that this program asked for a name pointer.
	 *
	 * Every way of asking ends up here, so "does this program use name
	 * pointers at all" has one answer instead of three:
	 *   - `byname(&x)`            -> the TARGET, `x`
	 *   - `int *byname p = &x`    -> the target when the initializer names one
	 *   - `void f(int *byname p)` -> the parameter, whose target is the CALLER's
	 * The optimizer's name pointer analysis reads this to know that a program
	 * which asked for a name has to be looked at, and the `auto` resolution
	 * reads it because the representation exists in this program.
	 *
	 * @param {SymbolEntry?} [symbol] the variable involved, when known
	 */
	noteNamePointerRequest(symbol = null) {
		if (!this.forcedNamePointers) this.forcedNamePointers = new Set();
		const name = symbol?.getAssemblySymbol?.() ?? symbol?.name ?? null;
		if (name) this.forcedNamePointers.add(name);
		return this.forcedNamePointers;
	}

	/**
	 * The numeric value of one item of an initializer list.
	 *
	 * A content constant such as `@lead` counts as a number too: its id is
	 * known from the content tables (or from `#pragma id`).
	 *
	 * @param {ASTNode?} item
	 * @returns {number?} null when it is not a compile time number
	 */
	numberOfInitializerItem(item) {
		if (!item) return null;
		if (item.type === 'NumericLiteral') {
			const value = Number(item.value);
			return Number.isFinite(value) ? value : null;
		}
		/*
		`{(int)(@thorium), ...}`: the element is a content constant written with
		an explicit cast, because the array itself is `const int`. The cast does
		not change which content it is, so look through it -- otherwise such an
		array silently becomes all zeros.
		*/
		if (item.type === 'CastExpression') {
			return this.numberOfInitializerItem(item.expression);
		}
		if (item.type === 'Identifier' && typeof item.name === 'string' && item.name[0] === '@') {
			const table = this.contentTable;
			if (!table) return null;
			for (const category of ['item', 'liquid', 'unit', 'block']) {
				const id = table.idOf(category, item.name);
				if (id !== undefined) return (id === null) ? null : id;
			}
			return null;
		}
		return null;
	}

	/**
	 * Remember the contents of an array given with a literal list.
	 *
	 * Everything here must be a compile time number, because these are exactly
	 * the arrays that may be stored as an encoded table instead of in memory.
	 * An `encoded` array has no other way to hold its values, so for it the
	 * contents are mandatory; for the rest a non-numeric element simply means
	 * "this one cannot use the constant representations".
	 *
	 * @param {SymbolEntry} symbol
	 * @param {ASTNode} list An InitializerList
	 * @param {boolean} required
	 * @param {any} location For the error message
	 * @returns {void}
	 */
	recordArrayInitialValues(symbol, list, required, location = null) {
		const items = list.values ?? list.children ?? [];
		if (!Array.isArray(items) || items.length === 0) return;
		const numbers = items.map(item => this.numberOfInitializerItem(item));
		const bad = numbers.findIndex(v => v === null || !Number.isFinite(v));
		if (bad >= 0) {
			if (required) {
				const raw = items[bad]?.name ?? items[bad]?.raw ?? items[bad]?.value ?? '?';
				this.addError(
					`An encoded array can only hold numbers; element ${bad} ('${raw}') is not one`,
					location);
			}
			// Not usable as a constant table, but the array itself is still fine
			return;
		}
		symbol.arrayInitialValues = numbers;
	}

	/**
	 * 
	 * @param {NumericLiteralNode} node 
	 */
	visitNumericLiteral(node) {
		//node.dataType = this.typeTable.get('int');
		if (node.value === true || node.value === false) {
			node.dataType = this.typeTable.get('bool');
		} else if (node.raw.indexOf('.') !== -1 || node.raw.slice(-1) === 'f') {
			node.dataType = this.typeTable.get('float');
		} else {
			node.dataType = this.typeTable.get('int');
		}
	}

	/**
	 * 
	 * @param {StringLiteralNode} node 
	 * @remark A double-quoted literal is a native Mindustry string (`string_t`).
	 *         `char` is the ordinary one-cell character/number type.
	 */
	visitStringLiteral(node) {
		node.dataType = this.typeTable.get('string_t');
	}

	/**
	 * 
	 * @param {CharacterLiteralNode} node
	 * @remark A single-quoted literal is an `int` holding the character's ASCII
	 * value, unlike the double-quoted `"a"` which stays a `char`
	 * (`docs/OPEN_WORK.md` 7.1).
	 */
	visitCharacterLiteral(node) {
		node.dataType = this.typeTable.get('int');
	}

	/**
	 * 
	 * @param {NullLiteralNode} node 
	 */
	visitNullLiteral(node) {
		node.dataType = this.typeTable.get('null_t');
	}

	/**
	 * Get type name from a declarator, not only a type node.
	 * NOTE: CANNOT be a function.
	 * 
	 * @param {DeclaratorNode} decl 
	 */
	getTypeNameFromDeclarator(decl) {
		const simpleType = this.getTypeNameFromTypeNode(decl.type);
		let suffix = '';
		if (decl.arrayDimensions && decl.arrayDimensions.length) {
			suffix = ' ' + decl.arrayDimensions.map(dim => `[${dim.value}]`).join('');
		}
		return simpleType + suffix;
	}

	// 5th conversation
	// 新增辅助方法：从类型节点中提取类型名称
	// 7th (1 Dec)
	// 修改getTypeNameFromTypeNode以处理指针和结构体
	// Priority adjusted manually !!!
	// Also add pointer dereference manually
	// This function doesn't case const qualifier
	/**
	 * 
	 * @param {TypeSpecifierNode} typeNode 
	 * @returns 
	 */
    getTypeNameFromTypeNode(typeNode) {
        if (!typeNode) return null;
		/*
		Already a resolved type: happens when a function is specialised and its
		parameter is given the concrete variant. Asking for its syntax node
		then found nothing, and the parameter was declared with a null type.
		*/
		if (typeNode.isTypeInfo === true) return typeNode.name;
        
		let prefix = "";
		/*
		The `*`s carry their OWN qualifiers: `int *remote` is a remote POINTER,
		`remote int *` is a pointer to a remote int -- two different types, so
		each level has to come out on its own star. A plain level prints a bare
		`*`, exactly as before. (`pointerDepth` lives on the parameter node, and
		on the type specifier of a function pointer.)
		*/
		let ptrSuffix = '';
		const depth = typeNode.pointerDepth ?? typeNode.type?.pointerDepth ?? 0;
		const levelQuals = typeNode.pointerQualifiers ?? typeNode.type?.pointerQualifiers ?? [];
		for (let i = 0; i < depth; i++) {
			const own = levelQuals[i] ?? [];
			ptrSuffix += '*' + (own.length > 0 ? ' ' + own.join(' ') : '');
		}
		
		if (typeNode.type === 'TypeSpecifier' && typeNode.getAttribute('qualifiers')) {
			const attributes = typeNode.getAttribute('qualifiers');
			if (attributes.length > 0)
				prefix = attributes.join(' ') + ' ';
		}

		// 处理结构体/联合体类型
        if (typeNode.type === 'TypeSpecifier' && 
            (typeNode.typeName === 'struct' || typeNode.typeName === 'union')) {
            const structName = typeNode.getAttribute('structOrUnionName');
            return prefix + (structName || typeNode.typeName) + ptrSuffix;
        }
		// 枚举类型：`enum Tag` / `enum { ... }`
		if (typeNode.type === 'TypeSpecifier' && typeNode.typeName === 'enum') {
			const enumName = typeNode.getAttribute('enumName');
			return prefix + (enumName || 'enum') + ptrSuffix;
		}

		if (typeNode.arrayDimensions && typeNode.arrayDimensions.length) {
			/*
			An unspecified dimension (`int p[]`) has no node to read a value
			from -- it is exactly the "any size" the caller is allowed to pass.
			*/
			ptrSuffix += ' ' + typeNode.arrayDimensions.map(dim => `[${dim?.value ?? ''}]`).join('');
		}
		
        // 如果是TypeSpecifier节点
        if (typeNode.typeName && typeof typeNode.typeName === 'string') {
            return prefix + typeNode.typeName + ptrSuffix;
        }
		if (typeof typeNode.type === 'object') {
			return prefix + this.getTypeNameFromTypeNode(typeNode.type) + ptrSuffix;
		}
        
        // 如果是标识符节点（处理typedef定义的类型）
        if (typeNode.type === 'Identifier') {
            return typeNode.name + ptrSuffix;
        }
        
        return null;
    }

    visitIdentifier(node) {
		const specialTypes = this.specialTypes;
		if (node.name.length && node.name[0] === '@') {
			if (node.name === '@counter') {
				this.addWarning(`Deprecated to use @counter inside program`, node.getAttribute('location'));
			}
			/*
			String/message length and character indexing arrived with the
			v150 string instructions. Refuse the property itself when the
			target cannot support it, instead of emitting a sensor that reads
			null in game.
			*/
			if ((node.name === '@size' || node.name === '@bufferSize')
				&& this.targetVersion < 150) {
				this.addError(`${node.name} requires v150 or higher`, node.getAttribute('location'));
			}
			if (specialTypes[node.name]) {
				node.dataType = specialTypes[node.name];
				return;
			}
			/*
			if (objectList.includes(node.name)) {
				node.dataType = this.typeTable.get('item_t');
			} else if (liquidList.includes(node.name)) {
				node.dataType = this.typeTable.get('liquid_t');
			} else if (unitList.includes(node.name)) {
				node.dataType = this.typeTable.get('unit_t');
			} else {
				node.dataType = this.typeTable.get('content_t');
			}
			*/
			node.dataType = this.typeTable.get('content_t');
			/*
			A `@name` nobody declared and no table knows is still a content
			constant, but the compiler cannot tell WHICH one, so mark the node:
			an implicit conversion to `item_t` & friends is refused (an explicit
			cast is still allowed, it simply cannot be folded away).
			*/
			if (this.contentTable && this.contentTable.isOpaque(node.name)) {
				node.setAttribute('opaqueContent', true);
				/*
				Mark the TYPE as well, so every compatibility check (assignment,
				initialisation, argument passing) sees it: the compiler cannot tell
				which content this is, so it may not silently become an `item_t`.
				An explicit cast is still allowed -- that is the programmer saying
				"I know better" -- but its result is not a compile time constant.
				*/
				const marked = this.typeTable.get('content_t').duplicate();
				// `duplicate()` shares the annotations object: a fresh one keeps
				// the marker on this type only
				marked.annotations = new AttributeClass();
				marked.annotations.setAttribute('opaqueContent', true);
				node.dataType = marked;
			}
			return;
		}
        const symbol = this.currentScope.lookup(node.name);
        if (!symbol) {
            this.addError(`Undeclared identifier '${node.name}'`, node.location);
            return;
        }

        symbol.used = true;
        node.symbol = symbol; // 将符号关联到节点

        // 设置节点类型
        if (symbol.kind !== 'type') {
            node.dataType = this.getTypeInfo(symbol.extractType());
        }
    }

	/**
	 * 
	 * @param {CastExpression} node 
	 */
	visitCastExpression(node) {
		node.dataType = this.getExpressionType(node);
		this.visit(node.expression, {
			givenType: node.dataType
		});
	}

    visitBinaryExpression(node) {
        this.visit(node.left);
        this.visit(node.right);

        const leftType = this.getExpressionType(node.left);
        const rightType = this.getExpressionType(node.right);

        if (!leftType || !rightType) {
            return;
        }

        /*
        `string_t` is the native Mindustry string, so `+` concatenates two of
        them. Whether it can actually be done is decided later: only two
        literals can be joined at compile time, and there is no instruction
        that joins two strings at run time. `char` is a NUMBER and takes the
        ordinary arithmetic path.
        */
        const isNativeString = t => !!t && (t.name === 'string_t');
        if (node.operator === '+' && isNativeString(leftType) && isNativeString(rightType)) {
            node.dataType = this.getTypeInfo('string_t');
            return;
        }

        // 检查操作符的类型兼容性
        if (!this.isTypeCompatibleForOperator(node.operator, leftType, rightType)) {
            this.addError(
                `Operator '${node.operator}' cannot be applied to types '${leftType}' and '${rightType}'`,
                node.location
            );
            return;
        }

        // 设置表达式结果类型
        node.dataType = this.getResultType(node.operator, leftType, rightType);
    }

    visitUnaryExpression(node) {
        this.visit(node.argument);
		const argType = this.getExpressionType(node.argument);
		
		if (!argType) return;
		
		const operator = node.operator;
		
		switch (operator) {
			case '*': // 解引用操作
				if (!this.isValidDereference(argType)) {
					this.addError(`Cannot dereference non-pointer type '${this.typeToString(argType)}'`, node.location);
					return;
				}
				
				// 设置表达式结果类型
				// The discard was of no reason ...
				node.dataType = argType.pointerTo; //.discardQualifier(['volatile']);
				break;
				
			case '&': // 取地址操作
				// 检查操作数是否为左值
				if (!this.isLValue(node.argument)) {
					this.addError(`Cannot take address of non-lvalue`, node.location);
					return;
				}
				
				/*
				Taking the address of a `register` variable used to be forbidden
				outright. It is fine when the pointer can carry NAMES instead of
				an address -- that is precisely the representation a register
				value demands. A struct qualifies; a scalar only does when name
				pointers are on at all.
				*/
				if (this.isRegisterVariable(node.argument)) {
					const registerSymbol = (node.argument.type === 'Identifier')
						? (this.currentScope.lookup(node.argument.name) ?? null) : null;
					const registerType = registerSymbol?.myType?.() ?? argType;
					const isAggregate = !!registerType && registerType.isTypeInfo
						&& (registerType.kind === 'struct' || registerType.kind === 'union');
					/*
					A struct can only be reached by NAME when that representation
					is enabled; otherwise it still has to go into memory.
					*/
					const named = (isAggregate && this.allowsStructNamePointer(registerType))
						|| (!!registerType && registerType.kind === 'pointer');
					if (named) {
						if (registerSymbol) {
							registerSymbol.addressedByName = true;
							registerSymbol.forcedNamePointer = true;
						}
					} else if (!isAggregate) {
						/*
						A scalar `register` variable has neither an address nor a name
						representation, so there is nothing to point at.
						*/
						this.addError(`Cannot take address of register variable`, node.location);
						return;
					}
					/*
					An aggregate falls through on purpose: it is too wide for a name
					packet, or it nests another struct, or the pragma is off.
					`markVariableAsAddressed` below then degrades it to the in-memory
					copy of its type -- the same path any struct takes -- instead of
					refusing a program that is perfectly writable in C.
					*/
				}
				
				// 标记变量已被取地址
				this.markVariableAsAddressed(node.argument);
				
				// 创建指针类型
				const ptrType = new TypeInfo('', 'pointer', 2);
				ptrType.pointerTo = argType;
				/*
				A HANDLE array (an open dimension, or a remote array) is ONE
				register, so &a is a NAME pointer to that register -- 1 word,
				not a block/offset pair. The type has to say so, or widthOfType
				(the same fact the code generator works from) would disagree with
				what is actually emitted.
				*/
				if (argType && argType.isTypeInfo && argType.kind === 'array'
						&& widthOfType(argType) === 1) {
					ptrType.qualifiers = ['byname'];
				}
				node.dataType = ptrType;
				break;
				
			case '+': case '-': // 正负号
				if (!this.isNumericType(argType.name)) {
					this.addError(`Unary '${operator}' requires numeric type`, node.location);
					return;
				}
				node.dataType = argType;
				break;
				
			case '~': // 按位取反
				if (!this.isIntegerType(argType.name)) {
					this.addError(`Unary '${operator}' requires integer type`, node.location);
					return;
				}
				node.dataType = argType;
				break;
				
			case '!': // 逻辑非
				node.dataType = this.typeTable.get('int'); // 返回int类型（0或1）
				break;
				
			case '++': case '--': // 递增递减
				if (!this.isLValue(node.argument)) {
					this.addError(`'${operator}' requires lvalue`, node.location);
					return;
				}
				
				if (!this.isNumericType(argType.name) && !argType.isPointerImpl()) {
					this.addError(`'${operator}' requires numeric type`, node.location);
					return;
				}
				
				// 检查const变量
				if (argType.isConst()) {
					this.addError(`Cannot modify const variable with '${operator}'`, node.location);
				}
				
				node.dataType = argType;
				break;
				
			default:
				this.addError(`Unknown unary operator '${operator}'`, node.location);
				break;
		}
    }
	
	// 添加辅助方法检查是否有效的解引用操作
	isValidDereference(type) {
		return type && (type.kind === 'pointer' || type.kind === 'array');
	}
	
	// 添加辅助方法检查是否为register变量
	isRegisterVariable(node) {
		if (node.type === 'Identifier') {
			const symbol = this.currentScope.lookup(node.name);
			return symbol && symbol.isRegister;
		}
		return false;
	}
	
	/**
	 * Mark a struct/union type as one that must be stored in memory.
	 *
	 * The flag goes onto the *canonical* type -- the object kept in
	 * `structTable`, which is shared by every use of the struct, including the
	 * member entries of every struct that embeds it. That sharing is what makes
	 * the requirement spread outwards: once `struct inner` must live in memory,
	 * `struct outer { struct inner i; ... }` reports `isStrictPointerImpl()` as
	 * well and is forced into memory too.
	 *
	 * @param {TypeInfo} type
	 * @returns {void}
	 */
	/**
	 * The "in memory" variant of a struct/union type.
	 *
	 * Taking the address of a struct held in registers is impossible -- a
	 * processor cannot name a group of registers. Rather than degrading the whole
	 * type (which would drag every other instance of it into memory too), an
	 * implicit COPY of the type is made and only that copy is marked as stored in
	 * memory. The variable whose address was taken switches to the copy; every
	 * other instance of the same struct keeps the original type and stays in
	 * registers.
	 *
	 * A struct whose DEFINITION already demands memory (it embeds an array, say)
	 * has no such copy: every instance of it is in memory anyway, so the type
	 * itself is handed back unchanged.
	 *
	 * @param {TypeInfo} type
	 * @returns {TypeInfo}
	 */
	/**
	 * Whether `from` is an instantiation of the struct template that `to`
	 * spells out concretely.
	 *
	 * `struct tmpl { auto int *p; }` produces variants that all keep the NAME
	 * `tmpl`. Handing one to `void f(struct cvt)` -- where `struct cvt` has the
	 * same members, in the same order, with concrete representations -- is
	 * allowed, because the variant and `cvt` describe the same layout. Anything
	 * else (a different member, or a different order) is not.
	 *
	 * @param {TypeInfo?} from
	 * @param {TypeInfo?} to
	 * @returns {boolean}
	 */
	isStructVariantOf(from, to) {
		// A parameter's type is often still the NAME at this point
		const resolve = t => (typeof t === 'string') ? this.getTypeInfo(t) : t;
		from = resolve(from); to = resolve(to);
		if (!from || !to) return false;
		/*
		Whether either side is still a pattern has to be asked by NAME: the
		flag lives on the canonical entry, and a variant does not carry it. The
		MEMBERS, though, must be read from the object handed in -- a variant's
		members say what was chosen, and going back to the pattern would lose
		that.
		*/
		const fromIsPattern = from.isTemplate === true
			|| this.canonicalStructType(from)?.isTemplate === true;
		if (!['struct', 'union'].includes(from.kind)) return false;
		if (!['struct', 'union'].includes(to.kind)) return false;
		if (from.kind !== to.kind) return false;
		const fm = from.members ?? [], tm = to.members ?? [];
		if (fm.length !== tm.length) return false;
		return fm.every((m, i) => {
			const t = tm[i];
			if (m.name !== t.name) return false;
			/*
			The representation has to agree: a member carrying a NAME and one
			carrying an address are not the same thing, so a name variant does
			not convert into a struct that expects an address.
			*/
				/*
			Checked later if `from` is still a pattern: its representation is
			not chosen until the whole program has been read, which happens
			after this check runs.
			*/
			if (!fromIsPattern
				&& (m.namePointer === true) !== (t.namePointer === true)) return false;
			return this.isSameType(m.type, t.type);
		});
	}

	/**
	 * Check the conversions that were accepted while the struct was still a
	 * pattern: by now every instance has chosen a representation.
	 *
	 * @returns {void}
	 */
	verifyStructConversions() {
		for (const entry of this.pendingStructConversions ?? []) {
			if (!entry.name || !entry.expected) continue;
			const expected = this.getTypeInfo(entry.expected);
			if (!expected) continue;
			const owner = this.symbolByName(entry.name);
			const actual = owner?.myType?.() ?? null;
			if (!actual) continue;
			/*
			Compared on the MEMBERS of the chosen variant: going through
			`canonicalStructType` here would find the pattern again, whose
			members still say "undecided", and every conversion would pass.
			*/
			const fm = actual.members ?? [], em = expected.members ?? [];
			const agree = fm.length === em.length && fm.every((m, i) =>
				m.name === em[i].name
				&& (m.namePointer === true) === (em[i].namePointer === true));
			if (agree) continue;
			this.addError(`'${entry.name}' does not convert into '${entry.expected}': its 'auto' `
				+ `members settled on a different representation than that struct spells out`,
				entry.location);
		}
		this.pendingStructConversions = [];
	}

	/**
	 * Look a name up across every scope.
	 *
	 * @param {string} name
	 * @returns {SymbolEntry?}
	 */
	symbolByName(name) {
		const visit = scope => {
			if (!scope) return null;
			const found = scope.lookup?.(name) ?? null;
			if (found) return found;
			for (const child of scope.children ?? []) {
				const got = visit(child);
				if (got) return got;
			}
			return null;
		};
		return visit(this.currentScope) ?? visit(this.globalScope);
	}

	/**
	 * Reject `typedef void (*f)(struct tmpl)` -- a template struct in the
	 * signature of a function POINTER type.
	 *
	 * @returns {void}
	 */
	rejectTemplateInFunctionPointers() {
		const inner = t => (t?.kind === 'pointer') ? t.pointerTo : t;
		const bad = t => {
			// A parameter's type is still the NAME at this point
			const raw = (typeof t === 'string') ? this.getTypeInfo(t) : t;
			const c = this.canonicalStructType(inner(raw));
			return !!c && c.isTemplate === true;
		};
		for (const entry of this.typeTable?.values?.() ?? []) {
			const fn = entry?.functionTo ?? null;
			if (!fn) continue;
			const params = fn.myType?.()?.parameters ?? fn.parameters ?? [];
			if (!params.some(p => bad(p?.type ?? p))) continue;
			this.addError(`'${entry.name}' is a function pointer type, and its signature names `
				+ `a struct with 'auto' members -- which has no single representation to `
				+ `travel as. Use the concrete struct instead (one whose members spell out `
				+ `their representation)`, null);
		}
	}

	/**
	 * The canonical entry for a struct type.
	 *
	 * A symbol does not necessarily hold the object in `structTable`: it holds
	 * a copy taken at some point, and flags put on the canonical entry after
	 * that do not appear in it. Asking by NAME always reaches the one place
	 * that is kept up to date.
	 *
	 * @param {TypeInfo?} type
	 * @returns {TypeInfo?}
	 */
	canonicalStructType(type) {
		if (!type || !type.name) return type;
		return this.structTable?.get(type.name)
			?? this.typeTable?.get(type.name) ?? type;
	}

	/**
	 * The concrete variant of a template struct for one representation.
	 *
	 * `struct tmpl { auto int *p; }` is a pattern. An instance that stores a
	 * name in `p` and one that stores an address are two different types --
	 * exactly like two C++ template instantiations -- and they do not convert
	 * into each other.
	 *
	 * The NAME is kept, so a struct written out with concrete members
	 * (`struct cvt { int *byname p; }`) compares equal to the variant it
	 * matches. Converting therefore needs the member names to be the same, in
	 * the same order -- which is the cheap rule to check, and enough.
	 *
	 * Members are deep copied: `TypeInfo.duplicate()` shares the `members`
	 * array, so setting `namePointer` on a variant would otherwise reach back
	 * into the pattern.
	 *
	 * @param {TypeInfo} type
	 * @param {string[]} reps one per template member: 'name' or 'memory'
	 * @returns {TypeInfo}
	 */
	structVariantOf(type, reps) {
		const signature = reps.join('|');
		this.structVariants = this.structVariants ?? new Map();
		const key = `${type.name}|${signature}`;
		const existing = this.structVariants.get(key);
		if (existing) return existing;
		const copy = type.duplicate();
		copy.members = (type.members ?? []).map(m => {
			const cm = new MemberInfo(m.name, m.type?.duplicate?.() ?? m.type, m.offset, m.bitField);
			cm.namePointer = m.namePointer;
			cm.isBitfield = m.isBitfield;
			cm.storageName = m.storageName;
			cm.bitOffset = m.bitOffset;
			cm.bitWidth = m.bitWidth;
			cm.isSigned = m.isSigned;
			cm.isBitfieldStorage = m.isBitfieldStorage;
			return cm;
		});
		copy.bitfieldStorages = (type.bitfieldStorages ?? []).map(s =>
			copy.members.find(m => m.name === s.name) ?? s);
		const names = type.templateMembers ?? [];
		names.forEach((memberName, i) => {
			const m = copy.members.find(x => x.name === memberName);
			if (!m) return;
			m.namePointer = (reps[i] === 'name');
			/*
			`auto` is what made this a pattern; the variant has decided, so it
			must not keep asking.
			*/
			if (m.type && Array.isArray(m.type.qualifiers)) {
				m.type.qualifiers = m.type.qualifiers.filter(q => q !== 'auto');
			}
		});
		copy.isTemplate = false;
		copy.variantSignature = signature;
		this.structVariants.set(key, copy);
		return copy;
	}

	/** The representation a struct member is given by this assignment. */
	representationOfMemberAssignment(right) {
		if (!right) return null;
		let got = null;
		this.deepWalk(right, n => {
			if (got) return;
			const who = String(n.functionName ?? n.callee?.name ?? '');
			if (who === 'byname') got = 'name';
			else if (n.type === 'UnaryExpression' && n.operator === '&') got = 'memory';
		});
		if (got) return got;
		/*
		A variable declared `int *byname q` and stored straight into the member
		carries a name too.
		*/
		if (right.type === 'Identifier') {
			const sym = this.currentScope?.lookup?.(right.name) ?? null;
			if (sym?.forcedNamePointer === true || sym?.usesNamePointer === true) return 'name';
			if (sym?.myType?.()?.kind === 'pointer') return 'memory';
		}
		return null;
	}

	/**
	 * Settle every template struct instance on one representation per `auto`
	 * member, from what is actually stored into it.
	 *
	 * @param {ASTNode} ast
	 * @returns {void}
	 */
	specializeStructTemplates(ast) {
		if (!ast) return;
		const collect = type => {
			const out = [];
			this.deepWalk(ast, n => { if (n.type === type) out.push(n); });
			return out;
		};
		/** @type {Map<string, Map<string, string>>} symbol -> member -> rep */
		const wanted = new Map();
		/*
		The whole program has been visited by now, so `currentScope` is the
		GLOBAL one -- locals live in child scopes, which is why a plain
		lookup is not enough.
		*/
		/*
		Every node remembers the scope it was written in (`linkScopesToAST` put
		it there), so asking that scope resolves SHADOWING the way the program
		reads: a local `m` wins over a global one of the same name. Searching
		the whole tree for a name instead could pick the wrong one.
		*/
		const ownerOf = (name, node) => node?.scope?.lookup?.(name)
			?? this.symbolByName(name);
		for (const node of collect('AssignmentExpression')) {
			if (node.operator !== '=' || node.left?.type !== 'MemberExpression') continue;
			if (node.left.getAttribute?.('operator') !== '.') continue;
			const baseNode = node.left.children?.[0];
			if (baseNode?.type !== 'Identifier') continue;
			const ownerName = baseNode.name;
			const owner = ownerOf(ownerName, node);
			const declared = owner?.myType?.() ?? null;
			/*
			Asked by NAME: the symbol's own copy of the type may predate the
			flags that mark it as a pattern.
			*/
			const canonical = this.canonicalStructType(declared);
			if (!canonical || canonical.isTemplate !== true) continue;
			const memberName = node.left.children[1]?.name;
			const rep = this.representationOfMemberAssignment(node.right);
			if (!memberName || !rep) continue;
			if (!wanted.has(ownerName)) wanted.set(ownerName, new Map());
			const prev = wanted.get(ownerName).get(memberName);
			if (prev && prev !== rep) {
				this.addError(`'${ownerName}.${memberName}' is given both a name and an `
					+ `address, so '${ownerName}' has no single representation`,
					node.location);
			}
			wanted.get(ownerName).set(memberName, rep);
		}
		for (const [ownerName, members] of wanted) {
			const owner = ownerOf(ownerName);
			if (!owner) continue;
			const declared = owner.myType?.() ?? null;
			const type = this.canonicalStructType(declared);
			if (!type) continue;
			const names = type.templateMembers ?? [];
			const reps = names.map(n => members.get(n) ?? null);
			if (reps.some(r => !r)) {
				const which = names.filter((n, i) => !reps[i]).join(', ');
				this.addError(`'${ownerName}' has an 'auto' member (${which}) whose representation `
					+ `is never decided -- store either '&x' or 'byname(&x)' into it`, null);
				continue;
			}
			const variant = this.structVariantOf(type, reps);
			if (owner.type && typeof owner.type === 'object' && owner.type.type) {
				owner.type.type = variant;
			} else {
				owner.type = variant;
			}
			owner.structVariant = variant;
			owner.templateRepSignature = reps.join('|');
			/*
			Member expressions were resolved while the type was still a pattern,
			so they carry no `memberByname`. Visit them again now that the
			variant has decided -- otherwise the write would put one word and
			the read take two.
			*/
			this.refreshMemberFlags(ast, ownerName, variant);
		}
	}

	/**
	 * A function whose parameter is a TEMPLATE struct is a pattern too: it has
	 * to be emitted once per variant it is called with, because a member that
	 * carries a name and one that carries an address are not read the same way.
	 *
	 * @param {ASTNode} ast
	 * @returns {void}
	 */
	specializeStructTemplateFunctions(ast) {
		const list = ast?.functions ?? [];
		/** @type {Map<string, any[]>} */
		const calls = new Map();
		this.deepWalk(ast, n => {
			if (n.type !== 'FunctionCall') return;
			const name = n.callee?.type === 'Identifier' ? String(n.callee.name) : null;
			if (!name) return;
			if (!calls.has(name)) calls.set(name, []);
			calls.get(name).push(n);
		});
		const valueUses = [];
		this.deepWalk(ast, n => {
			if (n.type === 'VariableDeclarator' && n.initializer?.type === 'Identifier') {
				valueUses.push({ node: n.initializer, holder: n.name });
			} else if (n.type === 'AssignmentExpression' && n.right?.type === 'Identifier') {
				valueUses.push({ node: n.right, holder: n.left?.name });
			}
		});
		const repsOfArgument = arg => {
			if (!arg || arg.type !== 'Identifier') return null;
			const sym = this.symbolByName(arg.name);
			const type = sym?.myType?.() ?? null;
			if (!type || !['struct', 'union'].includes(type.kind)) return null;
			const names = this.canonicalStructType(type)?.templateMembers ?? null;
			if (!names) return null;
			return (type.members ?? []).filter(m => names.includes(m.name))
				.map(m => (m.namePointer === true ? 'name' : 'memory')).join('|');
		};
		for (const func of [...list]) {
			const name = String(func.name ?? '');
			const paramTypes = (func.parameters ?? []).map(p => {
				/*
				A parameter's type is still the SYNTAX NODE at this point
				(`TypeSpecifier` with a `typeName`), not a resolved `TypeInfo`
				-- so asking for `.name` found nothing and no template was ever
				seen.
				*/
				let t = p?.type ?? null;
				if (t && typeof t === 'object' && !t.isTypeInfo) {
					const fromNode = this.getTypeNameFromTypeNode(t)
						?? this.getTypeNameFromDeclarator(p) ?? null;
					t = fromNode ? this.getTypeInfo(fromNode) : null;
				} else if (typeof t === 'string') {
					t = this.getTypeInfo(t);
				}
				return this.canonicalStructType(t?.kind === 'pointer' ? t.pointerTo : t);
			});
			const templateIndices = paramTypes
				.map((t, i) => (t?.isTemplate === true ? i : -1)).filter(i => i >= 0);
			if (!templateIndices.length) continue;
			/** @type {Map<string, any[]>} signature -> nodes to retarget */
			const groups = new Map();
			const retarget = new Map();
			for (const call of calls.get(name) ?? []) {
				const signature = templateIndices
					.map(i => repsOfArgument(call.arguments?.[i])).join('|');
				if (!signature || signature.split('|').some(r => !r)) continue;
				if (!groups.has(signature)) { groups.set(signature, []); retarget.set(signature, []); }
				retarget.get(signature).push(call.callee);
			}
			for (const use of valueUses) {
				if (String(use.node?.name) !== name) continue;
				const sym = this.symbolByName(use.holder);
				const fpType = sym?.myType?.() ?? null;
				if (!fpType?.parameters) continue;
				const signature = templateIndices
					.map(i => this.autoRepFromExpectedType(fpType.parameters[i]?.type
						?? fpType.parameters[i])).join('|');
				if (!signature || signature.split('|').some(r => !r)) continue;
				if (!groups.has(signature)) { groups.set(signature, []); retarget.set(signature, []); }
				retarget.get(signature).push(use.node);
			}
			if (!groups.size) continue;
			const saved = this.currentScope;
			this.currentScope = this.globalScope;
			const made = [];
			/*
			Starting at 1: the pattern itself is still declared under the
			original name, so an instance keeping that name would be a
			redefinition. The pattern is removed from the function list below;
			its symbol stays, but nothing is emitted for it.
			*/
			let index = 1;
			for (const signature of groups.keys()) {
				const copy = this.cloneAstNode(func);
				copy.name = this.mangleFunctionName(name, index++);
				copy.scope = null;
				copy.setAttribute('autoInstance', true);
				copy.setAttribute('autoReps', signature);
				this.ownParameterNodes(copy);
				templateIndices.forEach((paramIndex, a) => {
					const param = copy.parameters?.[paramIndex];
					if (!param) return;
					const wanted = signature.split('|')[a];
					/*
					The variant the parameter has to see: same name, members
					decided.
					*/
					const base = paramTypes[paramIndex];
					const reps = (base?.templateMembers ?? []).map((_, k) =>
						signature.split('|')[k] ?? 'memory');
					param.type = this.structVariantOf(base, reps);
				});
				this.visit(copy);
				made.push(copy);
				const copySymbol = this.symbolByName(copy.name);
				for (const node of retarget.get(signature) ?? []) {
					node.name = copy.name;
					/*
					The call was resolved while the PATTERN was still the only
					declaration, so the identifier holds a reference to it. The
					name alone is not enough: the generator reads the cached
					symbol, which still pointed at the pattern -- and so handed
					the argument to the unspecialised parameter.
					*/
					if (copySymbol) node.symbol = copySymbol;
					node.setAttribute('overloadResolved', true);
				}
			}
			this.currentScope = saved;
			const at = list.indexOf(func);
			if (at >= 0) list.splice(at, 1, ...made);
		}
	}

	/**
	 * Re-resolve `x.m` for one struct variable after its type changed.
	 *
	 * @param {ASTNode} ast
	 * @param {string} ownerName
	 * @param {TypeInfo} variant
	 * @returns {void}
	 */
	refreshMemberFlags(ast, ownerName, variant) {
		if (!ast) return;
		const collect = type => {
			const out = [];
			this.deepWalk(ast, n => { if (n.type === type) out.push(n); });
			return out;
		};
		for (const node of collect('MemberExpression')) {
			if (node.children?.[0]?.type !== 'Identifier') continue;
			if (node.children[0].name !== ownerName) continue;
			const memberName = node.children[1]?.name;
			const info = (variant.members ?? []).find(m => m.name === memberName);
			if (info?.namePointer !== true || info.type?.kind !== 'pointer') continue;
			node.setAttribute('memberByname', true);
			node.memberInfo = info;
			if (info.type) node.dataType = info.type;
		}
	}

	memoryVariantOf(type) {
		if (!type || !type.isTypeInfo) return type;
		if (!['struct', 'union'].includes(type.kind)) return type;
		// Already a memory implementation? Nothing to do.
		if (type.isStrictPointerImpl()) return type;
		this.memoryVariants = this.memoryVariants ?? new Map();
		const existing = this.memoryVariants.get(type.name);
		if (existing) return existing;
		const copy = type.duplicate();
		copy.forceMemoryImpl = true;
		this.memoryVariants.set(type.name, copy);
		/*
		Every pointer to this struct must now see the memory copy: a pointer can
		only ever point at an instance that has an address, and those are exactly
		the ones using the copy.
		*/
		this.retargetPointersTo(type.name, copy);
		return copy;
	}

	/**
	 * Repoint every pointer-to-`structName` at `variant`, so that `p->m` is
	 * resolved through memory.
	 *
	 * @param {string} structName
	 * @param {TypeInfo} variant
	 * @returns {void}
	 */
	retargetPointersTo(structName, variant) {
		const fixType = type => {
			if (!type || !type.isTypeInfo) return;
			if (type.kind === 'pointer' && type.pointerTo
				&& type.pointerTo.name === structName
				&& ['struct', 'union'].includes(type.pointerTo.kind)) {
				type.pointerTo = variant;
			}
		};
		for (const type of this.typeTable.values()) fixType(type);
		for (const structType of this.structTable.values()) {
			(structType.members ?? []).forEach(member => {
				if (member && member.type) fixType(member.type);
			});
		}
		const visitScope = scope => {
			if (!scope) return;
			(scope.getAllSymbols?.() ?? []).forEach(symbol => {
				const type = symbol.myType?.() ?? null;
				if (type && type.isTypeInfo) fixType(type);
			});
			scope.children?.forEach(visitScope);
		};
		visitScope(this.globalScope);
	}

	// 添加辅助方法标记变量已被取地址
	markVariableAsAddressed(node) {
		if (node.type === 'Identifier') {
			const symbol = this.currentScope.lookup(node.name);
			if (symbol) {
				symbol.isAddressed = true;
				/*
				A struct held in registers has no address at all: a processor
				cannot name "the group of registers called s". Rather than
				refusing the program, the struct is degraded to a piece of
				memory -- and so is every struct that embeds it (see
				`TypeInfo.requireMemoryImplementation`).
				*/
				const symbolType = symbol.myType?.() ?? null;
				/*
				With a name-based pointer to a struct, taking the address no
				longer forces the struct into memory: the pointer carries the
				NAME of every member instead of an address.
				*/
				if (symbol.addressedByName === true) {
					/* keep it in registers */
				} else if (symbolType && ['struct', 'union'].includes(symbolType.kind)) {
					/*
					Give this variable the in-memory COPY of its type. Only this
					variable changes; other instances of the same struct are left
					alone.
					*/
					const variant = this.memoryVariantOf(symbolType);
					if (variant !== symbolType) {
						if (symbol.type && typeof symbol.type === 'object' && symbol.type.type) {
							symbol.type.type = variant;
						} else {
							symbol.type = variant;
						}
					}
				} else if (symbolType && symbolType.kind === 'array' && widthOfType(symbolType) === 1) {
					/*
					A HANDLE array (an open dimension, or a remote array) is ONE
					register, so its address is the NAME of that register. Nothing
					here needs memory: keep the layout.
					*/
					symbol.addressedByName = true;
				}
				if (symbol.kind === 'variable') {
					symbol.accessThroughPointer = true;
				} else if (symbol.kind === 'struct' || symbol.kind === 'union') {
					symbol.implementAsPointer = true;
				}
			}
			
			/*
			Being addressed normally forces a variable out of registers -- but
			not when the pointer is going to carry names instead of an address,
			which is exactly how a register resident value is reached.
			*/
			if (symbol.isRegister && !symbol.addressedByName) {
				this.addWarning(`Register variable '${node.name}' has its address taken, will be stored in memory`, node.location);
				symbol.isRegister = false; // 强制取消register优化
			}
		} else if (node.type === 'MemberExpression') {
			// 处理结构体成员被取地址的情况
			const object = node.getChild(0);
			/*
			A registry struct keeps each member in a register of its own, so
			`&s.m` needs no memory at all -- and the struct itself can never be
			given an address (a processor cannot build the name). Forcing it into
			memory here would therefore be pure waste.
			*/
			this.markVariableAsAddressed(object);
		} else if (node.type === 'CastExpression') {
			/*
			`(T*)x` was the old output-parameter spelling. That use is removed:
			`ulocate`/`ucontrol` now reject it and require `&x`. A plain pointer
			cast is still treated as an address-taking conversion for other
			contexts; a cast of something already pointer-like is an ordinary
			conversion.
			*/
			const target = node.dataType ?? null;
			const inner = node.expression ?? null;
			const isPointerish = t => !!t && (t.isPointerImpl?.() === true || t.isStrictPointerImpl?.() === true);
			if (isPointerish(target) && !isPointerish(inner?.dataType)) {
				this.markVariableAsAddressed(inner);
			}
		} else if (node.type === 'UnaryExpression' && node.operator === '*') {
			// 解引用表达式的地址（如&*ptr）等于ptr
			const arg = node.argument;
			/*
			if (arg.type === 'Identifier') {
				const symbol = this.currentScope.lookup(arg.name);
				if (symbol && symbol.kind === 'variable') {
					symbol.isAddressed = true;
					//symbol.accessThroughPointer = true;
				}
			}
				*/
			this.markVariableAsAddressed(arg);
		}
	}

    /**
     * Refuse an assignment that hands one array to another.
     *
     * Two arrays are only interchangeable when they are stored the same way.
     * A memory array and an array in registers share no representation, and a
     * handle is a description of an array rather than one, so `int s[4]` and an
     * `int s[]` are not the same type either. Comparing the type NAMES cannot
     * see any of this -- they all print as `int[...]` -- which is why the check
     * is made here rather than left to `isTypeCompatible`.
     *
     * A remote array is refused on its own account, and always: a handle names
     * the get / set helpers by LINE NUMBER in this program, so it does not
     * survive the trip to another processor even when both arrays are
     * perfectly local there. Sharing the elements means sharing the code that
     * reaches them, which is code generation rather than a value.
     *
     * @param {any} node
     * @param {TypeInfo} leftType
     * @param {TypeInfo} rightType
     * @returns {boolean} true when the assignment was refused
     */
    refuseIncompatibleArrayAssignment(node, leftType, rightType) {
        if (leftType?.kind !== 'array' || rightType?.kind !== 'array') return false;
        const left = this.symbolOfArrayExpression?.(node.left) ?? null;
        const right = this.symbolOfArrayExpression?.(node.right) ?? null;
        const nameOf = side => side?.name ?? 'an array';
        /*
        An array PARAMETER whose type has an OPEN dimension (`int s[]`) arrives
        as a packed handle BY VALUE -- a copy of the caller's handle, with the
        length inside the packed value. Two things therefore cannot happen:
        there is no stored length for the copy to stop at (see
        `emitElementCopy`, which would use 0), and writing a handle over the
        parameter's register would only rebind this function's private copy.
        Either way `s = b;` leaves the caller's array exactly as it was, so the
        spelling promises "s is b now" and delivers nothing. It is the same
        hole `vecalias_into_parameter.c` names from the intrinsic's side, so it
        gets the same answer: refuse it and point at what does work.

        A SIZED array parameter (`int s[4]`) is not refused here: its outer
        length is a compile-time fact, so the element copy §3.6 emits has a
        bound and reaches the caller's storage. Only the open case has no
        length to copy against.
        */
        if (left?.kind === 'parameter' && this.hasOpenDimension(leftType)) {
            this.addError(
                `Cannot assign to array parameter '${nameOf(left)}': it arrives as a handle `
                + `BY VALUE, a copy of the caller's, so the assignment would only change this `
                + `function's copy and leave the caller's array as it was. Write the elements `
                + `instead (\`${nameOf(left)}[i] = ...\`); for a handle you own, declare `
                + `\`int h[];\` and bind that`,
                node.location);
            return true;
        }
        /*
        A symbol with `arrayAliasOf` does not HOLD an array -- it IS one, the one
        it names. There is nothing behind it to rebind: the storage is the other
        array's, and the code that reaches it was generated for the other array.
        Writing to it would either be dropped or, worse, land in the wrong place;
        say so instead.

        Only a declaration can produce one: `int s[] = r;` -- and that is what
        the inliner itself makes, which is why nothing the optimizer generates can
        run into this (the optimizer runs after this pass).
        */
        if (left?.arrayAliasOf) {
            const target = left.arrayAliasOf;
            this.addError(
                `Cannot assign to '${nameOf(left)}': it is not an array of its own, it is `
                + `'${target?.name ?? 'another array'}' itself. Write `
                + `\`int ${nameOf(left)}[] = ${target?.name ?? 'that array'};\` to bind it`,
                node.location);
            return true;
        }
        const leftImpl = this.arrayImplementationOf(left);
        const rightImpl = this.arrayImplementationOf(right);
        const saidAs = impl => ({
            memory: 'an array in memory',
            handle: 'an array handle',
            remote: 'a remote array',
            encoded: 'an encoded array',
            embedded: 'an embedded array'
        })[impl] ?? 'an array in an undecided layout';
        /*
        An UNBOUND handle (`int a[];` declared, not yet bound) is the one array
        that may be ASSIGNED a value: `a = b;` BINDS it -- the cell starts empty
        and the assignment is what fills it. That is not a copy, so the two
        implementations do not have to match. The one thing that cannot be bound
        to a local cell is a REMOTE array: a handle packs the helper entry points
        of THIS processor, and they mean nothing on another one, so the same
        refusal as every other remote-to-local handle copy applies.
        */
        if (left?.isUnboundHandle === true) {
            if (rightImpl === 'remote') {
                this.addError(
                    `Cannot bind a remote array to '${nameOf(left)}': a handle packs helper `
                    + `entry points of THIS processor, which mean nothing there. Copy the `
                    + `elements instead`, node.location);
                return true;
            }
            return false;    // binding: the implementations may differ
        }
        /*
        An ENCODED array is a constant table of contents, whatever the
        declaration said: the layout packs its values into registers or a
        string, and there is no storage behind the name for a copy to land in.
        `elems = elems` slicing through the layout check would be admitted --
        both sides answer 'encoded' -- and then the copy §3.6 emits would have
        nothing to write to. Refuse before the layout equality is consulted; a
        target that really is `const` keeps the plain const refusal it gets
        further down this pass.
        */
        if (leftImpl === 'encoded' && !leftType.isConst()) {
            this.addError(
                `Cannot assign to '${nameOf(left)}': an encoded array is a constant table `
                + `of contents -- even without 'const' the layout leaves no cells to write `
                + `into. Declare it 'array("embedded_divided", ...)' or as a plain array `
                + `to have cells`,
                node.location);
            return true;
        }
        if (leftImpl === rightImpl) return false;
        this.addError(
            `Cannot assign ${saidAs(rightImpl)} to ${saidAs(leftImpl)}: `
            + `'${nameOf(right)}' and '${nameOf(left)}' are not the same type, `
            + `because they are not stored the same way`,
            node.location);
        return true;
    }

    /** The symbol an array-typed expression denotes, when it is a plain name. */
    symbolOfArrayExpression(node) {
        if (!node || node.type !== 'Identifier') return null;
        return node.symbol
            ?? this.currentScope?.lookup?.(node.name)
            ?? this.globalScope?.lookup?.(node.name)
            ?? null;
    }

    /**
     * `vecalias(handle *dst, int b[])` -- bind a handle cell to an array.
     *
     * The `&` is not decoration. A handle is ONE register, so the address of a
     * handle is an ordinary one-word name pointer, the signature is the
     * cheapest thing that can carry it, and the body is one store. That is the
     * whole reason this exists as an intrinsic rather than as a function: as a
     * function it would have to be passed an array, and a handle cannot be
     * passed as an array (it is a description of one).
     *
     * The destination must therefore be a handle cell this program OWNS, which
     * means a declared one (`int a[];`). The other shapes are refused each for
     * its own reason, because the advice differs: a memory array is storage
     * with an address and nothing to pack a handle into, so the advice is the
     * copy that does work; an array in registers has no address at all; and a
     * handle PARAMETER is a copy the caller passed, so binding into it would
     * rebind the callee's view and leave the caller's array as it was.
     *
     * The source may be any LOCAL layout, and a remote one is refused for the
     * same reason every other remote-to-local handle copy is: the helpers in a
     * handle are line numbers of this program, and they mean nothing on another
     * processor.
     *
     * @param {ASTNode} node A `vecalias` BuiltinCall
     */
    checkVecAlias(node) {
        const args = node.arguments ?? [];
        if (args.length !== 2) {
            this.addError(`'vecalias' takes exactly 2 arguments, but ${args.length} were provided`,
                node.location);
            return;
        }
        const [destination, source] = args;
        const nameOf = symbol => symbol?.name ?? 'it';
        /*
        `&a` -- the address of a name. Anything else is not a cell to write a
        handle into: `vecalias(mem, b)` would have to be a memory array by
        definition, and `vecalias(3, b)` names nothing at all.
        */
        if (destination.type !== 'UnaryExpression' || destination.operator !== '&'
            || destination.argument?.type !== 'Identifier') {
            this.addError(
                `The first argument of vecalias must be the address of a handle, as in `
                + `'vecalias(&a, b)': a handle is bound by writing into the cell that holds it`,
                destination.location ?? node.location);
            return;
        }
        const cell = this.symbolOfArrayExpression(destination.argument);
        const cellType = cell?.myType?.() ?? null;
        if (!cell || cellType?.kind !== 'array') {
            this.addError(
                `'${destination.argument.name}' is not an array, so it has no handle to bind`,
                destination.argument.location ?? node.location);
            return;
        }
        const cellImpl = this.arrayImplementationOf(cell);
        if (cellImpl === 'remote') {
            this.addError(
                `Cannot vecalias into '${nameOf(cell)}': a remote array is an element of ANOTHER `
                + `processor, and a handle here packs the entry points of THIS one`,
                destination.location);
            return;
        }
        /*
        Only a handle cell THIS PROGRAM OWNS can be bound into, and that means
        a declared one (`int a[];`). The other three shapes are refused for
        three different reasons, so the message has to say which one it hit:
        the advice is not the same for any of them.
        */
        if (cell.isUnboundHandle !== true) {
            const name = nameOf(cell);
            /*
            An array with no length of its own, and not one this program
            declared, is a PARAMETER (`int s[]`) -- the one shape that is a
            handle without being a cell. `arrayParamRep` would say so too, but
            it is filled in only at the very end of this pass, long after this
            runs, so the type is what can be asked.
            */
            const isParameter = this.staticArrayLengthOf(cell) === null;
            const said = isParameter
                ? 'an array PARAMETER, and the handle in it is a COPY -- '
                    + 'the one the caller passed, so binding into it would change what this '
                    + "function sees from here on and leave the caller's array on the handle it "
                    + "already has. Declare a handle of your own "
                    + "('int h[];') to bind instead"
                : (cellImpl === 'memory')
                    ? `an array in memory, and a handle is not storage -- use veccpy(${name}, ...)`
                    : 'an array in registers, which has no address to take the address of';
            this.addError(
                `Cannot vecalias into '${name}': it is ${said}`, destination.location);
            return;
        }
        if (source.dataType?.kind !== 'array') {
            this.addError(`The second argument of vecalias must be an array, as in 'vecalias(&a, b)'`,
                source.location ?? node.location);
            return;
        }
        /*
        A remote array cannot be NAMED by a handle, whatever the destination is:
        the get / set helpers a handle packs are line numbers in this program's
        own output. The elements can still be copied, one at a time, with
        `veccpy` -- and the message has to say so, because a refusal that only
        said no would read as "remote arrays are unusable".
        */
        if (this.arrayImplementationOf(this.symbolOfArrayExpression(source)) === 'remote'
            || this.typeHasRemoteQualifier(source.dataType)) {
            this.addError(
                `Cannot bind a remote array by vecalias: a handle packs helper entry points `
                + `of THIS processor, which mean nothing there. Copy the elements with `
                + `'veccpy' instead`,
                source.location ?? node.location);
            return;
        }
        node.dataType = this.getTypeInfo('void');
    }

    /**
     * `veccpy(int a[N], int b[M])` -- copy elements from `b` into `a`.
     *
     * The destination is storage this program owns, and only that. A handle is
     * a NAME and not storage, so there are no elements in it to write: the way
     * to bind one is `vecalias(&h, b)`, and saying so is the whole advice.
     *
     * The lengths are settled here when both are known, and that is a refusal
     * rather than a silent truncation: `M > N` in the source text is a mistake
     * in the program, not a runtime condition. When one of the two is only
     * known at run time -- which is what a handle's packed length is -- there is
     * nothing to check here, and the generator copies the SMALLER of the two
     * counts so that the copy cannot run past the end of the destination.
     *
     * @param {ASTNode} node A `veccpy` BuiltinCall
     */
    checkVecCpy(node) {
        const args = node.arguments ?? [];
        if (args.length !== 2) {
            this.addError(`'veccpy' takes exactly 2 arguments, but ${args.length} were provided`,
                node.location);
            return;
        }
        const [destination, source] = args;
        if (destination.dataType?.kind !== 'array') {
            this.addError(`The first argument of veccpy must be an array, as in 'veccpy(a, b)'`,
                destination.location ?? node.location);
            return;
        }
        if (source.dataType?.kind !== 'array') {
            this.addError(`The second argument of veccpy must be an array, as in 'veccpy(a, b)'`,
                source.location ?? node.location);
            return;
        }
        const destinationSymbol = this.symbolOfArrayExpression(destination);
        const destinationImpl = this.arrayImplementationOf(destinationSymbol);
        if (destinationImpl === 'handle') {
            this.addError(
                `Cannot veccpy into '${destinationSymbol?.name ?? 'it'}': a handle is a NAME, not `
                + `storage, so it has no elements to write. Write `
                + `'vecalias(&${destinationSymbol?.name ?? 'h'}, b);' to bind it instead`,
                destination.location);
            return;
        }
        /*
        The loop needs a bound, so the destination has to have a length to
        count up to. Every layout has one except a handle, and that was just
        refused above.
        */
        const destinationLength = this.staticArrayLengthOf(destinationSymbol);
        if (destinationLength === null) {
            const name = destinationSymbol?.name ?? 'a';
            this.addError(
                `Cannot veccpy into '${name}': it has no length, so there is nothing to copy `
                + `into. Give it a size, as in 'int ${name}[8];'`, destination.location);
            return;
        }
        /*
        The source length is only KNOWN when the source is not a handle: a
        handle carries its length in the packed value, which is a run time
        question. A remote array's length is its declared one, and a local
        array's is the size it was written with.
        */
        const sourceSymbol = this.symbolOfArrayExpression(source);
        const sourceLength = this.staticArrayLengthOf(sourceSymbol);
        if (sourceLength !== null && sourceLength > destinationLength) {
            this.addError(
                `The second argument of veccpy has ${sourceLength} element(s) in dimension 1, but `
                + `the destination '${destinationSymbol?.name ?? 'it'}' has ${destinationLength}`,
                source.location ?? node.location);
            return;
        }
        node.dataType = this.getTypeInfo('void');
    }

    /**
     * An array symbol's element count when the type gives one, else null.
     *
     * `null` means "not known here" and not "zero": a handle has a length, but
     * it is in the packed value rather than in the type, so only run time can
     * read it.
     *
     * @param {SymbolEntry?} symbol
     * @returns {number?}
     */
    staticArrayLengthOf(symbol) {
        const type = symbol?.myType?.() ?? null;
        if (!type || type.kind !== 'array') return null;
        /*
        `hasOpenDimension` already draws the line between "the type says how
        many" and "only run time knows", and this is the same line: an open
        dimension is a handle, whose length is in the packed value.
        */
        if (this.hasOpenDimension(type)) return null;
        return Number((this.dimensionListOf(type) ?? [])[0]);
    }

    /**
     * The target an array-element lvalue writes through when its object is an
     * alias: `int al[] = mem; al[i] = ...;` writes `mem`, not `al`.
     * @param {any} left
     * @returns {{alias: SymbolEntry, target: SymbolEntry}?}
     */
    arrayAliasOfElement(left) {
        if (!left || left.type !== 'MemberExpression') return null;
        const object = left.children?.[0] ?? left.object ?? null;
        if (!object || object.type !== 'Identifier') return null;
        const alias = object.symbol
            ?? this.currentScope?.lookup?.(object.name)
            ?? this.globalScope?.lookup?.(object.name) ?? null;
        if (!alias?.arrayAliasOf) return null;
        let target = alias.arrayAliasOf;
        while (target?.arrayAliasOf) target = target.arrayAliasOf;
        return { alias, target };
    }

    visitAssignmentExpression(node) {
        this.visit(node.left);
        /*
        `p = "hi"` where p is `const char*`: materialise the literal as a
        read-only char array before the right side is visited.
        */
        const leftTypeForLiteral = this.getExpressionType(node.left);
        if (node.operator === '='
            && node.right?.type === 'StringLiteral'
            && this.isConstCharPointer(leftTypeForLiteral)) {
            node.right = this.coerceStringLiteralToCharPointer(
                node.right, leftTypeForLiteral, node);
        }
        this.visit(node.right, {
			givenType: node.left.dataType,
			givenTypeUnsure: true
		});

        const leftType = this.getExpressionType(node.left);
        let rightType = this.getExpressionType(node.right);

        if (!leftType || !rightType) {
            return;
        }

        /*
        Writing through an alias of an ENCODED array (`int al[] = mem;` where
        `mem` was requested `array("encoded", ...)`). The alias has no storage
        of its own and an encoded table has no cells, so the write could only
        crash the generator (`Internal parser error: an encoded array is
        constant...`). Say it here as a normal semantic refusal. A `const`
        target is already caught by the element type's const check below.
        */
        if (!leftType.isConst()) {
            const aliasWrite = this.arrayAliasOfElement(node.left);
            if (aliasWrite && aliasWrite.target.requestedArrayImplementation === 'encoded') {
                const { alias, target } = aliasWrite;
                this.addError(
                    `Cannot assign to '${alias.name}': it is an alias of '${target.name}', which is `
                    + `an encoded constant table with no cells for the write to land in. Give `
                    + `'${alias.name}' its own storage instead of aliasing a constant`,
                    node.location);
                return;
            }
        }

		let compatible = false;
		let resultType = leftType;
		if (node.operator === '=') {
			/*
			An array is judged by how it is STORED, not by what it is called:
			`int[4]` names a memory array, an array in registers and a handle all
			under the same spelling. So this has to be settled before the type
			names are compared, or the comparison agrees with itself and nothing
			is caught.
			*/
			if (this.refuseIncompatibleArrayAssignment(node, leftType, rightType)) {
				return;
			}
			compatible = this.isTypeCompatible(leftType, rightType);
		} else {
			const operation = node.operator.slice(null, -1);
			compatible = this.isTypeCompatibleForOperator(operation, leftType, rightType);
			if (compatible) {
				const probableResult = this.getResultType(operation, leftType, rightType);
				compatible = compatible && this.isTypeCompatible(leftType, probableResult);
				resultType = probableResult;
			}
		}

        // 检查赋值兼容性
        if (!compatible) {
			let funcFlag = false;
			if (node.right.type === 'Identifier' && node.right.symbol && node.right.symbol.kind === 'function') {
				// Try function pointer
				const funcType = new TypeInfo('', 'function', 1);
				funcType.functionTo = new SymbolEntry(
					'',
					{
						returnType: node.right.symbol.type.returnType,
						parameters: node.right.symbol.type.parameters
					},
					this.globalScope,
					'function',
					node.right.location
				);
				// Identifier itself can be assigned this:
				node.dataType = funcType;
				rightType = funcType;
				funcFlag = this.isTypeCompatible(leftType, rightType);
				const rightTypeReadable = this.typeToString(rightType);
				if (!funcFlag) {
					this.addError(`Incorrect type '${rightTypeReadable}' in assignment of function pointer '${leftType}'`,
					node.location);
				}
			} else {
				this.addError(
                `Cannot assign '${rightType}' to '${leftType}'`,
                node.location
				);
			}
			if (!funcFlag) {
				
				return;
			}
        }
		
		// TODO: Some issues about "const int*" / "int* const" might exist
		
		// 检查左值是否为const
        if (leftType.isConst()) {
            this.addError(`Cannot assign to const variable`, node.location);
        }

        // 检查左值
        if (!this.isLValue(node.left)) {
            this.addError(`Assignment requires lvalue`, node.location);
        }

        node.dataType = resultType;
    }
	
	// 添加成员访问支持
    visitMemberExpression(node) {
        const object = node.getChild(0);
        const member = node.getChild(1);
        const computed = node.getAttribute('computed');
		const operator = node.getAttribute('operator'); // '.' 或 '->'

		const regOffset = (offset, parent = null) => {
			if (object.type === 'MemberExpression') {
				// this.visit(object);	// ? should have visited !!
				if (typeof object.getAttribute('totalMemberOffset') === 'number') {
					node.setAttribute('totalMemberOffset', object.getAttribute('totalMemberOffset') + offset);
					node.setAttribute('totalSource', object.hasAttribute('totalSource') ? object.getAttribute('totalSource') : object);
				}
			} else {
				node.setAttribute('totalMemberOffset', offset);
				node.setAttribute('totalSource', object);
			}
		};
        
        this.visit(object);
        const objectType = this.getExpressionType(object);
        
        if (!objectType) return;
        
        // 数组下标访问 (Updated 8 Feb: also for strings now!)
		// This should discard volatile qualifier
        if (computed) {
            if (objectType.kind !== 'array' && objectType.kind !== 'pointer') {
				if (objectType.kind === 'basic' && objectType.name === 'string_t') {
					if (this.targetVersion < 150) {
						this.addError('String index access requires at least v150', node.location);
						return;
					} else {
						node.setAttribute('stringAccess', true);
						/**
						 * Indexing a native string yields a character NUMBER.
						 * @type {TypeInfo}
						 */
						node.dataType = this.getTypeInfo('char');
					}
					
				} else {
					this.addError(`Cannot use subscript on ${this.targetVersion >= 150 ? 'non-array nor string' : 'non-array'} type`, node.location);
                	return;
				}
                
            }
            
            this.visit(member);
            const indexType = this.getExpressionType(member);
            if (indexType && !this.isTypeCompatible(indexType, 'int')) {
                this.addWarning(`Array index should be of intergal type`, member.location);
            }
			/*
			A constant index against an array whose length is known at compile
			time is refused here, while it is still a source-level fact:
			`int r[3]; r[5]` cannot mean what it says. A dynamic subscript
			(`s[i]`) is left alone -- nothing here knows `i` -- and so is a
			pointer, whose length is not part of its type. This changes no
			generated code: everything that compiled before still compiles
			(OPEN_WORK §7.4).
			*/
			if (member.type === 'NumericLiteral' && objectType.kind === 'array') {
				const length = (this.dimensionListOf(objectType) ?? [])[0];
				if (Number.isFinite(length) && length > 0 && member.value >= length) {
					const what = object.type === 'Identifier' ? `'${object.name}'` : 'this array';
					this.addError(
						`Array subscript ${member.value} is out of bounds: `
						+ `${what} has only ${length} element(s)`,
						member.location);
				}
			}
			if (member.type === 'NumericLiteral' && member.value) {
				/*
				For a string (`char s`), `s[i]` indexes single characters, and
				there is no element type underneath to ask for a size.
				*/
				const elementType = objectType.extractSingle?.() ?? null;
				const objectSize = (elementType && elementType.size) ? elementType.size : 1;
				regOffset(objectSize * member.value);
			}
            
            node.dataType = objectType.extractSingle();
			return;
        }
        
		// 结构体/联合体成员访问
		let targetType = objectType;
		
		// 处理指针操作符 '->'
		if (operator === '->') {
			if (objectType.kind !== 'pointer') {
				this.addError(`'->' operator requires pointer to struct/union`, node.location);
				return;
			}
			
			if (!objectType.pointerTo) {
				this.addError(`Cannot dereference incomplete pointer type`, node.location);
				return;
			}
			
			// 解引用指针，获取指向的类型
			targetType = objectType.pointerTo;
		}
		// 处理点操作符 '.'
		else if (operator === '.') {
			// 点操作符要求对象是结构体/联合体类型，不能是指针
			if (objectType.kind === 'pointer') {
				this.addError(`Cannot use '.' operator on pointer type, use '->' instead`, node.location);
				return;
			}
		}
		
		// 检查目标类型是否为结构体或联合体
		if (targetType.kind !== 'struct' && targetType.kind !== 'union') {
			this.addError(`Member access requires struct/union type, got '${this.typeToString(targetType)}'`, node.location);
			return;
		}
		
		
		if (member.type !== 'Identifier') {
			this.addError(`Member name must be an identifier`, member.location);
			return;
		}
		
		const memberName = member.name;
		const memberInfo = targetType.members.find(m => m.name === memberName);
		
		if (!memberInfo) {
			this.addError(`'${targetType.name}' has no member named '${memberName}'`, member.location);
			return;
		}
		
		// 记录成员信息
		node.dataType = memberInfo.type;	// Reserve 'volatile' if necessary
		node.memberInfo = memberInfo;
		
		// 设置节点属性，便于代码生成阶段使用
		node.setAttribute('memberOffset', memberInfo.offset);
		/*
		`int *byname ptr` inside a struct: carried on the node so the generator
		knows this MEMBER holds a name. A member has no SymbolEntry, which is
		why the qualifier used to be dropped: the write put one word (the name)
		and the read then took two (block + offset), and the two never met.
		*/
		if (memberInfo.namePointer === true && memberInfo.type?.kind === 'pointer') {
			node.setAttribute('memberByname', true);
		}
		node.setAttribute('memberName', memberName);
		regOffset(memberInfo.offset);

		// 如果是通过指针访问，记录解引用信息
		if (operator === '->') {
			node.setAttribute('dereferenced', true);
		}
		
    }

	/**
	 * A dimension written as a name (`const int N = 4; int a[N];`).
	 *
	 * @param {ASTNode?} dim
	 * @returns {number?} null when it is not a compile time constant
	 */
	constantDimensionOf(dim) {
		if (!dim) return null;
		if (dim.type === 'NumericLiteral') return Number(dim.value);
		if (dim.type === 'Identifier') {
			const symbol = this.currentScope?.lookup(dim.name);
			if (symbol?.isConstant) return Number(symbol.constantValue);
			const init = symbol?.initializer ?? symbol?.declarator?.initializer ?? null;
			if (symbol?.isConst && init && init.type === 'NumericLiteral') {
				return Number(init.value);
			}
		}
		return null;
	}

	/**
	 * `lenof(a)` -- the number of ELEMENTS, i.e. the outermost dimension.
	 *
	 * Only an array symbol has one; a parameter is only a pointer by the time
	 * it is called, so asking for its length is an error rather than a guess.
	 *
	 * @param {ASTNode} node
	 * @returns {number?}
	 */
	lenofOf(node, location) {
		if (!node) {
			this.addError(`lenof() needs an array`, location);
			return null;
		}
		/*
		`lenof(a[1])` is a question about the type of `a[1]`, which is
		`int[6]` when `a` is `int[5][6]` -- so the answer is the OUTERMOST
		dimension of that type, 6. Only the outermost one can be given: the
		rest are not part of the type of the expression.
		*/
		const dimensionOfType = (type, what) => {
			if (!type || type.kind !== 'array') {
				this.addError(`lenof() needs an array, but ${what} is not one`, location);
				return null;
			}
			const first = (this.dimensionListOf(type) ?? [])[0];
			if (first === undefined || first === null) {
				this.addError(`The length of ${what} is not known here`, location);
				return null;
			}
			return first;
		};
		if (node.type === 'Identifier') {
			const symbol = this.currentScope?.lookup(node.name) ?? null;
			if (!symbol) {
				this.addError(`Undeclared identifier '${node.name}'`, location);
				return null;
			}
			return dimensionOfType(symbol.myType?.() ?? null, `'${node.name}'`);
		}
		// Anything else: what the expression itself stands for
		this.visit(node);
		const type = this.getExpressionType(node) ?? node.dataType ?? null;
		const written = (node.type === 'MemberExpression')
			? `this element` : `this expression`;
		return dimensionOfType(type, written);
	}

	/**
	 * The dimensions of an array type as numbers, outermost first.
	 *
	 * @param {TypeInfo} type
	 * @returns {number[]?}
	 */
	dimensionListOf(type) {
		const raw = type?.arraySize ?? null;
		if (raw === null || raw === undefined) return null;
		const items = Array.isArray(raw) ? raw : [raw];
		return items.map(item => (item && typeof item.value === 'number')
			? item.value
			: (typeof item === 'number' ? item : null));
	}

	/**
	 * Whether an array type leaves its outermost dimension open, as `int s[]`
	 * does.
	 *
	 * This is not a variable length array. Nothing here is computed at run time:
	 * the length is CARRIED, which is the whole point of a handle -- it packs
	 * the length and the element size beside the two helpers that reach the
	 * elements (see `handleTailOf`). So an array with an open dimension has to
	 * arrive as a handle, because a pointer cannot say how far it goes, and
	 * `lenof` and `sizeof` both have to work on it.
	 *
	 * @param {TypeInfo?} type
	 * @returns {boolean}
	 */
	hasOpenDimension(type) {
		if (!type || type.kind !== 'array') return false;
		const outer = (this.dimensionListOf(type) ?? [])[0];
		return outer === undefined || outer === null
			|| !Number.isFinite(Number(outer)) || Number(outer) <= 0;
	}

	/**
	 * How many memory cells one value of this type occupies.
	 *
	 * @param {TypeInfo} type
	 * @returns {number?} null when the type has no memory representation
	 */
	sizeOfTypeInfo(type) {
		if (!type) return null;
		if (type.incomplete === true) return null;
		// Types that never reach memory have no meaningful size
		if (['string_t', 'content_t', 'device', 'null_t'].includes(type.name)) return null;
		// An inner array is a value of its own size, so this recurses
		const elementSize = t => {
			if (!t) return 1;
			if (t.kind === 'pointer') return 2;	// block + position
			if (t.kind === 'array') {
				const dims = (this.dimensionListOf(t) ?? []).filter(d => d !== null);
				return dims.reduce((a, b) => a * b, 1) * elementSize(t.pointerTo);
			}
			if (t.kind === 'struct' || t.kind === 'union') return t.size ?? 1;
			return 1;
		};
		return elementSize(type);
	}

	/**
	 * Resolve the type NAME a `sizeof(...)` / `widthof(...)` handed over as a
	 * string literal. `getTypeInfo` knows typedefs and struct tags but not the
	 * `struct` / `union` keyword itself, which the parser keeps in the name
	 * (`widthof(struct pt)`, `widthof(volatile struct pt)`); drop the keyword
	 * wherever it shows up and try again.
	 *
	 * @param {string} raw
	 * @returns {TypeInfo?}
	 */
	resolveCompileTimeTypeName(raw) {
		const direct = this.getTypeInfo(raw);
		if (direct) return direct;
		const bare = raw.replace(/\b(struct|union)\s+/g, '').trim();
		return bare !== raw ? this.getTypeInfo(bare) : null;
	}

	/**
	 * Fold `sizeof(...)` / `lenof(...)` / `widthof(...)`, which are compile
	 * time questions.
	 *
	 * The call node is turned into the number it stands for, so that
	 * everything downstream -- constant folding, array sizes, code generation
	 * -- only ever sees a literal.
	 *
	 * @param {ASTNode} node A FunctionCall
	 * @returns {boolean} whether it was one of them
	 */
	foldCompileTimeFunction(node) {
		const name = node.callee?.name;
		if (name !== 'sizeof' && name !== 'lenof' && name !== 'widthof') return false;
		const location = node.location;
		const args = node.arguments ?? [];
		let value = null;
		if (name === 'sizeof') {
			if (args.length !== 1) {
				this.addError(`sizeof() takes exactly one operand`, location);
				return true;
			}
			const arg = args[0];
			if (arg.type === 'StringLiteral' && arg.getAttribute?.('isTypeName') === true) {
				// `sizeof(<type>)`: the parser left the type's NAME here
				const info = this.resolveCompileTimeTypeName(String(arg.value));
				if (!info) {
					this.addError(`Unknown type '${arg.value}' in sizeof()`, location);
					return true;
				}
				value = this.sizeOfTypeInfo(info);
				if (value === null) {
					this.addError(
						`sizeof() cannot be applied to '${arg.value}': it has no memory representation`,
						location);
					return true;
				}
			} else if (arg.type === 'StringLiteral') {
				/*
				`sizeof("hi")`: in C the literal is a `const char[3]`, including
				the terminating NUL. The native string value is one cell, but a
				char pointer to the literal sees the character array, so the
				C answer is the useful one here.
				*/
				value = [...String(arg.value ?? '')].length + 1;
			} else {
				this.visit(arg);
				const type = this.getExpressionType(arg);
				value = this.sizeOfTypeInfo(type);
				if (value === null) {
					this.addError(
						`sizeof() cannot be applied to this operand: it has no memory representation`,
						location);
					return true;
				}
			}
		} else if (name === 'widthof') {
			if (args.length !== 1) {
				this.addError(`widthof() takes exactly one operand`, location);
				return true;
			}
			/*
			`widthof` answers the representation question: how many REGISTERS a
			value of the type occupies (1 for a name pointer or a handle array,
			2 for a memory pointer or array). It must always agree with code
			generation, so it is a thin wrapper over the infrastructure's
			`widthOfType` -- the very function the generator allocates with --
			never a second copy of the width table.
			*/
			const arg = args[0];
			/** @type {TypeInfo?} */
			let info = null;
			if (arg.type === 'StringLiteral' && arg.getAttribute?.('isTypeName') === true) {
				// `widthof(<type>)`: the parser left the type's NAME here
				info = this.resolveCompileTimeTypeName(String(arg.value));
				if (!info) {
					this.addError(`Unknown type '${arg.value}' in widthof()`, location);
					return true;
				}
			} else if (arg.type === 'StringLiteral') {
				value = [...String(arg.value ?? '')].length + 1;
				info = null;
			} else {
				this.visit(arg);
				info = this.getExpressionType(arg);
				if (!info) {
					this.addError(`widthof() cannot be applied to this operand`, location);
					return true;
				}
			}
			if (info) value = widthOfType(info);
		} else {
			if (args.length !== 1) {
				this.addError(`lenof() takes exactly one operand`, location);
				return true;
			}
			/*
			An array that arrived as a HANDLE: its length is not part of the
			PARAMETER's type, so it cannot be answered here -- it rides along in
			the packed handle and is asked for at run time. Folding it produced 0.
			*/
			const argNode = args[0];
			if (argNode.type === 'Identifier') {
				const sym = this.currentScope?.lookup(argNode.name) ?? null;
				const symType = sym?.myType?.() ?? null;
				const dims = (symType && symType.kind === 'array')
					? (this.dimensionListOf(symType) ?? []) : null;
				/*
				`void f(int s[])` -- the parameter's type says nothing about the
				length, so the answer has to come from the handle at run time.
				(`arrayParamRep` cannot be used here: it is filled in only after
				the call sites have been seen, which is later than this.)
				*/
				const known = dims ? dims[0] : null;
				if (sym && dims && (known === undefined || known === null
					|| !Number.isFinite(Number(known)) || Number(known) === 0)) {
					node.dataType = this.getTypeInfo('int');
					node.setAttribute('lenofOfHandle', sym.getAssemblySymbol?.() ?? argNode.name);
					return true;
				}
			}
			value = this.lenofOf(args[0], location);
			if (value === null) return true;
		}
		// Become the number itself
		node.type = 'NumericLiteral';
		node.value = value;
		node.raw = String(value);
		node.children = [];
		node.arguments = undefined;
		node.callee = undefined;
		node.dataType = this.getTypeInfo('int');
		return true;
	}

    /**
     * The name a function is emitted under.
     *
     * Several functions may share a name (overloading), and they must not
     * collide in the `FunctionRegisterer` -- so all but the first get a
     * suffixed name. The first keeps the plain name, which keeps ordinary
     * programs untouched.
     *
     * @param {string} name
     * @param {number} [index] Position among the functions sharing this name
     * @returns {string}
     */
    mangleFunctionName(name, index = 0) {
        return index === 0 ? name : `${name}__ov${index}`;
    }

    /**
     * How the compiler reacts to several functions sharing one name.
     *
     * `#pragma overload(auto | default | none)`. `default` (and `auto`) allow
     * it; `none` refuses.
     *
     * @returns {'auto' | 'default' | 'none'}
     */
    overloadMode() {
        const mode = this.compiler?.overloadMode ?? null;
        return (mode === 'auto' || mode === 'default' || mode === 'none') ? mode : 'default';
    }

    /**
     * Whether a parameter is written `auto` -- `void f(auto int *s)`.
     *
     * `auto` is also a storage class (`auto device`), so the qualifier may sit
     * in either place, exactly as `byname` does.
     *
     * @param {any} node A parameter node
     * @returns {boolean}
     */
    hasAutoQualifier(node) {
        const levels = [
            ...(node?.pointerQualifiers ?? []),
            ...(node?.type?.pointerQualifiers ?? []),
            node?.type?.getAttribute?.('qualifiers') ?? []
        ];
        if (levels.some(list => (list ?? []).includes('auto'))) return true;
        return /\bauto\b/.test(String(this.getTypeNameFromTypeNode(node) ?? ''));
    }

    /**
     * Whether a pointer that only ever holds register names is allowed here.
     *
     * Two ways of asking for it, and the same two the generator counts:
     * `#pragma optimize(pointer)` for all pointers, and an explicit request for
     * one of them (`int *byname p`, `p = byname(&x)`, a `byname` parameter).
     * Both need v150, since `read`/`write @this <name>` arrived there.
     *
     * @param {SymbolEntry?} [symbol] the variable being pointed at, if known
     * @returns {boolean}
     */
    namePointersEnabled(symbol = null) {
        const version = this.targetVersion ?? this.compiler?.config?.getAttribute('targetVersion') ?? 0;
        if (version < 150) return false;
        /*
        The pragma lands in `extraConfig.optimizeOption` -- the same place the
        generator reads it (`namePointerAllowed`). The two `optimizerConfig`
        objects probed below do not exist, so those probes always answered
        false; they are kept only so that a caller that passes the pragma
        through another channel keeps working.
        */
        const config = this.compiler?.extraConfig?.getAttribute?.('optimizeOption') ?? null;
        if (config?.doPointerOptimize === true) return true;
        const fallback = this.compiler?.optimizerConfig ?? null;
        if (fallback?.getAttribute?.('doPointerOptimize') === true) return true;
        if (fallback?.doPointerOptimize === true) return true;
        if (this.compiler?.config?.getAttribute?.('doPointerOptimize') === true) return true;
        // The program named the target itself: `int *byname p; p = &x;`
        if (symbol && (symbol.forcedNamePointer === true || symbol.namePointersOnly === true)) return true;
        /*
        Otherwise: the program asked for a name SOMEWHERE. Whether this very
        `&x` may be one is the optimizer's decision -- it runs later and owns
        the question -- but the answer has to be the same in both places, and
        for a call site the optimizer cannot see (the target is a local of a
        body it walks per round) the only thing that says a name is even
        possible here is that the program uses them.
        */
        if ((this.forcedNamePointers?.size ?? 0) > 0) return true;
        return false;
    }

    /**
     * A deep copy of an AST subtree.
     *
     * Needed to emit one version of an `auto` function per representation of
     * its arguments: the versions are the same program, only the parameter's
     * representation differs, so the body has to be copied rather than shared.
     *
     * @param {any} node
     * @param {Map} [seen]
     * @returns {any}
     */
    cloneAstNode(node, seen = new Map()) {
        if (node === null || node === undefined || typeof node !== 'object') return node;
        if (Array.isArray(node)) return node.map(n => this.cloneAstNode(n, seen));
        if (seen.has(node)) return seen.get(node);
        if (typeof node.type !== 'string' || !(node._attributes instanceof Map)) return node;
        const copy = new ASTNode(node.type, node.location);
        seen.set(node, copy);
        for (const [key, value] of node._attributes) copy.setAttribute(key, value);
        for (const key of Object.keys(node)) {
            /*
            A cached `scope` or `symbol` belongs to the function this was
            copied from: keeping it would make the copy's body look up names
            in a scope that is not its own. They are rebuilt when the copy is
            visited.
            */
            if (key === 'parent' || key === 'scope' || key === 'symbol'
                || key === '_attributes' || key === 'type' || key === 'location') continue;
            copy[key] = this.cloneAstNode(node[key], seen);
        }
        return copy;
    }

    /**
     * Give a copied function parameter nodes that belong to THAT copy.
     *
     * The parser builds a parameter by SPREADING an `ASTNode` into a plain
     * object (`parseParameter`), so a parameter is not an `ASTNode` and its
     * `type` is a type-specifier NODE rather than a node-type string.
     * `cloneAstNode` tests for a string `type` and, finding none, hands the very
     * same parameter object to every version made from a template.
     *
     * Writing a version's own choice onto it -- which representation its
     * parameter travels as, which struct variant it settles on -- therefore
     * wrote it onto all of them, and the version created LAST decided for the
     * others. Two versions of one `auto` function came out with the same
     * representation, so the one that should have taken a register NAME took an
     * address instead and wrote to a cell nobody had assigned.
     *
     * `type` itself is shared: a resolved type is replaced wholesale by a
     * variant rather than edited, and `cloneAstNode` shares it for the same
     * reason. The attribute map is not shared, since it is the one place a copy
     * could otherwise still write through to the version it was copied from.
     *
     * @param {any} copy The cloned function
     */
    ownParameterNodes(copy) {
        if (!Array.isArray(copy?.parameters)) return;
        copy.parameters = copy.parameters.map(param => {
            if (param === null || typeof param !== 'object') return param;
            // A parameter that really is an `ASTNode` is already the copy's own.
            if (param instanceof ASTNode) return param;
            const own = { ...param };
            if (param._attributes instanceof Map) own._attributes = new Map(param._attributes);
            return own;
        });
    }

    /**
     * The parameter type list of a function declaration, as type names.
     * @param {any} node
     * @returns {string[]}
     */
    parameterTypeNamesOf(node) {
        return (node?.parameters ?? []).map(param => String(this.getTypeNameFromTypeNode(param) ?? '?'));
    }

    /**
     * Collect every function declaration and give each one the name it will be
     * emitted under.
     *
     * Done before anything is visited, so that a call site always sees the
     * complete set of overloads -- a call may appear before some of them.
     *
     * @param {any} ast
     * @returns {void}
     */
    prescanFunctionDeclarations(ast) {
        /** @type {Map<string, Map<string, {name: string, node: any, paramTypes: string[], declarations: any[], definition: any?, mangledName: string?}>>} */
        const byName = new Map();
        for (const func of (ast?.functions ?? [])) {
            if (!func || func.type !== 'FunctionDeclaration' || !func.name) continue;
            const paramTypes = this.parameterTypeNamesOf(func);
            const signature = paramTypes.join(',');
            let entries = byName.get(func.name);
            if (!entries) { entries = new Map(); byName.set(func.name, entries); }
            let entry = entries.get(signature);
            if (!entry) {
                entry = { name: func.name, node: func, paramTypes, declarations: [], definition: null, mangledName: null };
                entries.set(signature, entry);
            }
            entry.declarations.push(func);
            func.setAttribute('overloadSignature', signature);
            func.overloadEntry = entry;
            if (func.body) {
                if (entry.definition && entry.definition !== func) {
                    this.addError(`Function '${func.name}' is already defined with these parameter types`,
                        func.location);
                } else {
                    entry.definition = func;
                    entry.node = func;
                }
            } else {
                func.isPrototype = true;
            }
        }

        this.overloadSets = new Map();
        for (const [name, entries] of byName) {
            const list = [...entries.values()];
            list.forEach((entry, index) => {
                const mangled = this.mangleFunctionName(name, index);
                entry.mangledName = mangled;
                entry.node.name = mangled;
                entry.declarations.forEach(decl => {
                    decl.name = mangled;
                    decl.mangledName = mangled;
                });
            });
            this.overloadSets.set(name, list);
        }
    }

    /**
     * The symbol of a variable that `remote(dev, x)` names by IDENTIFIER.
     *
     * `x` need not be declared in this program at all -- the variable lives on
     * the other processor, and its name is all that is needed to reach it. But
     * a SYMBOL is what carries the rest of the description (the length of an
     * array, the layout its elements have), so behave as if a global `x` of the
     * type this declaration asks for had been declared, and take its symbol.
     *
     * It is deliberately NOT added to any scope: nothing is really defined
     * here, so no registers must be emitted for it and it must not be exported.
     *
     * @param {string} name
     * @param {TypeInfo} finalType The type the declaration asks for
     * @param {any} [location]
     * @returns {SymbolEntry}
     */
    synthesiseRemoteTarget(name, finalType, location = null) {
        this.remoteTargetCache ??= new Map();
        const key = `${this.globalScope?.getPath?.() ?? 'g:'}.${name}`;
        if (this.remoteTargetCache.has(key)) return this.remoteTargetCache.get(key);
        /*
        The variable over there is an ordinary one: `remote` describes how THIS
        program reaches it, not what it is.
        */
        let type = finalType;
        if (finalType && (finalType.qualifiers ?? []).includes('remote')) {
            type = Object.create(Object.getPrototypeOf(finalType));
            Object.assign(type, finalType);
            type.qualifiers = [...finalType.qualifiers].filter(q => q !== 'remote');
        }
        const symbol = new SymbolEntry(name, { type: type }, this.globalScope, 'variable', location);
        symbol.isGlobal = true;
        this.remoteTargetCache.set(key, symbol);
        return symbol;
    }

    /**
     * How many elements a lookup table can name, and their names.
     *
     * @param {string} category item | liquid | unit | building
     * @returns {string[]}
     */
    lookupNamesFor(category) {
        const table = this.contentTable;
        if (!table?.namesOf) return [];
        const wanted = (category === 'building') ? 'block' : category;
        return (table.namesOf(wanted) ?? []).map(n => String(n).replace(/^@/, ''));
    }

    /**
     * `array("embedded_lookup_item", ...)` names its elements after contents,
     * so it cannot hold more elements than that table has names for. Without
     * this check the extra elements silently read as 0.
     *
     * @param {string} name The array's name, for the message
     * @param {string} category item | liquid | unit | building
     * @param {number} length
     * @param {any} location
     * @returns {void}
     */
    checkLookupCapacity(name, category, length, location) {
        const names = this.lookupNamesFor(category);
        if (!names.length && !this.contentTable) return;	// no table: nothing to check
        if (length > names.length) {
            this.addError(`Array '${name}' has ${length} elements, but the '${category}' `
                + `lookup table only names ${names.length}: use at most ${names.length}, `
                + `or another implementation such as array("embedded_divided", ...)`,
                location);
        }
    }

    /**
     * Which lookup table an array implementation string asks for.
     *
     * @param {string?} requested
     * @returns {string?} item | liquid | unit | building, or null
     */
    lookupCategoryOf(requested) {
        if (!requested || !String(requested).startsWith('embedded_lookup_')) return null;
        const CATEGORY_ALIASES = {
            item: 'item', liquid: 'liquid', unit: 'unit', block: 'building', building: 'building'
        };
        return CATEGORY_ALIASES[String(requested).slice('embedded_lookup_'.length)] ?? null;
    }

    /**
     * The dimensions of an array type, outermost first. `null` marks one that
     * was left unspecified (`int p[]`).
     *
     * @param {TypeInfo?} type
     * @returns {(number|null)[]}
     */
    arrayDimensionsOf(type) {
        const dims = [];
        let current = type;
        while (current && current.isTypeInfo && current.kind === 'array') {
            const size = current.arraySize ?? null;
            /*
            Two different shapes reach this point:
              - a VARIABLE keeps one dimension per array level, as the node the
                program wrote (`int a[3][4]` is an array of `int[4]`);
              - a PARAMETER keeps all of them in one place, because its type is
                rebuilt from a name like "int [3][4]".
            `NaN` (from `[]`) and a missing size both mean "unspecified".
            */
            const number = value => (Number.isFinite(Number(value)) ? Number(value) : null);
            if (Array.isArray(size)) {
                for (const entry of size) dims.push(number(entry));
            } else if (typeof size === 'number') {
                dims.push(number(size));
            } else if (size && typeof size.value !== 'undefined') {
                dims.push(number(size.value));
            } else {
                dims.push(null);
            }
            current = current.pointerTo ?? null;
        }
        return dims;
    }

    /**
     * `void f(int p[4])` may only be handed an array with at least 4 elements;
     * `void f(int p[][])` accepts any size. Every dimension is checked, so
     * `void f(int p[3][4])` needs `[>=3][>=4]`.
     *
     * @param {string} functionName
     * @param {{name: string, type: any}} declared The parameter as declared
     * @param {any} arg The argument expression
     * @param {number} index 0-based argument position
     * @returns {void}
     */
    checkArrayArgumentDimensions(functionName, declared, arg, index) {
        /*
        The function type stores a parameter's type as a name as often as not,
        so normalise it before looking for dimensions.
        */
        const paramType = this.getTypeInfo(declared?.type ?? null) ?? null;
        if (!paramType || !paramType.isTypeInfo || paramType.kind !== 'array') return;
        const argType = this.getExpressionType(arg);
        if (!argType || !argType.isTypeInfo || argType.kind !== 'array') return;
        const want = this.arrayDimensionsOf(paramType);
        const got = this.arrayDimensionsOf(argType);
        if (want.length !== got.length) {
            this.addError(
                `Argument ${index + 1} of '${functionName}' is '${this.typeToString(argType)}', `
                + `which does not have the ${want.length} dimension(s) the parameter asks for`,
                arg.location);
            return;
        }
        for (let i = 0; i < want.length; i++) {
            if (want[i] === null || got[i] === null) continue;   // `[]` accepts anything
            if (got[i] < want[i]) {
                this.addError(
                    `Argument ${index + 1} of '${functionName}' has ${got[i]} element(s) in `
                    + `dimension ${i + 1}, but the parameter needs at least ${want[i]}`,
                    arg.location);
                return;
            }
        }
    }

    /**
     * Record, for each array parameter, what the call sites hand over.
     *
     * An array argument is never silently decayed into a pointer, because a
     * non-memory array has no address to decay into. So the parameter has to
     * take over the representation the caller's array uses:
     *
     *   - `remote`      -- the elements are registers of another processor;
     *   - `names`       -- an embedded / encoded layout, so the elements are
     *                      registers here and are reached by name;
     *   - `traditional` -- an ordinary in-memory array, passed as a pointer.
     *
     * @param {any} callNode
     * @param {SymbolEntry?} funcSymbol
     * @param {{name: string, type: any}[]} expectedParams
     * @returns {void}
     */
    noteArrayArguments(callNode, funcSymbol, expectedParams) {
        if (!funcSymbol) return;
        const scope = funcSymbol.owningScope ?? null;
        if (!scope) return;
        (callNode.arguments ?? []).forEach((arg, index) => {
            const declared = expectedParams[index];
            if (!declared) return;
            const paramSymbol = scope.lookup(declared.name);
            if (!paramSymbol) return;
            const paramType = paramSymbol.myType?.() ?? null;
            if (!paramType) return;
            if (arg.type !== 'Identifier') return;
            const argSymbol = this.currentScope.lookup(arg.name);
            if (!argSymbol) return;
            const argType = argSymbol.myType?.() ?? null;
            if (!argType || argType.kind !== 'array') return;
            /*
            Handed over as a POINTER (`void f(auto int *p)` / `f(arr)`): the
            callee may write into it at any time, so its contents are no longer
            known constants. Without this, `print(arr[0])` after the call is
            folded back to the initial value and the write is lost.
            */
            if (paramType.kind === 'pointer') {
                argSymbol.arrayEscapes = true;
                return;
            }
            if (paramType.kind !== 'array') return;
            const notes = paramSymbol.arrayArgumentNotes
                ?? (paramSymbol.arrayArgumentNotes = {
                    remote: false, register: false, traditional: false, requested: new Set()
                });
            const requested = argSymbol.requestedArrayImplementation ?? null;
            if (argSymbol.isRemote === true) {
                notes.remote = true;
            } else if (argSymbol.isUnboundHandle === true) {
                /*
                A bound unbound-handle (`int h[]; h = someArray;`) holds a PACKED
                HANDLE in its one cell, whatever it was bound to. Passing it has
                to say "handle", not "traditional pointer": a two-word pointer
                shape built from that one-word value is garbage, and a SIZED
                parameter (which trusts the call-site note, unlike an open one)
                would read through it and trap -- the case recorded in
                OPEN_WORK §6.
                */
                notes.register = true;
            } else if (requested && requested !== 'traditional') {
                notes.register = true;
                notes.requested.add(requested);
            } else {
                notes.traditional = true;
            }
            /*
            The callee can write into the array, and this program cannot see
            when it does. So the array is no longer a set of known constants --
            without this, `print(a[1])` after a call would be folded back to the
            value the array was initialised with and lose the write.
            */
            argSymbol.arrayEscapes = true;
        });
    }

    /**
     * Bind the `remote()` directives whose array was declared further down.
     *
     * @returns {void}
     */
    finalizeRemoteLinks() {
        const pending = this.pendingRemoteLinks ?? [];
        this.pendingRemoteLinks = [];
        for (const entry of pending) {
            entry.declarator.initializer = entry.initializer;
            this.consumeRemoteDirective(entry.declarator, entry.symbol, entry.finalType,
                entry.qualifiers, true);
        }
        for (const entry of (this.pendingRemoteLinks ?? [])) {
            /*
            Retrying with `deferred` set resolves it against a global symbol of
            the required type -- which is enough unless the length of an array
            is still unknown, the one thing a name alone cannot supply.
            */
            entry.declarator.initializer = entry.initializer;
            this.consumeRemoteDirective(entry.declarator, entry.symbol, entry.finalType,
                entry.qualifiers, true);
        }
        this.pendingRemoteLinks = [];
    }

    /**
     * Which representation an `auto` parameter has to use, given the CONCRETE
     * parameter type a function pointer spells out.
     *
     * A function pointer is a line number: nothing at run time can choose, so
     * the version has to be picked here, from the type the pointer declares.
     *
     * @param {TypeInfo|string?} expected
     * @returns {'name' | 'memory' | 'traditional' | null}
     */
    autoRepFromExpectedType(expected) {
        let t = (typeof expected === 'string') ? this.getTypeInfo(expected) : expected;
        if (!t) return null;
        const quals = this.qualifiersOfTypeInfo(t);
        if (t.kind === 'pointer') {
            return quals.includes('byname') ? 'name' : 'memory';
        }
        if (t.kind === 'struct' || t.kind === 'union') {
            const members = t.members ?? [];
            if (members.some(m => m.namePointer === true)) return 'name';
            return 'memory';
        }
        if (t.kind === 'array') {
            return (quals.includes('remote')) ? 'handle' : 'traditional';
        }
        return 'memory';
    }

    /**
     * The type a parameter descriptor names.
     *
     * A parameter of a function POINTER reached through a `typedef` keeps its
     * type as a name (`{ name, type: 'int*' }`), while a function DECLARATION's
     * parameter has the type already resolved. Both have to be readable here.
     *
     * @param {any} p A parameter descriptor
     * @returns {TypeInfo?}
     */
    parameterTypeInfo(p) {
        if (!p) return null;
        if (p.isTypeInfo === true) return p;
        if (typeof p.type === 'string') return this.getTypeInfo(p.type) ?? null;
        return p.type ?? p;
    }

    /**
     * The qualifiers written on a type, wherever they were written.
     *
     * A qualifier describes the LEVEL it was written on, and for a pointer those
     * levels are different types: `const int *` is a pointer to a constant int,
     * `int *const` is a constant pointer to a plain int. So there is no separate
     * list to consult -- each level of the `pointerTo` chain carries its own
     * `qualifiers`, and the whole set is what this walks. (`pointerQualifiers`
     * used to be read here, on a field no `TypeInfo` ever had, which is how a
     * per-level qualifier came to be ignored.)
     *
     * @param {TypeInfo?} t
     * @returns {string[]}
     */
    qualifiersOfTypeInfo(t) {
        const found = [];
        for (let level = t, guard = 0; level && guard < 64; guard++) {
            for (const q of (level.qualifiers ?? [])) {
                if (!found.includes(q)) found.push(q);
            }
            level = level.pointerTo ?? null;
        }
        return found;
    }

    /**
     * Tell a parameter symbol which representation its argument travels as.
     *
     * One place, because two callers have to mean exactly the same thing: the
     * `auto` versions, whose representation was worked out from the argument
     * each call site hands over, and a function reached through a FUNCTION
     * POINTER, whose representation is the one the pointer's own type spells
     * out. They set flags the code generator reads, and the two sides of a
     * call only agree if both are set the same way.
     *
     * @param {SymbolEntry?} paramSymbol
     * @param {TypeInfo?} gotType What the parameter turns out to be
     * @param {'name' | 'memory' | 'handle' | 'traditional' | 'scalar' | null} rep
     * @returns {void}
     */
    applyAutoRepToParamSymbol(paramSymbol, gotType, rep) {
        if (!paramSymbol || !rep) return;
        if (rep === 'name') {
            paramSymbol.usesNamePointer = true;
            paramSymbol.forcedNamePointer = true;
            return;
        }
        if (rep !== 'memory' && rep !== 'handle') return;
        paramSymbol.noNamePointer = true;
        paramSymbol.arrayParamRep = (rep === 'handle' && gotType?.kind === 'array')
            ? 'handle' : (gotType?.kind === 'array' ? 'traditional' : null);
    }

    /**
     * The parameter list of a function POINTER type.
     *
     * The two ways a function pointer reaches the compiler keep the signature
     * in different places. One written out in place (`void (*f)(int *);`) has
     * it on the type itself; one reached through a `typedef` keeps it one level
     * down, on the symbol the type points at, because the type IS the
     * function's -- `kind` is `function`, and the parameters are on
     * `functionTo.type.parameters`.
     *
     * Asking only the outer type therefore found nothing at all for a
     * typedef'd pointer, and everything that reads a function pointer's
     * signature quietly did nothing: the `auto` version such a pointer needs
     * was never made, and an `auto` written in such a signature was never
     * rejected.
     *
     * @param {TypeInfo?} type
     * @returns {any[]?} the parameters, or null if this is not a function pointer
     */
    functionPointerParametersOf(type) {
        if (!type) return null;
        if (Array.isArray(type.parameters)) return type.parameters;
        const to = type.functionTo ?? null;
        if (Array.isArray(to?.type?.parameters)) return to.type.parameters;
        if (Array.isArray(to?.parameters)) return to.parameters;
        if (Array.isArray(to?.myType?.()?.parameters)) return to.myType().parameters;
        return null;
    }

    /**
     * A function pointer may not name a template: it would need a choice that
     * only exists at run time.
     *
     * @param {TypeInfo?} functionPointerType
     * @param {any} location
     * @returns {boolean} whether it was rejected
     */
    rejectTemplateInFunctionPointer(functionPointerType, location) {
        const params = this.functionPointerParametersOf(functionPointerType);
        if (!params) return false;
        for (const p of params) {
            const raw = p?.type ?? p;
            let t = (typeof raw === 'string') ? this.getTypeInfo(raw) : raw;
            if (!t) continue;
            const quals = this.qualifiersOfTypeInfo(t);
            if (quals.includes('auto')) {
                this.addError(`A function pointer cannot have an 'auto' parameter: its value is a `
                    + `line number, so nothing can choose the version at run time. Write the `
                    + `concrete type instead`, location);
                return true;
            }
            const canonical = this.canonicalStructType(t.kind === 'pointer' ? t.pointerTo : t);
            if (canonical?.isTemplate === true) {
                this.addError(`A function pointer cannot name the template '${canonical.name}': `
                    + `write the concrete struct it settles on instead`, location);
                return true;
            }
        }
        return false;
    }

    /**
     * Which representation an `auto` parameter has to use for one argument.
     *
     * Only what can be known for sure is used; everything else falls back to
     * the representation that is always correct (a memory pointer, or an array
     * handle). Guessing the other way would generate wrong code.
     *
     * @param {any} template The function declaration
     * @param {number} index Which parameter
     * @param {any} arg The argument at this call site
     * @returns {'name' | 'memory' | 'handle' | 'unknown'}
     */
    /**
     * The declaration a name refers to, found in the AST itself.
     *
     * Needed because an `auto` function is specialised BEFORE the program is
     * visited: at that point no scope holds the locals yet, so `scope.lookup()`
     * cannot answer. Everything that decides a representation -- `remote`,
     * `array("embedded_divided", ...)`, a plain `int b[4]` -- is visible in the
     * source, so reading it there is enough.
     *
     * @param {any} ast
     * @param {string} name
     * @returns {{declarator: any, declaration: any, isRemote: boolean}?}
     */
    findDeclarationOf(ast, name) {
        const wanted = String(name ?? '');
        if (!wanted) return null;
        let found = null;
        const look = declaration => {
            if (found || !declaration) return;
            for (const declarator of (declaration.declarators ?? [])) {
                if (String(declarator?.name ?? '') !== wanted) continue;
                const qualifiers = [
                    ...(declaration.type?.getAttribute?.('qualifiers') ?? []),
                    ...(declarator.type?.getAttribute?.('qualifiers') ?? [])
                ];
                /*
                `remote int ru[] = remote(dev, u)`: the qualifier may sit on the
                declaration or on the declarator, and the binding itself is a
                `remote(...)` call -- any of the three is enough to tell that the
                array lives in another processor.
                */
                const initializer = declarator?.initializer ?? null;
                const called = initializer?.type === 'BuiltinCall'
                    ? initializer.functionName
                    : (initializer?.callee?.name ?? null);
                const isRemote = qualifiers.includes('remote') || called === 'remote';
                found = { declarator, declaration, isRemote };
                return;
            }
        };
        /*
        A directed walk: global declarations, then each function's statements
        (into nested blocks). Walking every property instead wandered into the
        type tables and never came back.
        */
        const statements = list => {
            for (const statement of (list ?? [])) {
                if (found || !statement || typeof statement !== 'object') continue;
                if (statement.type === 'VariableDeclaration') look(statement);
                else if (statement.type === 'CompoundStatement') statements(statement.statements);
                else if (statement.body) {
                    if (statement.body.type === 'CompoundStatement') statements(statement.body.statements);
                    else statements([statement.body]);
                }
            }
        };
        statements(ast?.globalDeclarations ?? []);
        for (const func of (ast?.functions ?? [])) {
            if (found) break;
            statements(func?.body?.statements ?? []);
        }
        return found;
    }

    autoRepresentationOf(template, index, arg, ast = null) {
        const param = (template.parameters ?? [])[index];
        if (!param) return 'unknown';
        const type = this.getTypeInfo(this.getTypeNameFromTypeNode(param));
        /*
        Look at the PARAMETER before looking at the argument: whether there is
        anything to decide follows from the parameter alone.

        A SCALAR has exactly one representation, so `void f(auto int x)` is
        simply `void f(int x)` -- nothing is specialised and no argument has to
        be inspected. Refusing anything but a bare name here is what rejected
        `f(3)`, `f((int)q)` and every other ordinary expression.
        */
        if (!type) return 'unknown';
        if (type.kind !== 'array' && type.kind !== 'pointer') return 'scalar';
        let inner = arg;
        if (inner && inner.type === 'UnaryExpression' && inner.operator === '&') inner = inner.argument;
        const symbol = (inner && inner.type === 'Identifier')
            ? (inner.symbol ?? this.globalScope?.lookup?.(inner.name) ?? null) : null;
        const declaration = (inner && inner.type === 'Identifier' && ast)
            ? this.findDeclarationOf(ast, inner.name) : null;
        if (!symbol && !declaration) return 'unknown';
        if (type && type.kind === 'array') {
            /*
            Decided from the declaration, because the choice is a property of
            how the array was written -- and it has to be known while the
            versions are still being made.
            */
            if (declaration?.isRemote || symbol?.isRemote === true) return 'handle';
            const requested = declaration?.declarator?.getAttribute?.('arrayImplementation')
                ?? symbol?.requestedArrayImplementation ?? null;
            if (requested === 'traditional') return 'memory';
            if (requested) return 'handle';
            /*
            Nothing was written down, so the layout is chosen automatically --
            and that choice is not visible here. The refusal this spot was
            written to make was gated on `compiler.arrayOptimize`, which nothing
            ever sets, so the answer falls to the language default: memory
            (docs/OPEN_WORK.md 3.5).
            */
            return 'memory';
        }
        if (type && type.kind === 'pointer') {
            /*
            `&x` can be the NAME of x, which lets x stay in a register -- but
            only when x really is one plain register and name pointers are on.
            */
            if (arg && arg.type === 'UnaryExpression' && arg.operator === '&') {
                if (symbol) {
                    const targetType = symbol.myType?.() ?? null;
                    const oneRegister = !!targetType && targetType.size === 1
                        && !['array', 'struct', 'union'].includes(targetType.kind);
                    /*
                    Whether `&x` can be a NAME has to be judged from what `x`
                    IS, not from flags that taking its address has already set:
                    `&x` marks the symbol `accessThroughPointer`, so asking for
                    `!accessThroughPointer` here asked whether the address had
                    been taken -- which it has, by definition. The answer was
                    therefore always 'memory', and the 'name' version of an
                    `auto` function was never emitted.
                    */
                    const movable = !symbol.isVolatile && !symbol.isExtern && !symbol.isStatic && !symbol.isPersistent
                        && !symbol.needMemoryAllocation;
                    if (oneRegister && movable && this.namePointersEnabled(symbol)) return 'name';
                    return 'memory';
                }
                /*
                A local: no symbol yet, so judge the declaration. A plain scalar
                that nothing else forces into memory can be named.
                */
                const qualifierList = [
                    ...(declaration?.declaration?.type?.getAttribute?.('qualifiers') ?? []),
                    ...(declaration?.declarator?.type?.getAttribute?.('qualifiers') ?? [])
                ];
                const forced = qualifierList.includes('volatile') || qualifierList.includes('extern')
                    || qualifierList.includes('static') || qualifierList.includes('persistent');
                const typeName = String(declaration?.declarator?.type?.typeName
                    ?? declaration?.declaration?.type?.typeName ?? '');
                const composite = /\bstruct\b|\bunion\b|\[/.test(typeName);
                if (!forced && !composite && this.namePointersEnabled()) return 'name';
                return 'memory';
            }
            if (symbol.usesNamePointer === true) return 'name';
            if (symbol.myType?.()?.kind === 'array') return 'memory';
            return 'memory';
        }
        return 'unknown';
    }

    /**
     * Does the body use the `auto` parameter in a way only an address allows?
     *
     * A name pointer or an array handle cannot be moved, so `s + 1` (and
     * `s[i]`, which is the same thing) rules that instance out.
     *
     * @param {any} template
     * @param {string} paramName
     * @returns {boolean}
     */
    autoBodyNeedsAddress(template, paramName) {
        let found = false;
        /*
        `deepWalk` reaches only child nodes, so no `seen` set and no depth cap
        are needed: every object it visits is a node, and the walk terminates
        on its own.
        */
        const walk = node => {
            if (!node || typeof node !== 'object' || found) return;
            /*
            Only this node is looked at: the DESCENT is `deepWalk`'s job, and
            calling it again from here would hand it the same node back and
            never finish.
            */
            /*
            An ARRAY parameter is a different matter: `s[i]` is a subscript, and
            a handle supports that (it is what indexing a handle means). Only
            moving the parameter itself -- `s + 1` -- needs an address.
            */
            const paramIsArray = (() => {
                const p = (template.parameters ?? []).find(x => String(x?.name ?? '') === paramName);
                if (!p) return false;
                const t = this.getTypeInfo(this.getTypeNameFromTypeNode(p));
                return !!t && t.kind === 'array';
            })();
            if (node.type === 'BinaryExpression'
                && (node.operator === '+' || node.operator === '-')
                && [node.left, node.right].some(side => side?.type === 'Identifier' && side.name === paramName)) {
                found = true; return;
            }
            if (node.type === 'MemberExpression' && !paramIsArray) {
                const object = node.children?.[0] ?? node.object ?? null;
                if (object?.type === 'Identifier' && object.name === paramName) { found = true; return; }
            }
        };
        this.deepWalk(template.body, walk);
        return found;
    }

    /**
     * Emit one version of every `auto` function per representation of its
     * arguments.
     *
     * `void f(auto int *s)` is a TEMPLATE, not a function: what `s` has to be
     * (a name, an address, an array handle) depends on what each call site
     * hands over. One call site needing a name and another needing an address
     * used to be a silent miscompilation -- a single function cannot do both.
     * Here each call site picks its own version.
     *
     * @param {any} ast
     * @returns {void}
     */
    expandAutoTemplates(ast) {
        const templates = (ast?.functions ?? []).filter(
            func => func?.body && (func?.parameters ?? []).some((param, i) => this.hasAutoQualifier(param)));
        if (!templates.length) return;

        /** @type {any[]} */
        const calls = [];
        this.deepWalk(ast, node => {
            if (node.type === 'FunctionCall') calls.push(node);
        });

        /*
        Value uses: `fptr z = handler;` -- the function is named, not called.
        The pointer's own parameter types say which version is wanted.
        */
        const valueUses = this.functionValueUses(ast);

        for (const template of templates) {
            const originalName = String(template.name ?? '');
            /*
            Marked: it is a pattern, not a function that is emitted. Its
            parameters carry the notes of every call site mixed together, which
            is exactly what the versions are here to separate -- so later passes
            must not read them.
            */
            template.setAttribute('autoTemplate', true);
            const autoIndices = (template.parameters ?? [])
                .map((param, i) => (this.hasAutoQualifier(param) ? i : -1)).filter(i => i >= 0);
            const mine = calls.filter(call => call?.callee?.type === 'Identifier'
                && String(call.callee.name) === originalName);
            const groups = new Map();
            for (const call of mine) {
                const signature = autoIndices
                    .map(i => this.autoRepresentationOf(template, i, call.arguments?.[i] ?? null, ast)).join('|');
                if (!groups.has(signature)) groups.set(signature, []);
                groups.get(signature).push(call);
            }
            /*
            A function pointer cannot name a template -- so what it DOES name
            decides the version.
            */
            /** @type {Map<string, any[]>} signature -> identifier nodes to retarget */
            const retarget = new Map();
            for (const use of valueUses) {
                if (String(use.node?.name) !== originalName) continue;
                const holder = use.holder ?? null;
                if (!holder) continue;
                const sym = use.owner?.scope?.lookup?.(holder)
                    ?? this.globalScope?.lookup?.(holder) ?? null;
                const fpType = sym?.myType?.() ?? null;
                const fpParams = this.functionPointerParametersOf(fpType);
                if (!fpParams) continue;
                if (this.rejectTemplateInFunctionPointer(fpType, use.node.location ?? null)) continue;
                const signature = autoIndices
                    .map(i => this.autoRepFromExpectedType(fpParams[i]?.type ?? fpParams[i]))
                    .join('|');
                if (!signature || signature.split('|').some(r => !r)) {
                    this.addError(`'${originalName}' has an 'auto' parameter, and '${holder}' `
                        + `does not say which version it wants`, use.node.location ?? null);
                    continue;
                }
                if (!groups.has(signature)) groups.set(signature, []);
                if (!retarget.has(signature)) retarget.set(signature, []);
                retarget.get(signature).push(use.node);
            }
            if (groups.size === 0) continue;
            /*
            Nothing is really being overloaded here, just specialised: mark
            every instance so the versions keep their own names.
            */
            const instances = [];
            let index = 0;
            for (const [signature, callSites] of groups) {
                const reps = signature.split('|');
                if (reps.includes('ambiguous')) {
                    this.addError(`'${originalName}' has an 'auto' parameter, and this call hands it `
                        + `an array whose layout is chosen automatically -- which one it is cannot be `
                        + `known here. Write it down (array("embedded_divided", ...), or `
                        + `array("traditional", ...)), or turn '#pragma optimize(array)' off`,
                        callSites[0]?.location ?? null);
                    continue;
                }
                if (reps.includes('unknown')) {
                    this.addError(`'${originalName}' has an 'auto' parameter, and what this call hands `
                        + `it cannot be made out`, callSites[0]?.location ?? null);
                    continue;
                }
                const name = this.mangleFunctionName(originalName, index++);
                for (let a = 0; a < autoIndices.length; a++) {
                    const paramIndex = autoIndices[a];
                    const paramName = template.parameters[paramIndex]?.name;
                    /*
                    `scalar` is exempt: `x + 1` on a plain int is arithmetic,
                    not a pointer being stepped, so it says nothing about the
                    representation.
                    */
                    if (reps[a] !== 'memory' && reps[a] !== 'scalar' && paramName
                        && this.autoBodyNeedsAddress(template, paramName)) {
                        this.addError(`Parameter '${paramName}' of '${originalName}' is 'auto', and this `
                            + `call hands it something that has no address (${reps[a]}) -- but the body `
                            + `moves the pointer (s + 1, or s[i]), which needs one`,
                            callSites[0]?.location ?? null);
                    }
                }
                const copy = this.cloneAstNode(template);
                copy.name = name;
                copy.scope = null;
                copy.setAttribute('autoInstance', true);
                copy.setAttribute('autoReps', signature);
                this.ownParameterNodes(copy);
                autoIndices.forEach((paramIndex, a) => {
                    const param = copy.parameters?.[paramIndex];
                    /*
                    The representation goes on the parameter node rather than on
                    the function, because the signature is written per parameter.
                    It only means anything now that the copy owns its parameter
                    nodes: a parameter is a plain object, so before that every
                    version shared one and the last version created decided for
                    all of them -- which is how a version meant to take a NAME
                    came out taking an address.
                    */
                    if (param) param.autoRep = reps[a];
                });
                instances.push(copy);
                for (const call of callSites) {
                    call.callee.name = name;
                    call.callee.setAttribute('overloadResolved', true);
                }
                for (const ident of retarget.get(signature) ?? []) {
                    ident.name = name;
                    ident.setAttribute('overloadResolved', true);
                }
            }
            const list = ast.functions ?? [];
            const at = list.indexOf(template);
            /*
            Nothing could be specialised (every call was refused): keep the
            template, so the program still names something.
            */
            if (!instances.length) continue;
            /*
            The template was already visited, so its name is taken. Drop the
            symbol before the versions claim the names -- the first version
            keeps the plain name.
            */
            for (const scope of [this.globalScope, template.scope]) {
                if (scope?.symbols?.delete) scope.symbols.delete(originalName);
            }
            if (at >= 0) list.splice(at, 1, ...instances);
            /*
            The versions are built after the program was visited, so they have
            to be visited now -- that is what gives each one its own scope and
            its own parameter symbols.
            */
            const savedScope = this.currentScope;
            this.currentScope = this.globalScope;
            for (const instance of instances) this.visit(instance);
            /*
            Each version has to be told how its `auto` parameter arrives.

            The choice was made from the call sites of the TEMPLATE, but a
            version gets a fresh parameter symbol when it is visited -- and
            `finalizeArrayParameters` decides from the notes gathered on that
            symbol, of which a fresh one has none. It therefore fell back to
            `traditional`, i.e. a pointer: right for a memory array, wrong for
            one held in registers or in another processor. (Inlining hid this,
            because an inlined parameter borrows the caller's array instead.)
            */
            for (const instance of instances) {
                const signature = instance.getAttribute?.('autoReps') ?? null;
                if (!signature) continue;
                const reps = String(signature).split('|');
                autoIndices.forEach((paramIndex, a) => {
                    const rep = reps[a];
                    if (!rep || rep === 'scalar') return;
                    const paramNode = (instance.parameters ?? [])[paramIndex];
                    const paramName = paramNode?.name ?? template.parameters?.[paramIndex]?.name;
                    if (!paramName) return;
                    const symbol = instance.scope?.lookupCurrent?.(paramName) ?? null;
                    if (!symbol || symbol.myType?.()?.kind !== 'array') return;
                    symbol.arrayParamRep = (rep === 'memory') ? 'traditional' : 'handle';
                });
            }
            this.currentScope = savedScope;
            /*
            A function stored into a function pointer was named while the
            PATTERN was still the only declaration, so the identifier holds a
            reference to it. The name alone is not enough: the generator reads
            the cached symbol, and so does the check that the value being stored
            fits the pointer's type -- which is how storing a version was
            refused against the pattern's `auto int *` even though the version
            the pointer names is an ordinary `int *`.
            */
            for (const [signature, idents] of retarget) {
                const instance = instances.find(i => i.getAttribute?.('autoReps') === signature);
                if (!instance) continue;
                const copySymbol = this.symbolByName(instance.name);
                if (!copySymbol) continue;
                for (const ident of idents) ident.symbol = copySymbol;
            }
            for (const call of mine) {
                if (call?.callee?.type !== 'Identifier') continue;
                call.callee.symbol = this.globalScope?.lookup?.(call.callee.name) ?? call.callee.symbol;
            }
            /*
            The versions are chosen by representation, not by type -- so put
            them in the overload set under the name they were written with,
            and let the call sites (already rewritten) keep their pick.
            */
            this.overloadSets?.set(originalName,
                instances.map(node => ({ node, paramTypes: this.parameterTypeNamesOf(node) })));
        }
    }

    /**
     * The places a function is NAMED rather than called: its value is stored.
     *
     * @param {any} ast
     * @returns {any[]} `{ node, owner, holder }` per stored function
     */
    functionValueUses(ast) {
        /** @type {any[]} */
        const valueUses = [];
        this.deepWalk(ast, n => {
            if (n.type === 'VariableDeclarator' && n.initializer?.type === 'Identifier') {
                valueUses.push({ node: n.initializer, owner: n, holder: n.name });
            } else if (n.type === 'AssignmentExpression' && n.right?.type === 'Identifier') {
                valueUses.push({ node: n.right, owner: n, holder: n.left?.name });
            }
        });
        return valueUses;
    }

    /**
     * Pin the representation of a NON-template function that is reached through
     * a function pointer.
     *
     * `expandAutoTemplates` does this for an `auto` function, by making one
     * version per representation. A function with no `auto` parameter has only
     * ONE version, so the representation has to be settled here instead of
     * being discovered at each call -- and the only thing that can settle it is
     * the type the function pointer spells out.
     *
     * It has to be settled HERE, before anything else decides. An indirect call
     * carries no information about the callee: at run time the pointer is a
     * line number, and the call site can only hand over what the callee's
     * parameter was compiled to expect. Left to itself the analysis picked a
     * representation from the callee alone, and the call site disagreed --
     * the callee read a register NAME while the call site sent an address, so
     * the parameter was whatever `__param_0` happened to hold (zero), and the
     * program printed 0 instead of the value it had just been given.
     *
     * What the pointer's type can say is limited, and what it cannot say is
     * refused rather than guessed at. Its parameters travel as type NAMES, and
     * no type name carries a pointer qualifier: `void (*)(int *byname)` reads
     * back as `int*`. So where a qualifier decides the representation -- the
     * NAME a `byname` pointer carries -- there is nothing here to read it from,
     * and the address is all this pass can see. Pinning that would answer a
     * question the pointer type never got asked.
     *
     * @param {any} ast
     * @returns {void}
     */
    pinValueTakenRepresentations(ast) {
        const valueUses = this.functionValueUses(ast);
        if (!valueUses.length) return;
        const functions = ast?.functions ?? [];
        if (!functions.length) return;

        for (const use of valueUses) {
            const originalName = String(use.node?.name ?? '');
            const holder = use.holder ?? null;
            if (!originalName || !holder) continue;
            const fnNode = functions.find(f => String(f?.name ?? '') === originalName);
            if (!fnNode) continue;
            /*
            The pointer's own type is the only place the representation is
            written down: `cb f = test;` where `cb` is `void (*)(int *)` says
            the parameter travels as an ADDRESS.
            */
            const fpType = use.owner?.scope?.lookup?.(holder)?.myType?.() ?? null;
            const fpParams = this.functionPointerParametersOf(fpType);
            if (!fpParams) continue;
            if (this.rejectTemplateInFunctionPointer(fpType, use.node.location ?? null)) continue;

            /*
            An `auto` parameter is not settled here at all: it has one version
            per representation, and which one applies is decided by the
            argument. `expandAutoTemplates` has already made the version a
            function pointer names.
            */
            if ((fnNode.parameters ?? []).some(param => this.hasAutoQualifier(param))) continue;

            /*
            A qualifier the pointer's own type cannot spell out.
            A function pointer's parameters travel as type NAMES, and no type
            name carries a pointer qualifier: `void (*)(int *byname)` reads
            back as `int*`. So where the declaration asks for a representation
            by that means -- the NAME a `byname` pointer carries -- there is
            nothing here to read it from, and the address is the only thing
            this pass can see. The two sides would then disagree about the
            argument, silently: the callee reads a name, the call site sends
            an address. Saying so beats shipping that.
            */
            const spelledOut = (fnNode.parameters ?? []).some((param, i) => {
                const asked = [
                    ...(param?.pointerQualifiers ?? []),
                    ...(param?.type?.pointerQualifiers ?? []),
                ].flat().filter(q => q === 'byname' || q === 'remote');
                if (!asked.length) return false;
                const said = this.qualifiersOfTypeInfo(this.parameterTypeInfo(fpParams[i]));
                return !said.some(q => asked.includes(q));
            });
            if (spelledOut) {
                this.addError(`'${originalName}' is given to a function pointer, and a function `
                    + `pointer's parameter type cannot say 'byname' or 'remote': the two reach the `
                    + `compiler as plain type names, which carry neither. The parameter would be `
                    + `handed one representation and read as the other. Write the parameter without `
                    + `the qualifier`, use.node?.location ?? null);
                continue;
            }

            /*
            All of it, or none of it. Pinning the parameters we can make out
            while leaving the rest to be discovered would leave the function
            able to answer to two representations at once, which is the failure
            this exists to remove.
            */
            const reps = [];
            for (let i = 0; i < (fnNode.parameters ?? []).length; i++) {
                const rep = this.autoRepFromExpectedType(fpParams[i]?.type ?? fpParams[i]);
                if (!rep) { reps.length = 0; break; }
                reps.push(rep);
            }
            if (reps.length !== (fnNode.parameters ?? []).length) continue;

            (fnNode.parameters ?? []).forEach((param, i) => {
                const paramName = param?.name;
                if (!paramName) return;
                const symbol = fnNode.scope?.lookupCurrent?.(paramName) ?? null;
                if (!symbol) return;
                this.applyAutoRepToParamSymbol(symbol, symbol.myType?.() ?? null, reps[i]);
            });
        }
    }

    /**
     * Whether `remote` appears anywhere on a type -- on the array itself, or on
     * the element level (`remote int s[4]` puts it on `int`).
     *
     * @param {TypeInfo?} type
     * @returns {boolean}
     */
    typeHasRemoteQualifier(type) {
        let current = type ?? null;
        let guard = 0;
        while (current && guard++ < 8) {
            if ((current.qualifiers ?? []).includes('remote')) return true;
            current = current.pointerTo ?? null;
        }
        return false;
    }

    /**
     * Decide and remember one array's layout, using only the facts that are
     * settled by the end of semantic analysis: the parameter representation
     * (`finalizeArrayParameters`), `remote`, `volatile`, and an explicit
     * `array("...")` request. The generator reads `symbol.chosenArrayStyle`
     * and re-forces the choice only for the one fact decided later -- whether
     * the function is recursive (`recursiveInfo` is built by the optimizer).
     *
     * The automatic choice (memory, instruction budget, initial values) is
     * deliberately NOT made here: whether the array's memory allocation
     * actually succeeds, and what its literal contents are, are known only
     * once the generator runs, and guessing either would change which
     * programs compile.
     *
     * The order below mirrors the generator's `arrayStyleFor` exactly --
     * parameter representation, then `remote`, then `volatile`, then the
     * request -- so both compute the same style for every case handled here.
     *
     * @param {SymbolEntry?} symbol
     * @returns {{type: string, implement: string?, reason: string}?} null when
     *          the layout still depends on generator-time facts
     */
    arrayStyleFor(symbol) {
        if (!symbol) return null;
        if (symbol?.arrayAliasOf) return this.arrayStyleFor(symbol.arrayAliasOf);
        if (symbol.chosenArrayStyle) return symbol.chosenArrayStyle;
        const rep = symbol.arrayParamRep ?? null;
        if (rep === 'handle') {
            symbol.chosenArrayStyle = { type: 'embedded', implement: 'divided', reason: 'array parameter' };
            return symbol.chosenArrayStyle;
        }
        if (rep === 'traditional') {
            symbol.chosenArrayStyle = { type: 'traditional', implement: null, reason: 'array parameter' };
            return symbol.chosenArrayStyle;
        }
        if (symbol.isRemote === true) {
            symbol.chosenArrayStyle = { type: 'embedded', implement: 'divided', reason: 'remote array' };
            return symbol.chosenArrayStyle;
        }
        /*
        `volatile` is settled by the declaration, and it outranks an explicit
        request just as the generator's `forcedTraditionalReason` lets it.
        Recursion is NOT checked here on purpose: `recursiveInfo` does not
        exist yet, so the generator re-forces the cached choice when it does.
        */
        if (symbol.isVolatile === true || symbol.myType()?.isVolatile?.()) {
            symbol.chosenArrayStyle = { type: 'traditional', implement: null,
                reason: 'a volatile array must be kept in memory' };
            return symbol.chosenArrayStyle;
        }
        const requested = symbol.requestedArrayImplementation ?? null;
        if (requested) {
            const style = normalizeImplementation(requested);
            /*
            A `lookup` request still needs the category the generator picks
            from the content table (`lookupNamesOf`), and an unrecognized name
            falls through to the automatic choice -- both are left to the
            generator, which sees those facts.
            */
            if (style && style.implement !== 'lookup') {
                symbol.chosenArrayStyle = style;
                return style;
            }
        }
        return null;
    }

    /**
     * How an array is really stored, which is what decides whether two arrays
     * are the same thing at all.
     *
     * The layout is the point. An array in memory and an array in registers
     * share no representation: there is no single instruction that turns one
     * into the other, so nothing that is true of one is true of the other. A
     * HANDLE is a third kind of thing again -- it is a description of an array
     * rather than one, which is why `int s[]` may travel as a handle while
     * `int s[4]` cannot.
     *
     * A handle is also the one representation that cannot leave the processor.
     * The two helper entry points it packs are LINE NUMBERS in this program
     * (`helperAddressOf`), so the same number means something else entirely on
     * another one, and a remote array is not reachable by a handle at all.
     * That is why a remote array is its own kind here rather than one of the
     * local ones.
     *
     * The answer is READ, not re-derived: `arrayStyleFor` owns the decision,
     * and this maps its style onto the words the call sites know. A parameter
     * answers by its representation; a request answers by the layout it named
     * -- `traditional` as `'memory'`, and any other NAMED layout (`encoded`,
     * `embedded`) by its OWN name, so the yes/no questions these call sites
     * ask can tell two differently-named layouts apart instead of reading two
     * `null`s as the same thing. The remaining styles are settled by the
     * declaration itself (volatile), or are a remote array -- including one
     * reached through an alias, which is where following the alias matters.
     *
     * `null` when only the generator can tell: a `lookup` request whose
     * category comes from the content table. When nothing decided at all the
     * answer is the language default, memory -- a ruling, not a guess. (The
     * `#pragma optimize(array)` -> `null` branch the body used to carry is
     * gone: it was gated on `compiler.arrayOptimize`, which nothing ever sets;
     * `docs/OPEN_WORK.md` 3.5.)
     *
     * @param {SymbolEntry?} symbol
     * @returns {'memory' | 'handle' | 'remote' | 'encoded' | 'embedded' | null}
     */
    arrayImplementationOf(symbol) {
        if (!symbol) return null;
        if (symbol.isRemote === true || this.typeHasRemoteQualifier(symbol.myType?.())) {
            return 'remote';
        }
        const style = this.arrayStyleFor(symbol);
        if (style) {
            if (style.reason === 'array parameter') {
                return symbol.arrayParamRep === 'handle' ? 'handle' : 'memory';
            }
            if (style.reason === 'requested') {
                return style.type === 'traditional' ? 'memory' : style.type;
            }
            if (style.reason === 'remote array') return 'remote';
            return 'memory';    // a volatile array: its declaration settled it
        }
        // A `lookup` request also comes back styleless -- the generator picks
        // its category from the content table -- and the request says so.
        if (symbol.requestedArrayImplementation != null) return null;
        return 'memory';
    }

    /**
     * Enforce the two rules that keep an UNBOUND handle (`int a[];` declared
     * with no initializer) honest:
     *
     *   - it is PROVABLY unreadable: a read (a subscript, `lenof`, `sizeof`, or
     *     the right side of an assignment) that sits textually before its first
     *     binding IN THE SAME FUNCTION is a compile error;
     *   - binding it is `a = b;` (or, later, `vecalias(&a, b);`) -- and a handle
     *     that is never bound anywhere is a compile error too.
     *
     * A read in a function that never binds the handle is allowed to stand: the
     * binding may live in the caller, and only run time can tell. A handle that
     * ESCAPES unbound (handed to a function, or a binding whose branch was not
     * taken) is likewise left to run time: the cell starts at 0, and extracting
     * a 0-packed handle jumps to line 0, the same trap an uninitialised pointer
     * sets off.
     *
     * @param {any} ast
     * @returns {void}
     */
    checkUnboundHandles(ast) {
        /*
        Every unbound handle in the program, by identity: two functions may each
        have an `int a[];`, and only the one that is never bound is the error.
        */
        const unbound = new Set();
        const walkScopes = scope => {
            scope?.symbols?.forEach(sym => {
                if (sym?.isUnboundHandle === true) unbound.add(sym);
            });
            (scope?.children ?? []).forEach(walkScopes);
        };
        walkScopes(this.globalScope);
        if (unbound.size === 0) return;

        /** All bindings seen anywhere, for the never-bound rule. */
        const boundEverywhere = new Set();
        const symbolOf = node => (node && node.type === 'Identifier')
            ? (node.symbol ?? null) : null;
        const isUnboundSymbol = node => {
            const s = symbolOf(node);
            return s?.isUnboundHandle === true ? s : null;
        };
        /*
        Reads are found by a small walker that knows where a name is a READ and
        where it is something else. The modes are:
          - `read`: an ordinary value use (subscript object, right of an `=`, ...);
          - `lvalue`: written, not read (the left of an assignment, `&a`, the
            first argument of `vecalias`) -- an element WRITE such as `a[i] = x`
            is still caught, because the OBJECT of a subscript is read whatever
            the outer mode is;
          - `escape`: a bare name handed to a function, which may be passed on
            unbound and traps at run time instead of failing here.
        The descent is `further`, the one level walk every other analysis uses:
        the sub-nodes of an expression live in NAMED fields (`left`, `right`,
        `test`, `arguments`, ...) and not in `children`, so a walk of `children`
        alone never even sees the arguments of a call -- `print(a[1])` is a BUILTIN
        call, whose arguments are not children at all -- and a read would slip
        through unchallenged.
        In `collect` phase only the bindings are gathered; in `check` phase the
        same walk applies the same-function-before-bind rule against the set the
        collect phase found.
        */
        /*
        The two bindings there are: a plain `a = b;`, and `vecalias(&a, b)`, whose
        first argument is an address rather than a name.
        */
        const boundBy = node => {
            if (node.type === 'AssignmentExpression' && node.operator === '=') {
                return isUnboundSymbol(node.left);
            }
            if (node.type === 'FunctionCall' || node.type === 'BuiltinCall') {
                if ((node.callee?.name ?? node.functionName ?? null) !== 'vecalias') return null;
                const first_ = node.arguments?.[0] ?? null;
                return isUnboundSymbol(first_ && first_.type === 'UnaryExpression'
                    && first_.operator === '&' ? first_.argument : null);
            }
            return null;
        };
        const scan = (node, mode, bound, boundInFunction, phase) => {
            if (!node) return;
            if (node.type === 'Identifier') {
                if (phase === 'check' && mode === 'read') {
                    const sym = isUnboundSymbol(node);
                    if (sym && boundInFunction.has(sym.name) && !bound.has(sym.name)) {
                        this.addError(
                            `Array '${sym.name}' is an unbound handle: it is read before anything `
                            + `bound it here (write '${sym.name} = someArray;' first)`, node.location);
                    }
                }
                return;
            }
            /*
            What a child MEANS is decided by its parent: an assignment writes its
            left side, `&` names one, and a call hands a bare name over rather
            than using it. The rest is an ordinary value use.
            */
            const modeFor = child => {
                if (child === node.callee) return 'callee';
                if (node.type === 'AssignmentExpression' && child === node.left) return 'lvalue';
                if (node.type === 'UnaryExpression' && child === node.argument
                    && node.operator === '&') return 'lvalue';
                if ((node.type === 'FunctionCall' || node.type === 'BuiltinCall')
                    && child === (node.arguments ?? [])[1]
                    && (node.callee?.name ?? node.functionName ?? null) === 'vecalias') {
                    /* the array being bound TO is read here, not handed over */
                    return 'read';
                }
                if ((node.type === 'FunctionCall' || node.type === 'BuiltinCall')
                    && (node.arguments ?? []).includes(child)) return 'escape';
                return 'read';
            };
            this.further(node, child =>
                scan(child, modeFor(child), bound, boundInFunction, phase));
            /*
            A binding counts only after its operands have been read, so the
            right-hand side of `a = a;` is still asked about.
            */
            const bound_ = boundBy(node);
            if (bound_) { bound.add(bound_.name); boundEverywhere.add(bound_); }
        };

        const walk = node => {
            if (!node) return;
            if (node.type === 'FunctionDeclaration') {
                const body = node.body ?? null;
                if (!body) return;
                const collect = new Set();
                scan(body, 'read', collect, collect, 'collect');
                if (collect.size === 0) return;
                const bound = new Set();
                scan(body, 'read', bound, collect, 'check');
                return;
            }
            if (node.type === 'Program') {
                /*
                The parser keeps functions in `program.functions`, not in `children`;
                global declarations have no function to order reads against, so only
                the function bodies are walked.
                */
                (node.functions ?? []).forEach(walk);
                return;
            }
            (node.children ?? []).forEach(walk);
        };
        walk(ast);

        for (const sym of unbound) {
            if (!boundEverywhere.has(sym)) {
                this.addError(
                    `Array '${sym.name}' is an unbound handle that is never bound: write `
                    + `'${sym.name} = someArray;' somewhere before using it`, sym.location);
            }
        }
    }

    /**
     * Turn the notes collected at every call site into one decision per array
     * parameter. Called once, after the whole program has been visited.
     *
     * @param {any} ast
     * @returns {void}
     */
    finalizeArrayParameters(ast) {
        const visitScope = scope => {
            if (!scope) return;
            /*
            The pattern behind `auto` versions: nothing is emitted for it, and
            its parameters hold every call site's notes at once.
            */
            if (scope.astNode?.getAttribute?.('autoTemplate') === true) {
                (scope.children ?? []).forEach(visitScope);
                return;
            }
            for (const symbol of scope.symbols.values()) {
                const notes = symbol.arrayArgumentNotes;
                /*
                A version emitted for one representation already knows it:
                re-deciding from the call-site notes would mix them back
                together, which is exactly what the versions are here to avoid.
                */
                if (symbol.arrayParamRep) continue;
                const declaredRemote = symbol.isRemote === true
                    || this.typeHasRemoteQualifier(symbol.myType?.());
                /*
                `remote int s[4]`: the elements are registers of another
                processor, so this parameter travels as a HANDLE. That has to be
                decided from the declaration alone -- a call through a function
                pointer gives no call-site information at all, yet the callee
                still has to agree on the form the array arrives in.
                */
                if (declaredRemote) {
                    symbol.arrayParamRep = 'handle';
                    if (notes?.traditional) {
                        this.addError(`Parameter '${symbol.name}' is declared 'remote', `
                            + `but is also passed an ordinary array: the elements cannot be `
                            + `in another processor and in memory at the same time`, symbol.location);
                    }
                    continue;
                }
                /*
                `int s[]` leaves its length open, so the callee cannot be handed a
                pointer: nothing in a block and an offset says how many elements
                lie behind the offset, and `lenof` / `sizeof` on such a parameter
                would answer 0. A handle CAN carry it -- it packs the length and
                the element size beside the helpers -- so an array with an open
                dimension always arrives as one, whatever it is given, a memory
                array included (see `ensureArrayHandle`'s `kind: 'memory'` shape).

                Decided from the declaration, like the `remote` case above: the
                parameter has to agree on its form before any call site is known,
                and a call through a function pointer gives no call-site
                information at all.
                */
                if (this.hasOpenDimension(symbol.myType?.())) {
                    symbol.arrayParamRep = 'handle';
                    continue;
                }
                if (!notes) continue;
                if (notes.remote) {
                    symbol.arrayParamRep = 'handle';
                    if (notes.traditional) {
                        this.addError(`Parameter '${symbol.name}' is declared 'remote', `
                            + `but is also passed an ordinary array: the elements cannot be `
                            + `in another processor and in memory at the same time`, symbol.location);
                    }
                } else if (notes.register) {
                    symbol.arrayParamRep = 'handle';
                    if (notes.traditional) {
                        this.addError(`Parameter '${symbol.name}' is passed both an array held in `
                            + `registers and an ordinary in-memory array; they have no layout in common`,
                            symbol.location);
                    }
                } else {
                    symbol.arrayParamRep = 'traditional';
                }
            }
            (scope.children ?? []).forEach(visitScope);
        };
        visitScope(this.globalScope);
    }

    /**
     * Give every array symbol the layout it will use, while the facts behind
     * it are still the only thing consulted (`arrayStyleFor`), so the
     * generator reads one settled choice instead of re-deriving it.
     *
     * The traversal mirrors `finalizeArrayParameters`: an `auto` template is
     * never emitted -- its expanded children are -- so only the children have
     * representations of their own.
     *
     * @returns {void}
     */
    finalizeArrayStyles() {
        const visitScope = scope => {
            if (!scope) return;
            if (scope.astNode?.getAttribute?.('autoTemplate') === true) {
                (scope.children ?? []).forEach(visitScope);
                return;
            }
            for (const symbol of scope.symbols.values()) {
                if (symbol.myType?.()?.kind !== 'array') continue;
                this.arrayStyleFor(symbol);
            }
            (scope.children ?? []).forEach(visitScope);
        };
        visitScope(this.globalScope);
    }

    /**
     * Reject everything that only function overloading could support.
     *
     * @param {any} node A function declaration
     * @returns {void}
     */
    checkOverloading(node) {
        const mode = this.compiler?.overloadMode ?? null;
        const hasAuto = (node.parameters ?? []).some(param => this.hasAutoQualifier(param));
        if (hasAuto && mode === 'none') {
            this.addError(`An 'auto' parameter needs function overloading, which is turned off `
                + `by '#pragma overload(none)'`, node.location ?? null);
        }
        /* Whether two functions may share a name is decided in
           `prescanFunctionDeclarations`; `auto` versions are emitted in
           `expandAutoTemplates`. */
    }

    /**
     * Narrow an overload set by ARGUMENT COUNT, before the arguments are visited.
     *
     * `resolveOverloadedCall` chooses by type, and it needs the arguments visited
     * to know their types -- but visiting an argument needs a parameter list to
     * take its `givenType` from. Neither can go first. The count is the one fact
     * available from the syntax alone, so it goes first: when it narrows the set
     * to exactly one candidate, the arguments can be visited against a parameter
     * list of the right length, and the type-based choice still runs afterwards to
     * settle anything the count could not.
     *
     * Without this, a call carrying MORE arguments than the parameter list the
     * name lookup happened to find reads `expectedParams[index].type` out of
     * bounds. A name lookup can only find one of the versions -- the others were
     * renamed `name__ov1`, `name__ov2` by `prescanFunctionDeclarations` -- so
     * `add(1, 2, 3)` was measured against the 2-parameter `add` and threw
     * `Cannot read properties of undefined` before anything could be reported.
     *
     * Returns the entry only when the count decides it. Zero or several
     * candidates matching is not an answer, and guessing would pick a version the
     * types may not want.
     *
     * @param {any} node A FunctionCall
     * @returns {{node: any, paramTypes: string[]}|null}
     */
    preselectOverloadByArity(node) {
        if (node?.callee?.type !== 'Identifier') return null;
        if (node.callee.getAttribute?.('overloadResolved') === true) return null;
        const set = this.overloadSets?.get(String(node.callee.name ?? '')) ?? null;
        if (!set || set.length <= 1) return null;
        const arity = (node.arguments ?? []).length;
        const matching = set.filter(entry => entry.paramTypes.length === arity);
        return matching.length === 1 ? matching[0] : null;
    }

    /**
     * Pick which of several functions sharing a name this call means.
     *
     * Called after the arguments have been visited (their types are needed)
     * and rewrites `node.callee.name` to the chosen function's emitted name, so
     * that everything downstream -- the generator, the optimizer, the inliner --
     * sees one ordinary function, as before.
     *
     * @param {any} node A FunctionCall
     * @returns {void}
     */
    resolveOverloadedCall(node) {
        if (node?.callee?.type !== 'Identifier') return;
        if (node.callee.getAttribute?.('overloadResolved') === true) return;
        const name = String(node.callee.name ?? '');
        const set = this.overloadSets?.get(name) ?? null;
        if (!set || set.length <= 1) return;
        const argTypes = (node.arguments ?? []).map(arg => this.getExpressionType(arg));
        const score = entry => {
            if (entry.paramTypes.length !== argTypes.length) return -1;
            let total = 0;
            for (let i = 0; i < argTypes.length; i++) {
                const want = entry.paramTypes[i];
                const got = argTypes[i];
                if (!got) continue;
                if (String(got.name ?? got) === String(want)) continue;
                if (node.arguments?.[i]?.type === 'StringLiteral') {
                    const wantType = (typeof want === 'string') ? this.getTypeInfo(want) : want;
                    if (this.isConstCharPointer(wantType)) { total += 1; continue; }
                }
                if (this.isTypeCompatible(want, got)) { total += 1; continue; }
                return -1;
            }
            return total;
        };
        let best = null;
        let bestScore = -1;
        for (const entry of set) {
            const got = score(entry);
            if (got < 0) continue;
            if (best === null || got < bestScore) { best = entry; bestScore = got; }
        }
        if (!best) {
            this.addError(`No version of '${name}' accepts these arguments`
                + ` (${argTypes.map(t => String(t?.name ?? t)).join(', ')})`, node.location);
            return;
        }
        if (String(best.node.name) === name) return;
        node.callee.name = best.node.name;
        const symbol = this.currentScope?.lookup?.(best.node.name) ?? null;
        if (symbol) node.callee.symbol = symbol;
    }

    visitFunctionCall(node) {
		/*
		`remote` is a binding form, not a function: it names another
		processor's variable, and is only meaningful as the initializer of a
		`remote`-qualified declaration. `consumeRemoteDirective` detaches that
		initializer before the expression is ever visited, so a `remote(...)`
		that REACHES here is being used as a value -- and the machine language
		has no instruction that yields one.

		It used to reach the walk below and read past the end of a parameter
		list that does not exist (`remote` is a vararg builtin with none),
		crashing with an empty error list (docs/OPEN_WORK.md 6). Refusing it
		early is also the only safe answer: typing it `void*` (its declared
		return) would let `m = remote(...)` through whenever the target accepts
		`void*` -- `void *m`, an array, or a struct pointer -- and the generator
		has no code for it, emitting `{not_implemented}`.
		*/
		if (node.callee && node.callee.type === 'Identifier' && node.callee.name === 'remote') {
			(node.arguments ?? []).forEach(arg => this.visit(arg));
			this.addError(`remote() is a binding form, not a value: write it as the `
				+ `initializer of a 'remote'-qualified declaration`, node.location);
			return;
		}
		if (node.callee && node.callee.type === 'Identifier' && node.callee.name === 'byname') {
			// Keep it a call: the generator turns it into the address.
			this.visit(node.arguments?.[0] ?? null);
			this.consumeByNameCall(node);
			return;
		}
		if (this.foldCompileTimeFunction(node)) return;
        this.visit(node.callee);

        // 检查参数
		/**
		 * @type {SymbolEntry?}
		 */
		let funcSymbol = null;
		/**
		 * @type {TypeInfo}
		 */
		let funcType = null;
		let readableFunctionName = "<unknown function>";
		if (node.callee.type === 'Identifier') {
			funcSymbol = this.currentScope.lookup(node.callee.name);
			funcType = funcSymbol.myType();
			readableFunctionName = funcSymbol.name;
		} else if (node.callee.dataType) {
			funcType = node.callee.dataType;
			readableFunctionName = funcType.toString();
		} else {
			this.addError(`Cannot resolve function`, node.callee.location);
			return;
		}
		
		let expectedParams = funcType.parameters || [], isFunctionPointer = false;
        if (funcSymbol && (funcSymbol.kind !== 'function' && 
			(!funcSymbol.type.type || funcSymbol.type.type.kind !== 'function'))) {
            this.addError(`Undeclared function '${node.callee.name}'`, node.callee.location);
            return;
        }
		if (!funcSymbol && funcType.kind !== 'function') {
			this.addError(`Object of type '${funcType.toString()}' is not callable`);
			return;
		}

		if ((funcSymbol && funcSymbol.kind !== 'function' && funcSymbol.type.type.kind === 'function')
			|| (!funcSymbol)) {
			expectedParams = funcType.functionTo.type.parameters;
			isFunctionPointer = true;
		}

		/*
		Decide the overload by argument count FIRST, so the loop below has a
		parameter list of the right length to read `givenType` out of. See
		`preselectOverloadByArity` for why the count has to go before the types.
		*/
		const byArity = this.preselectOverloadByArity(node);
		if (byArity) {
			const picked = this.currentScope?.lookup?.(byArity.node.name) ?? null;
			if (picked && picked.kind === 'function') {
				funcSymbol = picked;
				funcType = picked.myType();
				readableFunctionName = picked.name;
				expectedParams = funcType.parameters || [];
			}
			node.callee.name = byArity.node.name;
			if (picked) node.callee.symbol = picked;
			node.callee.setAttribute('overloadResolved', true);
		}

		/*
		`index < expectedParams.length` is not decoration. The parameter list can
		still be the wrong length here -- no overload set, or a count that matched
		zero or several versions -- and the count check below comes too late to
		stop the read. Such an argument is visited with no `givenType` (both
		consumers guard for it), so the count check is what reports the mistake,
		instead of a TypeError thrown before any diagnostic exists.
		*/
        node.arguments.forEach((arg, index) => this.visit(arg, {
			givenType: index < expectedParams.length
				? this.getTypeInfo(expectedParams[index].type)
				: null,
			givenTypeUnsure: true
		}));

		/*
		The count may have decided it already, in which case the callee is no
		longer the shared name and there is nothing left to choose. Otherwise the
		argument types are known now, so the right overload can be chosen, and
		everything below then works on that one.
		*/
		this.resolveOverloadedCall(node);
		if (node.callee.type === 'Identifier') {
			const chosen = this.currentScope?.lookup?.(node.callee.name) ?? null;
			if (chosen && chosen.kind === 'function') {
				funcSymbol = chosen;
				funcType = chosen.myType();
				readableFunctionName = chosen.name;
				expectedParams = funcType.parameters || [];
			}
		}
		if (funcSymbol) funcSymbol.called = true;

		/*
		A literal may satisfy a `const char*` parameter by materialising a
		read-only char array. This happens after overload resolution, so a
		`string_t` overload still wins when one exists.
		*/
		node.arguments.forEach((arg, index) => {
			if (index >= expectedParams.length || arg?.type !== 'StringLiteral') return;
			const raw = expectedParams[index].type;
			const want = (typeof raw === 'string') ? this.getTypeInfo(raw) : raw;
			if (!this.isConstCharPointer(want)) return;
			const reference = this.coerceStringLiteralToCharPointer(arg, want, node);
			node.arguments[index] = reference;
			this.visit(reference, { givenType: want, givenTypeUnsure: true });
		});

        // 检查参数数量
        /*
        A name shared by several versions is not one function with one
        parameter count. The count belongs to whichever version is chosen,
        and the choice has already been reported above, naming every version
        it tried against. Quoting one version's count here as well would name
        a version the call was never matched against: `add(1, 2, 3, 4)` was
        told it wanted 2 arguments, because 2 is how many the FIRST `add`
        takes, and saying so next to the accurate message reads as a second
        finding about the same call.
        */
        const shared = node.callee.type === 'Identifier'
            && (this.overloadSets?.get(String(node.callee.name))?.length ?? 0) > 1;
        if (!shared && node.arguments.length !== expectedParams.length) {
            this.addError(
                `Function '${readableFunctionName}' expects ${expectedParams.length} arguments, but ${node.arguments.length} were provided`,
                node.location
            );
            return;
        }

        // 检查参数类型
        node.arguments.forEach((arg, index) => {
            const argType = this.getExpressionType(arg);
            /*
            A parameter list shorter than the argument list can still reach this
            loop. `resolveOverloadedCall` reports it when no version of a shared
            name takes these arguments, and the `shared` flag below suppresses
            the count check as well -- so nothing returns, and an out-of-range
            read here is what a TypeError looks like.

            The loop above guards the same index for the same reason. By this
            point the diagnostics for this call are already written; what is
            left needs a parameter to do anything with, so the argument that has
            none is simply left alone.
            */
            if (index >= expectedParams.length) return;
            const expectedType = expectedParams[index].type;
            
            /*
            A POINTER to a template struct and a pointer to the struct it
            spells out are the same question one level down: compare what they
            point at.
            */
            const peelVariant = (a, e) => {
                const ra = (typeof a === 'string') ? this.getTypeInfo(a) : a;
                const re = (typeof e === 'string') ? this.getTypeInfo(e) : e;
                if (!ra || !re) return false;
                if (ra.kind === 'pointer' && re.kind === 'pointer') {
                    return this.isStructVariantOf(ra.pointerTo, re.pointerTo);
                }
                return this.isStructVariantOf(ra, re);
            };
            const compatible = (node.callee.name === 'sensor' && index === 0
                    && ['string_t', 'null_t'].includes(argType?.name))
                || this.isTypeCompatible(expectedType, argType)
                || peelVariant(argType, expectedType);
            if (argType && expectedType && !compatible) {
                this.addError(
                    `Argument ${index + 1} of '${node.callee.name}' expects '${expectedType}', but got '${argType}'`,
                    arg.location
                );
            }
            /*
            A struct that is still a pattern was accepted by name and shape
            alone. Whether its chosen representation really matches is only
            known once every store into it has been seen, so the check is left
            for then.
            */
            if (argType && expectedType && peelVariant(argType, expectedType)) {
                const raw = (typeof argType === 'string') ? this.getTypeInfo(argType) : argType;
                const inner = raw?.kind === 'pointer' ? raw.pointerTo : raw;
                /*
                Nothing to check when the parameter is the TEMPLATE itself: the
                argument settles on a variant, and the variant keeps the name.
                */
                /*
                Only a TEMPLATE that is NOT the parameter's own type has
                anything left to decide:
                  - a plain struct was checked in full above;
                  - a parameter that is itself the pattern is replaced by a
                    variant once the call sites are known, so comparing the
                    argument against the undecided pattern would reject every
                    one of them.
                */
                const expectedInner = (() => {
                    const rawE = (typeof expectedType === 'string')
                        ? this.getTypeInfo(expectedType) : expectedType;
                    const innerE = rawE?.kind === 'pointer' ? rawE.pointerTo : rawE;
                    return this.canonicalStructType(innerE);
                })();
                if (this.canonicalStructType(inner)?.isTemplate === true
                    && expectedInner?.isTemplate !== true) {
                this.pendingStructConversions = this.pendingStructConversions ?? [];
                    const rawExpected = (typeof expectedType === 'string')
                        ? this.getTypeInfo(expectedType) : expectedType;
                    const innerExpected = rawExpected?.kind === 'pointer'
                        ? rawExpected.pointerTo : rawExpected;
                    this.pendingStructConversions.push({
                        name: arg?.type === 'Identifier' ? arg.name
                            : (arg?.argument?.type === 'Identifier' ? arg.argument.name : null),
                        expected: innerExpected?.name ?? null,
                        location: arg.location ?? null
                    });
                }
            }
            /*
            An array argument is NOT decayed into a pointer, so its dimensions
            stay part of the contract: every dimension the parameter names has
            to be at least as large as what is handed over. `void f(int p[])`
            names nothing and therefore accepts anything.
            */
            this.checkArrayArgumentDimensions(readableFunctionName, expectedParams[index], arg, index);
        });
        /*
        An array keeps its own layout when it is passed, so the parameter has to
        be told which layout it will be given -- see `finalizeArrayParameters`.
        */
        this.noteArrayArguments(node, funcSymbol, expectedParams);

		if (isFunctionPointer) {
			node.dataType = this.getTypeInfo(funcSymbol ?
					funcSymbol.type.type.functionTo.type.returnType : funcType.functionTo.type.returnType);
		} else {
			node.dataType = this.getTypeInfo(funcSymbol.type.returnType);
		}
		node.setAttribute('isFunctionPointer', isFunctionPointer);
    }

    /**
     * `(volatile T*)x` used to be an output-parameter spelling. It is removed
     * in favour of `&x`; reject it here instead of letting the generator treat
     * the cast as a pointer value.
     *
     * @param {BuiltinCallNode} node
     * @returns {void}
     */
    rejectRemovedOutputPointerCasts(node) {
        const name = node.functionName;
        const symbol = this.currentScope.lookup(name);
        const outputIndices = (name === 'ulocate' || name === 'ucontrol')
            ? (node.arguments ?? []).map((_, index) => index).slice(1)
            : (symbol?.type?.nominalPointers ?? []);
        for (const index of outputIndices) {
            const arg = node.arguments?.[index];
            if (arg?.type !== 'CastExpression') continue;
            const typeNode = arg.typeNode ?? null;
            const qualifiers = [
                ...(typeNode?.getAttribute?.('qualifiers') ?? []),
                ...(arg.dataType?.qualifiers ?? [])
            ];
            const pointerDepth = typeNode?.pointerDepth ?? arg.dataType?.pointerDepth ?? 0;
            if (pointerDepth > 0 && qualifiers.includes('volatile')) {
                this.addError(`(volatile T*) output parameters were removed; use '&x' instead`,
                    arg.location ?? node.location);
            }
        }
    }

    visitBuiltinCall(node) {
		const funcSymbol = this.currentScope.lookup(node.functionName);
		if (!funcSymbol || funcSymbol.kind !== 'function') {
			this.addError(`Unknown builtin function '${node.functionName}'`, node.location);
			return;
		}

		// `byname(&c)`: handled here, because the parser makes it a builtin call
		if (node.functionName === 'byname') {
			node.arguments.forEach(arg => this.visit(arg));
			this.consumeByNameCall(node);
			return;
		}

		// 检查参数
		node.arguments.forEach(arg => this.visit(arg));
		this.rejectRemovedOutputPointerCasts(node);

		// 特殊的内建函数参数检查
		switch (node.functionName) {
			case 'printchar':
			case 'format':
				if (this.targetVersion < 150) {
					this.addError(`${node.functionName} requires v150 or higher`, node.location);
				}
				break;
			case 'set':
				if (node.arguments.length < 2) {
					this.addError(`'set' requires at least 2 arguments`, node.location);
				}
				break;
				
			case 'op':
				if (node.arguments.length < 3) {
					this.addError(`'op' requires at least 3 arguments`, node.location);
				}
				break;
				
			case 'read':
				if (node.arguments.length !== 2) {
					this.addError(`'${node.functionName}' requires exactly 2 arguments`, node.location);
				} else if (!node.arguments[0].dataType
					|| !['device', 'null_t', 'string_t'].includes(String(node.arguments[0].dataType.name))) {
					this.addError(`The building of '${node.functionName}' should be a device`, node.location);
				}
				if (node.arguments[0]?.dataType?.name === 'string_t' && this.targetVersion < 150) {
					this.addError(`Reading a string by index requires v150 or higher`, node.location);
				}
				break;
				
			case 'write':
				if (node.arguments.length !== 3) {
					this.addError(`'${node.functionName}' requires exactly 3 arguments`, node.location);
				} else if (!node.arguments[1].dataType
					|| !['device', 'null_t'].includes(String(node.arguments[1].dataType.name))) {
					this.addError(`The building of '${node.functionName}' should be a device`, node.location);
				}
				break;

			case 'stricteq':
				if (node.arguments.length !== 2) {
					this.addError(`'${node.functionName}' requires exactly 2 arguments`, node.location);
				}
				break;

			/*
			`vecalias` / `veccpy`: the arity and the argument layouts are the whole
			of what can be checked here, and both are questions about how an array
			is STORED rather than about a type name -- which is why they get their
			own checks instead of the parameter count in `default`.
			*/
			case 'vecalias':
				this.checkVecAlias(node);
				break;
			case 'veccpy':
				this.checkVecCpy(node);
				break;
				
			default:
				// I don't actually know what this is for...
				if (!funcSymbol.type.hasVarArgs) {
					const expectedParams = funcSymbol.type.parameters || [];
					if (node.arguments.length !== expectedParams.length) {
						this.addError(
							`Function '${node.functionName}' expects ${expectedParams.length} arguments, but ${node.arguments.length} were provided`,
							node.location
						);
					}
				}
				break;
		}

		node.dataType = funcSymbol.type.returnTypeEval ?
			funcSymbol.type.returnTypeEval(node)
			 : this.getTypeInfo(funcSymbol.type.returnType);
	}

	// !! Has manual changes !!
    visitIfStatement(node) {
        this.visit(node.test);
        
        // 检查条件表达式类型
        const testType = this.getExpressionType(node.test);
        if (testType && testType.name !== 'bool') {
            this.addWarning(`Condition expression should be of type 'bool'`, node.test.location);
        }

        this.visit(node.consequent);
        if (node.alternate) {
            this.visit(node.alternate);
        }
    }

	/**
	 * 
	 * @param {ConditionalExpressionNode} node 
	 * @remark Manually written. How could AI forget this?
	 */
	visitConditionalExpression(node) {
		this.visit(node.test);
		const testType = this.getExpressionType(node.test);
		if (testType && testType.name !== 'bool') {
            this.addWarning(`Condition expression should be of type 'bool'`, node.test.location);
        }
		this.visit(node.consequent);
		this.visit(node.alternate);
		const consequentType = this.getExpressionType(node.consequent);
		const alternateType = this.getExpressionType(node.alternate);
		if (!this.isTypeCompatible(consequentType, alternateType)) {
			this.addError(`Conditional expression must return the same type`, node.consequent.location);
		}
		node.dataType = consequentType;
	}

    /**
     * Visit a loop body with the break/continue context it provides.
     * `break` needs a loop or a switch; `continue` needs a loop.
     */
    visitLoopBody(body) {
        this.loopDepth += 1;
        this.breakableDepth += 1;
        try {
            if (body) this.visit(body);
        } finally {
            this.loopDepth -= 1;
            this.breakableDepth -= 1;
        }
    }

    visitBreakStatement(node) {
        if (this.breakableDepth === 0) {
            this.addError(`'break' can only be used inside a loop or switch`, node.location);
        }
    }

    visitContinueStatement(node) {
        if (this.loopDepth === 0) {
            this.addError(`'continue' can only be used inside a loop`, node.location);
        }
    }

    visitSwitchStatement(node) {
        this.visit(node.discriminant);
        const discType = this.getExpressionType(node.discriminant);
        const integerLike = discType && (this.isIntegerType(discType.name)
            || discType.name === 'char' || discType.name === 'bool');
        if (!integerLike) {
            this.addError(`A switch needs an integer value, but '${discType?.name ?? 'unknown'}' is not one`,
                node.discriminant?.location ?? node.location);
        }

        /*
        Case values are checked here, on the flat body list. `default` is a
        marker with no test. A `const int` variable is NOT a C integer constant
        expression, so the evaluator deliberately rejects identifiers.
        */
        const seen = new Set();
        let hasDefault = false;
        for (const stmt of node.body?.statements ?? []) {
            if (stmt.type !== 'CaseClause') continue;
            if (!stmt.test) {
                if (hasDefault) this.addError(`Duplicate 'default' in switch`, stmt.location ?? node.location);
                hasDefault = true;
                continue;
            }
            const value = this.constantCaseValue(stmt.test);
            if (value === undefined) {
                this.addError(`A case label must be a compile-time integer constant`,
                    stmt.test.location ?? stmt.location ?? node.location);
                continue;
            }
            /* An ATTRIBUTE, so `cloneAST` keeps it when a function is inlined. */
            stmt.setAttribute('caseValue', value);
            if (seen.has(value)) {
                this.addError(`Duplicate case value ${value} in switch`, stmt.location ?? node.location);
            }
            seen.add(value);
        }

        /*
        The whole switch body is one breakable context: `break` leaves the
        switch, while `continue` still belongs to the enclosing loop (so only
        `breakableDepth` moves, not `loopDepth`).
        */
        this.breakableDepth += 1;
        try {
            if (node.body) this.visit(node.body);
        } finally {
            this.breakableDepth -= 1;
        }
    }

    visitCaseClause(node) {
        if (node.test) this.visit(node.test);
    }

    /**
     * Value of a C integer constant expression, or `undefined`.
     * @param {any} node
     * @returns {number|undefined}
     */
    constantCaseValue(node) {
        if (!node) return undefined;
        switch (node.type) {
            case 'NumericLiteral':
                return Number.isFinite(Number(node.value)) ? Number(node.value) : undefined;
            case 'CharacterLiteral':
                return (node.value ?? '').codePointAt(0) ?? 0;
            case 'Identifier': {
                const symbol = this.currentScope.lookup(node.name);
                return symbol?.isEnumConstant === true
                    ? Number(symbol.constantValue) : undefined;
            }
            case 'UnaryExpression': {
                const v = this.constantCaseValue(node.argument);
                if (v === undefined) return undefined;
                switch (node.operator) {
                    case '+': return v;
                    case '-': return -v;
                    case '~': return ~v;
                    case '!': return v ? 0 : 1;
                    default: return undefined;
                }
            }
            case 'BinaryExpression': {
                const a = this.constantCaseValue(node.left);
                const b = this.constantCaseValue(node.right);
                if (a === undefined || b === undefined) return undefined;
                switch (node.operator) {
                    case '+': return a + b;
                    case '-': return a - b;
                    case '*': return a * b;
                    case '/': return b === 0 ? undefined : Math.trunc(a / b);
                    case '%': return b === 0 ? undefined : a % b;
                    case '&': return a & b;
                    case '|': return a | b;
                    case '^': return a ^ b;
                    case '<<': return a << b;
                    case '>>': return a >> b;
                    default: return undefined;
                }
            }
            default: return undefined;
        }
    }

    visitWhileStatement(node) {
        this.visit(node.test);
        
        // 检查条件表达式类型
        const testType = this.getExpressionType(node.test);
        if (testType && testType.name !== 'bool') {
            this.addWarning(`Loop condition should be of type 'bool'`, node.test.location);
        }

        this.visitLoopBody(node.body);
    }

    visitDoWhileStatement(node) {
        this.visitLoopBody(node.body);
        this.visit(node.test);
        const testType = this.getExpressionType(node.test);
        if (testType && testType.name !== 'bool') {
            this.addWarning(`Loop condition should be of type 'bool'`, node.test.location);
        }
    }

	// FOR LOOP DOESN'T HAVE ITS SCOPE
    visitForStatement(node) {
        // 进入新的作用域
        //const forScope = new Scope(this.currentScope, 'block');
        //this.currentScope.children.push(forScope);
        //this.currentScope = forScope;

        if (node.init) this.visit(node.init);
        if (node.test) {
            this.visit(node.test);
            const testType = this.getExpressionType(node.test);
            if (testType && testType.name !== 'bool') {
                this.addWarning(`Loop condition should be of type 'bool'`, node.test.location);
            }
        }
        if (node.update) this.visit(node.update);
        this.visitLoopBody(node.body);

        // 退出作用域
        //this.currentScope = this.currentScope.parent;
    }

    visitReturnStatement(node) {
        if (node.argument) {
			if (this.currentFunction) {
                const returnType = this.currentFunction.type.returnType;
				const returnTypeInfo = this.getTypeInfo(returnType);
				/*
				A function's return type is stored as text and may have lost the
				`const` qualifier on the pointee. Returning a literal still
				materialises it as a read-only array; the pointer cannot write
				through the array's declared constness either way.
				*/
				const returnsCharPointer = /\bchar\s*\*$/.test(String(returnType));
				if (node.argument.type === 'StringLiteral'
					&& (this.isConstCharPointer(returnTypeInfo) || returnsCharPointer)) {
					node.argument = this.coerceStringLiteralToCharPointer(
						node.argument, returnTypeInfo, node, returnsCharPointer);
				}
                const argType = this.getExpressionType(node.argument);
                
                if (returnType !== 'void' && argType && !this.isTypeCompatible(returnType, argType)) {
                    this.addError(
                        `Return type mismatch: expected '${returnType}', but got '${argType}'`,
                        node.argument.location
                    );
                }

				node.dataType = this.getTypeInfo(returnType);
            }

            this.visit(node.argument, {
				givenType: node.dataType
			});
            
        } else if (this.currentFunction && this.currentFunction.type.returnType !== 'void') {
            this.addError(`Function must return a value`, node.location);
        } else {
			node.dataType = this.getTypeInfo('void');
		}
    }

    visitCompoundStatement(node) {
        // 进入新的块作用域
        let blockScope = node.scope;
		if (!blockScope) {
			node.scope = blockScope = new Scope(this.currentScope, 'b');
			this.currentScope.children.push(blockScope);
		}
        this.currentScope = blockScope;

        // 遍历块内的所有语句
        node.statements.forEach(stmt => this.visit(stmt));
		/*
		A block-scope prototype has done its job during semantic analysis.
		Keeping it in the statement list makes the optimizer treat it as a
		function with no body.
		*/
		node.statements = node.statements.filter(
			stmt => !(stmt?.type === 'FunctionDeclaration' && !stmt.body));

        // 退出作用域
        this.currentScope = this.currentScope.parent;
    }

	/**
	 * 
	 * @param {InitializerListNode} node 
	 * @param {{ givenSymbol: SymbolEntry?, givenType: TypeInfo }?} param 
	 */
	visitInitializerList(node, param) {
		const declaratorTypes = ['VariableDeclarator', 'Declarator'];
		node.dataType = this.typeTable.get('null_t').duplicate();	// size might be modified
		node.dataType.size = 0;
		let index = 0;
		node.children.forEach(child => {
			let further = undefined;
			if (param && param.givenType) {
				further = {
					givenType: param.givenType.extractKth(index)
				};
			}
			this.visit(child, further);
			node.dataType.size += child.dataType ? child.dataType.size : 0;
			index++;
		});
		node.setAttribute('requiredSize', node.dataType.size);
		// Assign a virtual symbol for it
		// if (!node.parent || (node.parent.type !== 'InitializerList'
			//  && (!declaratorTypes.includes(node.parent.type) || !node.parent.symbol))) {
		let requireMemory = true;
		if (param && param.givenType) {
			node.dataType = param.givenType;
			requireMemory = param.givenType.isPointerImpl();
		}
		if (!(param && param.givenSymbol)) {
			const virtualSymbol = new SymbolEntry(
			`__initializer_${this.virtualCounter++}`, node.dataType, this.currentScope, requireMemory ? 'array' : 'struct', null, node.dataType.size);
			virtualSymbol.isConst = true;
			virtualSymbol.isVolatile = requireMemory;
			//virtualSymbol.accessThroughPointer = true;
			virtualSymbol.implementAsPointer = requireMemory;
			virtualSymbol.needMemoryAllocation = requireMemory;
			virtualSymbol.isVirtualSymbol = true;
			virtualSymbol.isStatic = true;
			node.symbol = virtualSymbol;
			this.currentScope.addSymbol(virtualSymbol);
		} else {
			node.symbol = param.givenSymbol;
		}
	}

    // =============== 类型检查辅助方法 ===============
	/**
	 * @param {ASTNode} node 
	 * @returns {TypeInfo | null}
	 */
	getExpressionType(node) {
        if (!node) return null;

        // 如果节点已经有数据类型，直接返回
        if (node.dataType) {
            return node.dataType;
			//return this.typeTable.get(node.dataType) ?? node.dataType;
        }

        // 根据节点类型推断类型
        switch (node.type) {
			case 'ConditionalExpression':
				return this.getExpressionType(node.consequent);

            case 'Identifier':
                const symbol = this.currentScope.lookup(node.name);
				if (!symbol) {
					return null;
				}
				if (symbol.kind === 'function') {
					let funcType = new TypeInfo(node.name, 'function');
					funcType.functionTo = symbol;
					return funcType;
				}
                return symbol.myType();

            case 'MemberExpression':
                return node.dataType;

            case 'UnaryExpression':
                if (node.operator === '*') {
                    // 解引用操作
                    const argType = this.getExpressionType(node.argument);
                    if (argType && argType.kind === 'pointer') {
                        return argType.pointerTo;
                    }
                    return null;
                } else if (node.operator === '&') {
                    // 取地址操作
                    const argType = this.getExpressionType(node.argument);
                    if (argType) {
                        const ptrType = new TypeInfo('', 'pointer', 2);
                        ptrType.pointerTo = argType;
                        return ptrType;
                    }
                    return null;
                }
                // 其他一元操作符
				/*
				// 其他一元操作符
				const argType = this.getExpressionType(node.argument);
				if (argType) {
					// 对于递增递减操作，返回与参数相同的类型
					if (node.operator === '++' || node.operator === '--') {
						return argType;
					}
					// 对于其他一元操作符，返回数值类型
					return this.typeTable.get('int');
				}
				return null;
				*/
                return this.getExpressionType(node.argument);

            case 'BinaryExpression':
                // 对于指针算术等操作，需要特殊处理
                const leftType = this.getExpressionType(node.left);
                const rightType = this.getExpressionType(node.right);
                
                if (node.operator === '+' || node.operator === '-') {
                    // 指针算术
                    if (leftType && leftType.kind === 'pointer') {
                        return leftType;
                    }
                    if (rightType && rightType.kind === 'pointer') {
                        return rightType;
                    }
                }
                
				if (node.operator === '/') {
					if (this.isNumericType(leftType) && this.isNumericType(rightType)) {
						return this.getTypeInfo('double');
					}
				}

				if (['||', '&&', '>=', '<=', '>', '<', '==', '!='].includes(node.operator)) {
					return this.getTypeInfo('bool');
				}

                // 默认返回左操作数类型
                return leftType;
				
			case 'AssignmentExpression':
				// 赋值表达式的类型是左操作数的类型
				return this.getExpressionType(node.left);
			
			case 'CastExpression':
				// 类型转换表达式的类型是转换后的类型
				if (node.typeNode) {
					const typeNode = node.typeNode;
					const typeName = this.getTypeNameFromTypeNode(typeNode);
					let baseType = this.getTypeInfo(typeName);
					
					return baseType;
				}
				return null;

            case 'NumericLiteral':
                return this.typeTable.get('int');

            case 'StringLiteral':
                return this.typeTable.get('string_t');

            case 'CharacterLiteral':
                return this.typeTable.get('int');

			case 'InitializerList':
            case 'NullLiteral':
                return this.typeTable.get('null_t');

            default:
                return null;
        }
    }

	// Currently unused
	isValidMemberAccessOperator(operator) {
		return operator === '.' || operator === '->';
	}

	/**
	 * 
	 * @param {TypeInfo} targetTypeRaw
	 * @param {TypeInfo} sourceTypeRaw
	 */
	isSameType(targetTypeRaw, sourceTypeRaw) {
		const targetType = targetTypeRaw.duplicate(), sourceType = sourceTypeRaw.duplicate();
		/*
		This comparison exists for the template-struct variant check: a pattern
		member `auto int *p` and a variant member `int *byname p` are the same
		SHAPE -- the representation is spelled out by the variant, not by the
		type string (it is read back off `namePointer` / the array implementation
		later). Storage and representation qualifiers therefore have to come off
		EVERY level, not just the top one: the program may have written them in
		front of the base (`auto int`) or behind a `*` (`int *byname`), and the
		older, lossier parsing used to make both read the same -- which is what
		made the two spellings match here.
		*/
		const ignoredQualifiers = ['auto', 'static', 'persistent', 'extern', 'near', 'register', 'byname', 'byvaluename', 'volatile'];
		const strip = t => {
			let head = t;
			while (head) {
				head.qualifiers = head.qualifiers.filter(item => !ignoredQualifiers.includes(item));
				head = head.pointerTo ?? null;
			}
		};
		strip(sourceType); strip(targetType);
		// 'const' of the source does not matter (kept on the target only)
		sourceType.qualifiers = sourceType.qualifiers.filter(item => item !== 'const');
		return this.typeToString(sourceType) == this.typeToString(targetType);
	}

    // 修改类型兼容性检查以支持指针和结构体
	/**
	 * 
	 * @param {TypeInfo | string} targetTypeRaw 
	 * @param {TypeInfo | string} sourceTypeRaw 
	 * @param {boolean} [strictCompatible=false] Whether allowing no cast
	 * @returns 
	 */
    isTypeCompatible(targetTypeRaw, sourceTypeRaw, strictCompatible = false) {
		
		/**
		 * @type {TypeInfo}
		 */
		let targetType = targetTypeRaw;
		/**
		 * @type {TypeInfo}
		 */
		let sourceType = sourceTypeRaw;
		// TODO: Might be sth like '*'
		if (typeof targetType === 'string') {
			targetType = this.getTypeInfo(targetType);
		}
		if (typeof sourceType === 'string') {
			sourceType = this.getTypeInfo(sourceType);
		}
		/*
		A type name that resolves to nothing is a type nobody wrote: an
		unreadable qualifier, or a typedef that is not in scope yet. There is
		nothing to compare it against, so it is simply not compatible -- and the
		check has to come BEFORE any field of either side is read, or refusing the
		program is a crash instead of a message. (The `qualifiers` de-duplication
		this used to do here is already inside `duplicate()`, and doing it on the
		originals rewrote the caller's type.)
		*/
		if (!targetType || !sourceType) return false;

		targetType = targetType.duplicate();
		sourceType = sourceType.duplicate();
        
		// Remove auto and volatile qualifier for both sides:
		const ignoredQualifiers = ['auto', 'volatile', 'static', 'persistent', 'extern', 'near'];
		sourceType.qualifiers = sourceType.qualifiers.filter(
			item => (!ignoredQualifiers.includes(item) && (sourceType.isStrictPointerImpl() || item !== 'const')) );	// 'const' of source does not matter
		targetType.qualifiers = targetType.qualifiers.filter(
			item => (!ignoredQualifiers.includes(item) && item !== 'const'));

		const specialContents = ['item_t', 'liquid_t', 'unit_t', 'block_t', 'content_t'];
		
        // 相同类型总是兼容
        if (this.typeToString(targetType) === this.typeToString(sourceType)) {
            return true;
        }
		if (!strictCompatible) {
			if (specialContents.includes(targetType.name) && specialContents.includes(sourceType.name)) {
				/*
				A `@name` nobody declared is `content_t`, but WHICH content is
				unknown, so it may only stay `content_t` unless the programmer
				casts explicitly.
				*/
				const opaque = sourceType.annotations?.getAttribute?.('opaqueContent') === true
					|| sourceType.getAttribute?.('opaqueContent') === true;
				if (opaque && targetType.name !== 'content_t') return false;
				return true;
			}
			// Clear names for checker
			if (targetType.kind === 'function' && sourceType.kind === 'function') {
				const duplicateTarget = targetType.duplicate(), duplicateSource = sourceType.duplicate();
				duplicateTarget.name = "";
				duplicateSource.name = "";
				return this.typeToString(duplicateTarget) === this.typeToString(duplicateSource);
			}
		}
        
        // void指针可以接受任何指针类型
        if (['pointer', 'array'].includes(targetType.kind) && ['pointer', 'array'].includes(sourceType.kind)) {
            if (!strictCompatible) {
				if (targetType.pointerTo && targetType.pointerTo.name === 'void') {
					return true;
				}
				if (sourceType.pointerTo && sourceType.pointerTo.name === 'void') {
					return true;
				}
			}
            // 指针类型兼容性检查
            return this.isTypeCompatible(targetType.extractSingle(), sourceType.extractSingle());
        }
        
        if (!strictCompatible) {
			// 数组到指针的转换
			if (targetType.kind === 'pointer' && sourceType.kind === 'array') {
				return this.isTypeCompatible(targetType.extractSingle(), sourceType.extractSingle());
			}
			// 数值类型之间的兼容性
			const numericTypes = ['int', 'char', 'short', 'long', 'float', 'double', 'signed', 'unsigned', 'bool'];
			if (numericTypes.includes(targetType.name) && numericTypes.includes(sourceType.name)) {
				return true;
			}
		} else {
			const numericGroup = ['int', 'char', 'long', 'short', 'signed', 'unsigned', 'bool'], decimalGroup = ['float', 'double'];
			if (numericGroup.includes(targetType.name) && numericGroup.includes(sourceType.name)) {
				return true;
			}
			if (decimalGroup.includes(targetType.name) && decimalGroup.includes(sourceType.name)) {
				return true;
			}
		}
        
		// TODO: Let's regard this as a feature...
		// null_t can be assigned to everything
		if (!strictCompatible) {
			if (sourceType.name === 'null_t') {
				return true;
			}
			/*
			...and it can hold everything, which is what lets a string view
			keep a string value, a message building or a memory block in one
			cell.
			*/
			if (targetType.name === 'null_t') {
				return true;
			}
		}
        
        // 结构体/联合体类型兼容性
        if (targetType.kind === 'struct' || targetType.kind === 'union') {
            if (sourceType.kind === targetType.kind && targetType.name === sourceType.name) {
                return true;
            }
        }
        
        return false;
    }

	/**
	 * 
	 * @param {TypeInfo | string} targetType 
	 * @param {(TypeInfo | string)[]} sourceTypes 
	 * @param {boolean} [strictCompatible=false] 
	 */
	isTypeCompatibleForAny(targetType, sourceTypes, strictCompatible = false) {
		return sourceTypes.some(type => this.isTypeCompatible(targetType, type, strictCompatible));
	}

	// ! Has manual content !
    isTypeCompatibleForOperator(operator, leftTypeRaw, rightTypeRaw) {
		
		let leftType = leftTypeRaw, rightType = rightTypeRaw;
		// TODO: Might be sth like '*'
		if (typeof leftType === 'string') {
			leftType = this.getTypeInfo(leftType);
		}
		if (typeof rightType === 'string') {
			rightType = this.getTypeInfo(rightType);
		}
		
		if (!leftType || !rightType) return false;
		
        const arithmeticOps = ['+', '-', '*', '/', '%'];
		const pointerOps = ['+', '-'];
        const comparisonOps = ['==', '!=', '<', '<=', '>', '>='];
		const specialComparisonOps = ['==', '!='];
        const logicalOps = ['&&', '||'];
        const bitwiseOps = ['&', '|', '^', '<<', '>>'];
		const pointerCompatible = ['pointer', 'array'];

		// No operator is allowed for struct / union
		// (Manually written)
		if (leftType.kind === 'struct' || leftType.kind === 'union' || leftType.kind === 'function')
			return false;

		if (rightType.kind === 'struct' || rightType.kind === 'union' || rightType.kind === 'function')
			return false;
		// (End)
		
		// (Manually written) (They should BE NAMES)
		// (As well as pointer execution)

        // 算术运算符要求数值类型
        if (arithmeticOps.includes(operator)) {
			const leftIsPointer = pointerCompatible.includes(leftType.kind);
			const rightIsPointer = pointerCompatible.includes(rightType.kind);
			if (leftIsPointer && rightIsPointer) {
				return false;
			}
			if ((leftIsPointer || rightIsPointer) && (!pointerOps.includes(operator))) {
				return false;
			}
            return (this.isNumericType(leftType.name) || leftIsPointer) && (this.isNumericType(rightType.name) || rightIsPointer);
        }

        // 比较运算符要求兼容类型
        if (comparisonOps.includes(operator)) {
			if (pointerCompatible.includes(leftType.kind) && pointerCompatible.includes(rightType.kind)) {
				return this.isTypeCompatible(leftType.pointerTo, rightType.pointerTo);
			}
			if (specialComparisonOps.includes(operator)) {
				return this.isTypeCompatible(leftType, rightType);
			} else {
				return this.isNumericType(leftType.name) && this.isNumericType(rightType.name);
			}
			
        }

        // 逻辑运算符要求布尔上下文（这里简化为int类型）
        if (logicalOps.includes(operator)) {
            return this.isLogicalType(leftType.name) && this.isLogicalType(rightType.name);
        }

        // 位运算符要求整型
        if (bitwiseOps.includes(operator)) {
            return this.isIntegerType(leftType.name) && this.isIntegerType(rightType.name);
        }

        return true; // 其他操作符暂时宽松处理
    }
	
	// 添加类型转字符串方法
    typeToString(typeInfo) {
        if (!typeInfo) return 'unknown';
		if (typeof typeInfo === 'string') {
			return typeInfo;
		}
        
        return typeInfo.toString();
    }

	// Check for LVal beforehand
    isTypeCompatibleForUnaryOperator(operator, argTypeRaw) {
		
		let argType = argTypeRaw;
		if (typeof argType === 'string') {
			argType = this.getTypeInfo(argType);
		}
		
        const arithmeticOps = ['+', '-'];
        const logicalOps = ['!'];
        const bitwiseOps = ['~'];
        const incrementOps = ['++', '--'];

        // 算术一元运算符要求数值类型
        if (arithmeticOps.includes(operator)) {
            return this.isNumericType(argType);
        }

        // 逻辑非要求布尔上下文
        if (logicalOps.includes(operator)) {
            return argType === 'bool';
        }

        // 位非要求整型
        if (bitwiseOps.includes(operator)) {
            return this.isIntegerType(argType);
        }

        // 递增递减要求左值且为数值类型
        if (incrementOps.includes(operator)) {
            return this.isNumericType(argType);
        }
		
		if (operator === '*') {
			return argType.kind === 'pointer';
		}

        return true;
    }

    getResultType(operator, leftType, rightType) {
		const comparisonOps = ['==', '!=', '<', '<=', '>', '>=', '||', '&&'];
		const pointerOps = ['+', '-'];
        // 在实际编译器中需要更精确的类型推导
		if (comparisonOps.includes(operator)) return this.typeTable.get('bool');
		if (pointerOps.includes(operator)) {
			if (leftType.kind === 'pointer') return leftType;
			if (rightType.kind === 'pointer') return rightType;
		}
        return leftType;
    }

    getUnaryResultType(operator, argType) {
        // 一元表达式通常保持操作数类型
		
		if (operator === '&') {
			// Return a pointer
			const ptrType = new TypeInfo('', 'pointer', 2);
			ptrType.pointerTo = argType;
			return ptrType;
		}
		
		if (operator === '*') {
			// Return a pointer's pointing-to
			return argType.pointerTo;
		}

		if (operator === '!') {
			return this.typeTable.get('bool');
		}
		
        return argType;
    }

    // 修改isLValue以支持成员访问
    isLValue(node) {
        // 标识符是左值
        if (node.type === 'Identifier') {
            return true;
        }

        // 成员访问是左值
        if (node.type === 'MemberExpression') {
            return true;
        }

        // 解引用是左值
        if (node.type === 'UnaryExpression' && node.operator === '*') {
            return true;
        }

        // 数组下标是左值
        if (node.type === 'MemberExpression' && node.getAttribute('computed')) {
            return true;
        }

        // 其他情况暂时认为不是左值
        return false;
    }

    isNumericType(type) {
        const numericTypes = ['int', 'char', 'short', 'long', 'float', 'double', 'signed', 'unsigned'];
        return numericTypes.includes(type);
    }

    isIntegerType(type) {
        const integerTypes = ['int', 'char', 'short', 'long', 'signed', 'unsigned'];
        return integerTypes.includes(type);
    }

	isLogicalType(type) {
		const logicalTypes = ['bool'];
		return this.isNumericType(type) || logicalTypes.includes(type);
	}

    // 默认访问方法
    visitDefault(node) {
        if (node.children) {
            node.children.forEach(child => this.visit(child));
        }
    }
}